window.__PURENISTA_CONTENT={"ae-comp": "\n    <div class=\"card\">\n      <h3>Composition diagrams <span class=\"tag ok\">At a glance</span></h3>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 180 120\" role=\"img\">\n<rect x=\"1\" y=\"1\" width=\"178\" height=\"118\" rx=\"8\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<g stroke=\"#7B6BB5\" stroke-width=\"1.2\" stroke-dasharray=\"4 4\" opacity=\".85\">\n<line x1=\"60\" y1=\"4\" x2=\"60\" y2=\"116\"/><line x1=\"120\" y1=\"4\" x2=\"120\" y2=\"116\"/>\n<line x1=\"4\" y1=\"40\" x2=\"176\" y2=\"40\"/><line x1=\"4\" y1=\"80\" x2=\"176\" y2=\"80\"/></g>\n<circle cx=\"60\" cy=\"40\" r=\"4\" fill=\"#DDD6E8\"/><circle cx=\"120\" cy=\"80\" r=\"4\" fill=\"#DDD6E8\"/><circle cx=\"60\" cy=\"80\" r=\"4\" fill=\"#DDD6E8\"/>\n<circle cx=\"120\" cy=\"40\" r=\"8\" fill=\"#8A5FC0\"/><circle cx=\"120\" cy=\"40\" r=\"13\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"1.5\" opacity=\".5\"/>\n<text x=\"127\" y=\"32\" font-size=\"9\" fill=\"#2A2138\">Subject</text></svg></div><figcaption>Rule of thirds: place the subject on an intersection</figcaption></figure>\n      <div class=\"dgm-grid\">\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"60\" cy=\"45\" r=\"16\" fill=\"#8A5FC0\"/><line x1=\"60\" y1=\"6\" x2=\"60\" y2=\"84\" stroke=\"#7B6BB5\" stroke-dasharray=\"3 3\" opacity=\".5\"/></svg></div><figcaption>Center · formal, focused</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"12\" y1=\"80\" x2=\"108\" y2=\"14\" stroke=\"#7B6BB5\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\"/><circle cx=\"45\" cy=\"60\" r=\"9\" fill=\"#8A5FC0\"/><circle cx=\"80\" cy=\"36\" r=\"6\" fill=\"#8A5FC0\" opacity=\".55\"/></svg></div><figcaption>Diagonal · motion</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><polygon points=\"60,18 96,74 24,74\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\"/><circle cx=\"60\" cy=\"26\" r=\"8\" fill=\"#8A5FC0\"/><circle cx=\"34\" cy=\"68\" r=\"7\" fill=\"#8A5FC0\" opacity=\".6\"/><circle cx=\"86\" cy=\"68\" r=\"7\" fill=\"#8A5FC0\" opacity=\".6\"/></svg></div><figcaption>Triangle · stability</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"20\" y=\"14\" width=\"80\" height=\"62\" rx=\"6\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"6\" opacity=\".35\"/><circle cx=\"60\" cy=\"45\" r=\"13\" fill=\"#8A5FC0\"/></svg></div><figcaption>Framing · locks the eye</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-width=\"1.4\" opacity=\".7\"><line x1=\"4\" y1=\"86\" x2=\"56\" y2=\"44\"/><line x1=\"116\" y1=\"86\" x2=\"64\" y2=\"44\"/><line x1=\"60\" y1=\"88\" x2=\"60\" y2=\"52\"/></g><circle cx=\"60\" cy=\"38\" r=\"11\" fill=\"#8A5FC0\"/></svg></div><figcaption>Leading lines · guide the gaze</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"92\" cy=\"45\" r=\"12\" fill=\"#8A5FC0\"/><rect x=\"10\" y=\"10\" width=\"60\" height=\"70\" rx=\"6\" fill=\"#7B6BB5\" opacity=\".07\"/><text x=\"18\" y=\"49\" font-size=\"9\" fill=\"#7B6BB5\">Empty</text></svg></div><figcaption>Negative space · lets it breathe</figcaption></figure>\n      </div>\n    </div>\n    <div class=\"card\">\n      <h3>Core composition rules <span class=\"tag gold\">Start here</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">Composition decides where the subject sits and how the eye travels. When in doubt, use the rule of thirds.</p>\n      <details><summary>Rule of thirds</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-dasharray=\"3 3\" opacity=\".8\"><line x1=\"38\" y1=\"4\" x2=\"38\" y2=\"62\"/><line x1=\"73\" y1=\"4\" x2=\"73\" y2=\"62\"/><line x1=\"4\" y1=\"23\" x2=\"106\" y2=\"23\"/><line x1=\"4\" y1=\"43\" x2=\"106\" y2=\"43\"/></g><circle cx=\"73\" cy=\"23\" r=\"7\" fill=\"#8A5FC0\"/></svg></span>Split the frame into three columns and three rows. <b>Put the face, the eyes, or the detail you most want seen on an intersection</b> — it reads more naturally and leaves room to breathe than dead center. The safest, most universal choice.</p></details>\n      <details><summary>Center composition</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"55\" y1=\"6\" x2=\"55\" y2=\"60\" stroke=\"#7B6BB5\" stroke-dasharray=\"3 3\" opacity=\".5\"/><circle cx=\"55\" cy=\"33\" r=\"13\" fill=\"#8A5FC0\"/></svg></span>Subject dead center: <b>bold, formal, focused</b> — great for symmetrical gowns and front-facing portraits. The risk is stiffness; fix it by making the <b>background or accessories asymmetric</b>, or turning the gaze aside.</p></details>\n      <details><summary>Diagonal</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"10\" y1=\"56\" x2=\"100\" y2=\"12\" stroke=\"#7B6BB5\" stroke-width=\"1.4\" stroke-dasharray=\"4 3\"/><circle cx=\"40\" cy=\"42\" r=\"8\" fill=\"#8A5FC0\"/><circle cx=\"72\" cy=\"26\" r=\"5\" fill=\"#8A5FC0\" opacity=\".55\"/></svg></span>Arrange the subject along a diagonal. Slanted lines carry <b>motion and direction</b> — perfect for walking poses, sweeping skirts and ribbons. Livelier than horizontals and verticals.</p></details>\n      <details><summary>Triangle</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><polygon points=\"55,12 92,54 18,54\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"1.4\" stroke-dasharray=\"4 3\"/><circle cx=\"55\" cy=\"20\" r=\"7\" fill=\"#8A5FC0\"/><circle cx=\"26\" cy=\"49\" r=\"6\" fill=\"#8A5FC0\" opacity=\".6\"/><circle cx=\"84\" cy=\"49\" r=\"6\" fill=\"#8A5FC0\" opacity=\".6\"/></svg></span>Subjects form a triangle. <b>Upright = stable, dignified</b> (a seated pose with the skirt spread); <b>inverted = tense, uneasy</b> (great for dark themes). The go-to for two-character shots.</p></details>\n      <details><summary>Framing</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"16\" y=\"10\" width=\"78\" height=\"46\" rx=\"5\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"5\" opacity=\".35\"/><circle cx=\"55\" cy=\"33\" r=\"11\" fill=\"#8A5FC0\"/></svg></span>Use <b>foreground elements to frame the subject</b> — window frames, arches, branches, curtains, hanging flowers. Adds depth, locks the eye onto the figure, and makes the image feel like a story.</p></details>\n      <details><summary>Leading lines</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-width=\"1.3\" opacity=\".7\"><line x1=\"6\" y1=\"60\" x2=\"50\" y2=\"30\"/><line x1=\"104\" y1=\"60\" x2=\"60\" y2=\"30\"/></g><circle cx=\"55\" cy=\"24\" r=\"9\" fill=\"#8A5FC0\"/></svg></span>Use floor lines, stairs, ribbons or light beams to <b>lead the eye to the subject</b>. If a photo doesn&#39;t make clear who the star is, it usually lacks leading lines.</p></details>\n      <details><summary>Negative space</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"82\" cy=\"33\" r=\"11\" fill=\"#8A5FC0\"/><rect x=\"8\" y=\"8\" width=\"52\" height=\"50\" rx=\"5\" fill=\"#7B6BB5\" opacity=\".08\"/></svg></span>You don&#39;t have to fill everything. <b>Generous empty space makes the subject stand out</b> and reads as refined — or lonely. Leave the space <b>in front of where the subject is looking</b>, or it feels walled in.</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>Visual weight &amp; depth <span class=\"tag ok\">Make it stand up</span></h3>\n      <ul class=\"tips\">\n        <li><b>Visual weight</b>dark, saturated, detailed and large things feel \"heavier\". If one side is too heavy the frame tilts — balance it with a <b>small bright</b> element on the other side.</li>\n        <li><b>Three planes</b>put something in the foreground, midground and background (petals → figure → architecture) and the image turns from a sticker into a space.</li>\n        <li><b>Gaze room</b>leave more space on the side the subject faces; the opposite feels cramped.</li>\n        <li><b>Rule of odds</b>1, 3 or 5 elements read more naturally than 2 or 4.</li>\n        <li><b>Don&#39;t crop at joints</b>avoid cutting at wrists, knees and ankles; crop mid-thigh or mid-torso instead.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Advanced composition <span class=\"tag gold\">One level up</span></h3>\n      <details><summary>Golden spiral / Fibonacci</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M92 12 A40 40 0 0 1 92 52 A28 28 0 0 1 44 52 A18 18 0 0 1 62 34 A10 10 0 0 1 62 46\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"1.6\"/><circle cx=\"62\" cy=\"40\" r=\"4\" fill=\"#8A5FC0\"/></svg></span>Repeatedly dividing a golden rectangle forms an <b>inward-curling spiral</b>. Place the subject (or the key detail, like an eye) at the <b>spiral&#39;s focal point</b> and the image gains an inexplicable natural flow. Master paintings and classic photography use it constantly.</p></details>\n      <details><summary>Symmetry &amp; reflection</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"8\" y1=\"33\" x2=\"102\" y2=\"33\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"22\" r=\"9\" fill=\"#8A5FC0\"/><circle cx=\"55\" cy=\"44\" r=\"9\" fill=\"#8A5FC0\" opacity=\".4\"/></svg></span><b>Full symmetry</b> reads as solemn, sacred, ceremonial; a <b>reflection</b> in water or a mirror adds dream and the play of real vs unreal. For mirror themes (like melem), reflection composition could not fit better.</p></details>\n      <details><summary>Fill-the-frame / breaking the edge</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"30\" fill=\"#8A5FC0\"/></svg></span>Let the subject <b>fill the whole frame or spill past the edges</b> and get cropped. It creates strong tension, pressure and intimacy — great for close-ups and high-emotion images. The opposite pole to negative space; both have power.</p></details>\n      <details><summary>The direction of triangles</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><polygon points=\"30,50 88,50 74,16\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\"/></svg></span>Beyond upright (stable) and inverted (uneasy), a <b>leaning triangle</b> adds motion and direction. For group shots, letting the heads form a triangle is the most reliable group pose.</p></details>\n      <details><summary>Foreground frame / tunnel effect</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#7B6BB5\" opacity=\".25\"/><ellipse cx=\"55\" cy=\"33\" rx=\"30\" ry=\"22\" fill=\"#F6F4FB\"/><circle cx=\"55\" cy=\"33\" r=\"11\" fill=\"#8A5FC0\"/></svg></span>Wrap the subject in a large, blurred foreground (foliage, railings, bokeh) for a <b>\"looking through something\" tunnel feel</b>. Depth deepens instantly and the image gains a voyeuristic, storytelling quality.</p></details>\n      <details><summary>Visual rhythm &amp; rest</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"21\" width=\"8\" height=\"24\" rx=\"2\" fill=\"#8A5FC0\" opacity=\".8\"/><rect x=\"23\" y=\"30\" width=\"8\" height=\"6\" rx=\"2\" fill=\"#8A5FC0\" opacity=\".8\"/><rect x=\"36\" y=\"21\" width=\"8\" height=\"24\" rx=\"2\" fill=\"#8A5FC0\" opacity=\".8\"/><rect x=\"49\" y=\"30\" width=\"8\" height=\"6\" rx=\"2\" fill=\"#8A5FC0\" opacity=\".8\"/><rect x=\"62\" y=\"21\" width=\"8\" height=\"24\" rx=\"2\" fill=\"#8A5FC0\" opacity=\".8\"/><rect x=\"75\" y=\"30\" width=\"8\" height=\"6\" rx=\"2\" fill=\"#8A5FC0\" opacity=\".8\"/><rect x=\"88\" y=\"21\" width=\"8\" height=\"24\" rx=\"2\" fill=\"#8A5FC0\" opacity=\".8\"/></svg></span>Good composition is like music: <b>density (detail) and emptiness (rest) should alternate</b>. Filling everything tires the eye; a well-placed \"void\" is the rest that lets the focal point be heard.</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>The full set of composition rules <span class=\"tag hot\">photography x painting x design</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 0\">The same rule is used differently in each field. Photographers first, then painters, then designers.</p>\n    </div>\n    <div class=\"card\">\n      <h3>1. Basic layout <span class=\"tag gold\">where the subject stands</span></h3>\n      <details><summary>Rule of thirds</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-dasharray=\"3 3\" opacity=\".8\"><line x1=\"38\" y1=\"4\" x2=\"38\" y2=\"62\"/><line x1=\"73\" y1=\"4\" x2=\"73\" y2=\"62\"/><line x1=\"4\" y1=\"23\" x2=\"106\" y2=\"23\"/><line x1=\"4\" y1=\"43\" x2=\"106\" y2=\"43\"/></g><circle cx=\"73\" cy=\"23\" r=\"7\" fill=\"#8A5FC0\"/></svg></span><i><b>Photo</b>Keeps the subject off dead centre, on an intersection or along a line, so the frame can breathe.</i><i><b>Paint</b>Used to divide sky from ground and foreground from distance, so the horizon never cuts the picture in half.</i><i><b>Design</b>The invisible skeleton of posters and web pages: logo, headline and buttons sit on the intersections to steer the reading path.</i></p></details>\n      <details><summary>Symmetry</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"55\" y1=\"4\" x2=\"55\" y2=\"62\" stroke=\"#7B6BB5\" stroke-dasharray=\"3 3\" opacity=\".6\"/><circle cx=\"33\" cy=\"33\" r=\"12\" fill=\"#8A5FC0\"/><circle cx=\"77\" cy=\"33\" r=\"12\" fill=\"#8A5FC0\"/></svg></span><i><b>Photo</b>A perfectly level mirror image, most often architecture and reflections, reading as solemn and still.</i><i><b>Paint</b>The core device of religious painting and court portraiture, using absolute symmetry to assert sacred or royal centrality.</i><i><b>Design</b>Luxury marks and invitations live on it; the spine of a book is a natural axis of symmetry, elegant and balanced.</i></p></details>\n      <details><summary>Centred</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"55\" y1=\"6\" x2=\"55\" y2=\"60\" stroke=\"#7B6BB5\" stroke-dasharray=\"3 3\" opacity=\".5\"/><circle cx=\"55\" cy=\"33\" r=\"14\" fill=\"#8A5FC0\"/></svg></span><i><b>Photo</b>Subject dead centre for force, directness and gravity. Common in fashion portraiture and minimalist photography.</i><i><b>Paint</b>The Renaissance icon layout: the most important figure at the absolute centre, everything else arranged around it.</i><i><b>Design</b>The favourite of product posters and album covers, making the subject the single focus in the most literal way.</i></p></details>\n      <details><summary>Diagonal</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"10\" y1=\"56\" x2=\"100\" y2=\"12\" stroke=\"#7B6BB5\" stroke-width=\"1.6\" stroke-dasharray=\"4 3\"/><circle cx=\"40\" cy=\"42\" r=\"8\" fill=\"#8A5FC0\"/><circle cx=\"72\" cy=\"26\" r=\"5\" fill=\"#8A5FC0\" opacity=\".55\"/></svg></span><i><b>Photo</b>A slanting line crossing the frame breaks the stillness and brings speed, movement and extension.</i><i><b>Paint</b>The great Baroque diagonal pushes conflict, motion and drama forward; the eye slides the whole width along it.</i><i><b>Design</b>Tilted headlines and angled colour blocks make a layout instantly livelier, more modern, more forceful.</i></p></details>\n      <details><summary>Horizontal</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-width=\"1.5\" opacity=\".75\"><line x1=\"6\" y1=\"22\" x2=\"104\" y2=\"22\"/><line x1=\"6\" y1=\"38\" x2=\"104\" y2=\"38\"/><line x1=\"6\" y1=\"52\" x2=\"104\" y2=\"52\"/></g></svg></span><i><b>Photo</b>Grassland, sea horizon: calm, wide, stable, time held still.</i><i><b>Paint</b>Stacked horizontals in landscape painting separate near, middle and far, building the most basic sense of depth.</i><i><b>Design</b>Banners and column layouts use horizontals to divide information, keeping the reading rhythm steady and clear.</i></p></details>\n      <details><summary>Vertical</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-width=\"1.5\" opacity=\".75\"><line x1=\"26\" y1=\"6\" x2=\"26\" y2=\"60\"/><line x1=\"46\" y1=\"6\" x2=\"46\" y2=\"60\"/><line x1=\"66\" y1=\"6\" x2=\"66\" y2=\"60\"/><line x1=\"86\" y1=\"6\" x2=\"86\" y2=\"60\"/></g></svg></span><i><b>Photo</b>Forests, towers, colonnades: height, force, uprightness and order.</i><i><b>Paint</b>Gothic altarpieces extend vertically, using standing figures and columns to lift the eye toward heaven.</i><i><b>Design</b>Tall mobile posters and vertical menus follow the direction of reading, giving a continuous, easy path.</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>2. Lines that lead <span class=\"tag ok\">where the eye goes</span></h3>\n      <details><summary>Leading lines</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-width=\"1.3\" opacity=\".75\"><line x1=\"6\" y1=\"60\" x2=\"50\" y2=\"30\"/><line x1=\"104\" y1=\"60\" x2=\"60\" y2=\"30\"/></g><circle cx=\"55\" cy=\"24\" r=\"9\" fill=\"#8A5FC0\"/></svg></span><i><b>Photo</b>Roads, railings and rivers pull the eye naturally toward a distant subject.</i><i><b>Paint</b>Limbs, drapery and spears are aimed deliberately to build an invisible flow of attention onto the protagonist.</i><i><b>Design</b>Arrows, numbers and a model's gaze act as functional signposts, walking the reader to the key message.</i></p></details>\n      <details><summary>Curves (S and C)</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M20 60 C60 52 30 34 55 26 C78 18 60 10 92 8\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"1.8\"/></svg></span><i><b>Photo</b>A winding river or mountain road lets the eye travel slowly and softly, elegant and deep.</i><i><b>Paint</b>Rococo's ornate curves and the S-shaped human pose carry a rhythm of fullness, flow and grace.</i><i><b>Design</b>Timelines and curved typesetting give reading a rise and fall, avoiding the monotony of straight layouts.</i></p></details>\n      <details><summary>Radial</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-width=\"1.2\" opacity=\".8\"><line x1=\"55\" y1=\"33\" x2=\"6\" y2=\"8\"/><line x1=\"55\" y1=\"33\" x2=\"55\" y2=\"4\"/><line x1=\"55\" y1=\"33\" x2=\"104\" y2=\"8\"/><line x1=\"55\" y1=\"33\" x2=\"6\" y2=\"58\"/><line x1=\"55\" y1=\"33\" x2=\"55\" y2=\"62\"/><line x1=\"55\" y1=\"33\" x2=\"104\" y2=\"58\"/><line x1=\"55\" y1=\"33\" x2=\"4\" y2=\"33\"/><line x1=\"55\" y1=\"33\" x2=\"106\" y2=\"33\"/></g><circle cx=\"55\" cy=\"33\" r=\"6\" fill=\"#8A5FC0\"/></svg></span><i><b>Photo</b>Light rays, flower stamens or a tunnel mouth spreading from a centre produce strong convergence or burst.</i><i><b>Paint</b>Renaissance perspective at full stretch: every vanishing line radiates from a single point, pushing space to infinity.</i><i><b>Design</b>Sale posters use radial backgrounds expanding from the headline for explosive visual pull.</i></p></details>\n      <details><summary>Golden spiral / Fibonacci</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M92 12 A40 40 0 0 1 92 52 A28 28 0 0 1 44 52 A18 18 0 0 1 62 34 A10 10 0 0 1 62 46\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"1.6\"/><circle cx=\"62\" cy=\"40\" r=\"4\" fill=\"#8A5FC0\"/></svg></span><i><b>Photo</b>Place the subject at the tight end of the spiral and the eye circles once before landing. Deeply harmonious.</i><i><b>Paint</b>The hidden code old masters used for group scenes: many figures spread along a spiral, busy but never chaotic.</i><i><b>Design</b>Inside logos and circular marks, the golden spiral is used to tune proportions with almost mathematical precision.</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>3. Shapes <span class=\"tag warn\">geometry that ties elements together</span></h3>\n      <details><summary>Triangle</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><polygon points=\"55,12 92,54 18,54\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"1.4\" stroke-dasharray=\"4 3\"/><circle cx=\"55\" cy=\"20\" r=\"7\" fill=\"#8A5FC0\"/><circle cx=\"26\" cy=\"49\" r=\"6\" fill=\"#8A5FC0\" opacity=\".6\"/><circle cx=\"84\" cy=\"49\" r=\"6\" fill=\"#8A5FC0\" opacity=\".6\"/></svg></span><i><b>Photo</b>In a group shot, line the heads into a triangle and the frame turns tight, stable and natural at once.</i><i><b>Paint</b>The universal formula of classical group painting: upright is immovable, inverted is precarious and tense.</i><i><b>Design</b>When the weight feels unstable, a small triangular arrow or geometric accent beside the key text anchors the page.</i></p></details>\n      <details><summary>Circle</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"33\" r=\"24\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\"/><circle cx=\"55\" cy=\"33\" r=\"11\" fill=\"#8A5FC0\"/></svg></span><i><b>Photo</b>Shoot through a round opening or window, or photograph radially symmetric things; the eye circulates inside the ring.</i><i><b>Paint</b>Mandalas and tondo Madonnas: the circle stands for eternity and wholeness, sealing attention into sacred space.</i><i><b>Design</b>App icons and badges lean on the circle: unified, focused, and legible inside any rectangular layout.</i></p></details>\n      <details><summary>Rectangle / L-shape</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M14 8 L14 58 L96 58\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"5\" opacity=\".35\"/><circle cx=\"60\" cy=\"34\" r=\"11\" fill=\"#8A5FC0\"/></svg></span><i><b>Photo</b>A wall corner or door frame forms an L, or light and shadow enclose a rectangle, boxing the eye onto one area.</i><i><b>Paint</b>Interiors and architectural painting use an L of wall and floor to define space while leaving one side open to breathe.</i><i><b>Design</b>Text and image often run along an L: headline across the top, sub-copy down the left, enclosing the subject yet leaving air.</i></p></details>\n      <details><summary>Cross</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"6\" y1=\"33\" x2=\"104\" y2=\"33\" stroke=\"#7B6BB5\" stroke-width=\"1.6\"/><line x1=\"55\" y1=\"4\" x2=\"55\" y2=\"62\" stroke=\"#7B6BB5\" stroke-width=\"1.6\"/><circle cx=\"55\" cy=\"33\" r=\"6\" fill=\"#8A5FC0\"/></svg></span><i><b>Photo</b>A horizon meeting a vertical trunk or lamp post makes a solid cross, settled and almost devotional.</i><i><b>Paint</b>In religious painting the cross echoes the crucifix; even a landscape can carry that stillness on a hidden cross axis.</i><i><b>Design</b>On a minimal poster, one horizontal and one vertical crossing is enough to bring complex elements to order.</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>4. Space and depth <span class=\"tag ok\">turning a flat plane into a room</span></h3>\n      <details><summary>Foreground layer</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"30\" r=\"12\" fill=\"#8A5FC0\"/><path d=\"M2 66 C24 44 34 60 46 66 Z\" fill=\"#7B6BB5\" opacity=\".55\"/><path d=\"M108 66 C86 42 74 58 62 66 Z\" fill=\"#7B6BB5\" opacity=\".55\"/></svg></span><i><b>Photo</b>Deliberately place grass, stone or a blurred figure in front of the lens to break the flatness and add depth.</i><i><b>Paint</b>A large dark foreground silhouette (branches, a portico) pushes the mid-ground figure and far landscape back several layers.</i><i><b>Design</b>In a composite, blurred bokeh or leaves laid in front instantly give flat assets a front, middle and back.</i></p></details>\n      <details><summary>Framing</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"16\" y=\"10\" width=\"78\" height=\"46\" rx=\"5\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"5\" opacity=\".35\"/><circle cx=\"55\" cy=\"33\" r=\"11\" fill=\"#8A5FC0\"/></svg></span><i><b>Photo</b>Shoot the distance through a doorway, arch or hollow tree for a picture-within-a-picture that shuts out the clutter.</i><i><b>Paint</b>A window or arch behind a portrait does more than frame the sitter: it implies a story between inside and outside.</i><i><b>Design</b>Modals and thumbnail previews are framing logic: they separate levels so you can focus on the current task.</i></p></details>\n      <details><summary>Negative space</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"86\" cy=\"33\" r=\"10\" fill=\"#8A5FC0\"/><rect x=\"8\" y=\"8\" width=\"56\" height=\"50\" rx=\"5\" fill=\"#7B6BB5\" opacity=\".08\"/></svg></span><i><b>Photo</b>Vast sky, water or white wall with a tiny subject: minimal, solitary, weightless.</i><i><b>Paint</b>Ink painting treats the unpainted as painted; what is left blank may be cloud, water, sky, and above all extended meaning.</i><i><b>Design</b>In luxury advertising, generous white space IS the sense of quality, and the breathing room that makes the key line land.</i></p></details>\n      <details><summary>Fill the frame</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"34\" fill=\"#8A5FC0\"/></svg></span><i><b>Photo</b>Extreme close-up or macro, the subject filling and bursting the border, stripping out background for pressure and intimacy.</i><i><b>Paint</b>Hyperreal portraiture fills the canvas with pores and hair, collapsing distance into an almost uncomfortable stare.</i><i><b>Design</b>Magazine cover close-ups and enlarged product details use overflow tension to say \"right in front of you\".</i></p></details>\n      <details><summary>Layered overlays</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"14\" y=\"12\" width=\"52\" height=\"42\" rx=\"4\" fill=\"#8A5FC0\" opacity=\".55\"/><rect x=\"44\" y=\"22\" width=\"52\" height=\"34\" rx=\"4\" fill=\"#7B6BB5\" opacity=\".45\"/></svg></span><i><b>Photo</b>Glass reflections and double exposure compress separate spaces into one frame, real and unreal interleaved.</i><i><b>Paint</b>Transparent glazes laid over one another let the underpainting show through, a subtle lustre photography cannot copy.</i><i><b>Design</b>A translucent block over the image with the type on top keeps the photograph's mood and the text's legibility.</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>5. Motion and tension <span class=\"tag hot\">unsettling the frame on purpose</span></h3>\n      <details><summary>Dutch angle</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"6\" y1=\"46\" x2=\"104\" y2=\"20\" stroke=\"#7B6BB5\" stroke-width=\"1.8\"/><rect x=\"42\" y=\"14\" width=\"16\" height=\"26\" rx=\"3\" fill=\"#8A5FC0\" transform=\"rotate(-15 50 27)\"/></svg></span><i><b>Photo</b>Tilting the horizon deliberately creates unease, weightlessness, disorder and tension. Common in film and street work.</i><i><b>Paint</b>Expressionism and Futurism used slanted strokes and layouts to carry emotional agitation or urban speed and vertigo.</i><i><b>Design</b>Sportswear and streetwear posters use tilted typesetting to inject kinetic energy and defiance.</i></p></details>\n      <details><summary>Pattern and its break</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g fill=\"#7B6BB5\" opacity=\".7\"><rect x=\"12\" y=\"14\" width=\"14\" height=\"14\" rx=\"3\"/><rect x=\"32\" y=\"14\" width=\"14\" height=\"14\" rx=\"3\"/><rect x=\"52\" y=\"14\" width=\"14\" height=\"14\" rx=\"3\"/><rect x=\"72\" y=\"14\" width=\"14\" height=\"14\" rx=\"3\"/><rect x=\"12\" y=\"38\" width=\"14\" height=\"14\" rx=\"3\"/><rect x=\"32\" y=\"38\" width=\"14\" height=\"14\" rx=\"3\"/><rect x=\"72\" y=\"38\" width=\"14\" height=\"14\" rx=\"3\"/></g><rect x=\"52\" y=\"38\" width=\"14\" height=\"14\" rx=\"3\" fill=\"#E08A3C\"/></svg></span><i><b>Photo</b>Among a run of identical windows or chairs, one element of another colour or direction becomes a visual bomb.</i><i><b>Paint</b>Pop art's favourite: repeat, then insert an outlier into the grid so the repetition itself sharpens the difference.</i><i><b>Design</b>In a tidy icon array, letting the featured item change colour or scale uses the broken rhythm to drive the click.</i></p></details>\n      <details><summary>Gaze room</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"34\" cy=\"33\" r=\"12\" fill=\"#8A5FC0\"/><g stroke=\"#7B6BB5\" stroke-width=\"1.2\" stroke-dasharray=\"3 3\"><line x1=\"48\" y1=\"30\" x2=\"96\" y2=\"26\"/></g><rect x=\"60\" y=\"8\" width=\"42\" height=\"50\" rx=\"4\" fill=\"#7B6BB5\" opacity=\".08\"/></svg></span><i><b>Photo</b>Leave more space on the side a person or animal is looking toward and the viewer follows the look without thinking.</i><i><b>Paint</b>In a group painting the sitters' sightlines form an invisible network telling you who the real protagonist is.</i><i><b>Design</b>A model on a banner looking straight at the copy or the button is the highest-converting gaze cue there is.</i></p></details>\n      <details><summary>Edge tension</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"14\" cy=\"33\" r=\"11\" fill=\"#8A5FC0\"/><rect x=\"34\" y=\"8\" width=\"68\" height=\"50\" rx=\"5\" fill=\"#7B6BB5\" opacity=\".07\"/></svg></span><i><b>Photo</b>Push the subject to the extreme edge and empty the centre: imbalance producing very strong psychological tension.</i><i><b>Paint</b>The figure pressed against the frame with space behind, as if about to be squeezed out or to enter the unknown.</i><i><b>Design</b>Key copy in the corner of a poster breaks the comfort zone, which is exactly what earns curiosity from a younger audience.</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>6. Special and experimental <span class=\"tag gold\">learn the rules, then break them</span></h3>\n      <details><summary>Multi-point perspective</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"1.2\"><rect x=\"10\" y=\"12\" width=\"22\" height=\"16\" rx=\"3\"/><rect x=\"44\" y=\"30\" width=\"22\" height=\"16\" rx=\"3\"/><rect x=\"76\" y=\"14\" width=\"22\" height=\"16\" rx=\"3\"/><rect x=\"24\" y=\"44\" width=\"22\" height=\"14\" rx=\"3\"/></g></svg></span><i><b>Photo</b>Stitching or tilt-shift removes the single vanishing point; near and far stay sharp, giving a miniature or flattened surreality.</i><i><b>Paint</b>The core perspective of the Chinese handscroll: not one fixed viewpoint but a moving one, placing different times and places in one picture.</i><i><b>Design</b>Infographics and illustrated maps abandon unified perspective so each icon shows its clearest angle, serving explanation over realism.</i></p></details>\n      <details><summary>Film border / frame within a frame</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"6\" width=\"94\" height=\"54\" rx=\"3\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"4\" opacity=\".45\"/><rect x=\"20\" y=\"14\" width=\"70\" height=\"38\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".25\"/><circle cx=\"55\" cy=\"33\" r=\"9\" fill=\"#8A5FC0\"/></svg></span><i><b>Photo</b>Deliberately including sprocket holes, an instant-film border or a screen's viewfinder insists \"this is an image being looked at\".</i><i><b>Paint</b>The meta device of the picture-within-a-picture: Velazquez's Las Meninas frames canvas, mirror and doorway together to question the real.</i><i><b>Design</b>Simulating a Polaroid border or a browser screenshot in a layout creates the feel of a casual record, or of retro nostalgia.</i></p></details>\n      <details><summary>Random / organic (de-composition)</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g fill=\"#8A5FC0\" opacity=\".6\"><circle cx=\"24\" cy=\"20\" r=\"7\"/><circle cx=\"70\" cy=\"14\" r=\"5\"/><circle cx=\"44\" cy=\"42\" r=\"9\"/><circle cx=\"88\" cy=\"46\" r=\"6\"/><circle cx=\"16\" cy=\"50\" r=\"4\"/></g></svg></span><i><b>Photo</b>The unthinking eye of street photography: apparently casual, no clear subject, yet catching the tangled poetry of life.</i><i><b>Paint</b>Abstract Expressionist pouring: Pollock let paint fall freely, abandoning composition so the work records a field of energy.</i><i><b>Design</b>Deconstructivist posters fragment, overlap and scramble type, refusing easy reading to state a position through anti-composition.</i></p></details>\n    </div>\n    <div class=\"card\">\n      <p class=\"cond\" style=\"margin:0\">None of these is a rule to obey; each is a tool for understanding visual logic. The analyser above now recognises more than a dozen of these patterns and reports how strongly the frame matches each one. Once you know them all you can use them at will, and break them deliberately to make something new.</p>\n    </div>\n", "ae-prin": "\n    <div class=\"card\">\n      <h3>Gestalt diagrams <span class=\"tag ok\">How we group</span></h3>\n      <div class=\"dgm-grid\">\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"22\" cy=\"32\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"36\" cy=\"32\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"29\" cy=\"48\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"22\" cy=\"64\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"36\" cy=\"64\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"84\" cy=\"32\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"98\" cy=\"32\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"91\" cy=\"48\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"84\" cy=\"64\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"98\" cy=\"64\" r=\"5\" fill=\"#7B6BB5\"/></svg></div><figcaption>Proximity: close = one group</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"24\" cy=\"28\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"48\" cy=\"28\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"72\" cy=\"28\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"96\" cy=\"28\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"24\" cy=\"62\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"72\" cy=\"62\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"96\" cy=\"62\" r=\"5\" fill=\"#7B6BB5\"/><rect x=\"42\" y=\"56\" width=\"12\" height=\"12\" rx=\"2\" fill=\"#8A5FC0\"/></svg></div><figcaption>Similarity: the odd one = emphasis</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"4\" stroke-linecap=\"round\"><path d=\"M60 20 A25 25 0 0 1 85 45\"/><path d=\"M85 45 A25 25 0 0 1 60 70\"/><path d=\"M60 70 A25 25 0 0 1 35 45\"/></g><text x=\"47\" y=\"49\" font-size=\"8\" fill=\"#DDD6E8\">?</text></svg></div><figcaption>Closure: the gap gets filled in</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M8 70 Q60 8 112 70\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"1.4\" stroke-dasharray=\"3 3\" opacity=\".6\"/><circle cx=\"14\" cy=\"64\" r=\"4\" fill=\"#8A5FC0\"/><circle cx=\"34\" cy=\"40\" r=\"4\" fill=\"#8A5FC0\"/><circle cx=\"60\" cy=\"26\" r=\"4\" fill=\"#8A5FC0\"/><circle cx=\"86\" cy=\"40\" r=\"4\" fill=\"#8A5FC0\"/><circle cx=\"106\" cy=\"64\" r=\"4\" fill=\"#8A5FC0\"/></svg></div><figcaption>Continuity: the eye follows the line</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"8\" width=\"104\" height=\"74\" rx=\"6\" fill=\"#2A2138\"/><circle cx=\"60\" cy=\"45\" r=\"20\" fill=\"#F6F4FB\"/></svg></div><figcaption>Figure–ground: contrast separates subject</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-width=\"2\" stroke-linecap=\"round\" opacity=\".8\"><path d=\"M18 26 l14 8\"/><path d=\"M18 46 l14 8\"/><path d=\"M18 66 l14 8\"/><path d=\"M58 22 l14 8\"/><path d=\"M58 42 l14 8\"/><path d=\"M58 62 l14 8\"/></g><text x=\"86\" y=\"49\" font-size=\"9\" fill=\"#8A5FC0\">→</text></svg></div><figcaption>Common fate: same direction = one group</figcaption></figure>\n      </div>\n    </div>\n    <div class=\"card\">\n      <h3>Principles of design <span class=\"tag gold\">The shared language</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">Almost everything that looks good obeys these. They apply to outfits, layouts and photos alike.</p>\n      <details><summary>Unity &amp; variety</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"24\" cy=\"24\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"40\" cy=\"24\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"56\" cy=\"24\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"24\" cy=\"42\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"40\" cy=\"42\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"56\" cy=\"42\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"82\" cy=\"33\" r=\"8\" fill=\"#B8892E\"/></svg></span><b>The central principle.</b> Unity = shared elements (one palette, one material, one style) hold it together; variety = differences keep it interesting.<br>All unity → dull; all variety → chaos. The answer is <b>big unity, small variety</b>: keep the palette unified and let one or two accents vary.</p></details>\n      <details><summary>Balance</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"38\" cy=\"34\" r=\"12\" fill=\"#8A5FC0\"/><circle cx=\"80\" cy=\"34\" r=\"12\" fill=\"#8A5FC0\"/><line x1=\"59\" y1=\"8\" x2=\"59\" y2=\"58\" stroke=\"#DDD6E8\" stroke-dasharray=\"3 3\"/></svg></span><b>Symmetrical</b>: identical halves — formal, dignified, classical (gowns, crowns, cathedrals).<br><b>Asymmetrical</b>: different halves of equal visual weight — lively, natural, modern.<br><b>Radial</b>: radiating from a center — emphasizes the middle, feels opulent.</p></details>\n      <details><summary>Proportion (golden ratio / thirds)</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"20\" y=\"12\" width=\"70\" height=\"16\" rx=\"3\" fill=\"#7B6BB5\" opacity=\".4\"/><rect x=\"20\" y=\"30\" width=\"70\" height=\"30\" rx=\"3\" fill=\"#8A5FC0\"/></svg></span>The golden ratio is about <b>1:1.618</b>, long considered the most pleasing division. In practice the <b>rule of thirds (1:2)</b> approximates it fine. Apply it to top/bottom of an outfit, head-to-body ratio, or subject-to-empty-space.</p></details>\n      <details><summary>Rhythm</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"18\" cy=\"33\" r=\"4.0\" fill=\"#8A5FC0\" opacity=\".8\"/><circle cx=\"33\" cy=\"33\" r=\"5.4\" fill=\"#8A5FC0\" opacity=\".8\"/><circle cx=\"48\" cy=\"33\" r=\"6.8\" fill=\"#8A5FC0\" opacity=\".8\"/><circle cx=\"63\" cy=\"33\" r=\"8.2\" fill=\"#8A5FC0\" opacity=\".8\"/><circle cx=\"78\" cy=\"33\" r=\"9.6\" fill=\"#8A5FC0\" opacity=\".8\"/><circle cx=\"93\" cy=\"33\" r=\"11.0\" fill=\"#8A5FC0\" opacity=\".8\"/></svg></span><b>Repetition</b> of an element creates rhythm (a row of lace, repeated butterflies); <b>gradation</b> of size or color creates flow (flowers scattering large to small). It keeps the eye moving — key to ornate styling.</p></details>\n      <details><summary>Contrast</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#2A2138\"/><circle cx=\"55\" cy=\"33\" r=\"13\" fill=\"#F3E9C0\"/></svg></span>Difference makes the point pop — <b>light/dark, warm/cool, big/small, dense/sparse, still/moving</b>. A flat image usually just lacks contrast; <b>dark background + bright subject</b> is the fastest fix.</p></details>\n      <details><summary>Harmony</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"14\" y=\"22\" width=\"15\" height=\"22\" rx=\"3\" fill=\"#6E5FA8\"/><rect x=\"31\" y=\"22\" width=\"15\" height=\"22\" rx=\"3\" fill=\"#7E6FB4\"/><rect x=\"48\" y=\"22\" width=\"15\" height=\"22\" rx=\"3\" fill=\"#8E80C0\"/><rect x=\"65\" y=\"22\" width=\"15\" height=\"22\" rx=\"3\" fill=\"#9E90CC\"/><rect x=\"82\" y=\"22\" width=\"15\" height=\"22\" rx=\"3\" fill=\"#AEA0D8\"/></svg></span>The opposite of contrast: keep elements <b>close to each other</b>. Adjacent hues (blue + blue-violet), shared materials or values all create harmony. When contrast runs wild, harmony reins it in.</p></details>\n      <details><summary>Emphasis (dominance)</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"24\" cy=\"24\" r=\"5\" fill=\"#DDD6E8\"/><circle cx=\"44\" cy=\"24\" r=\"5\" fill=\"#DDD6E8\"/><circle cx=\"86\" cy=\"24\" r=\"5\" fill=\"#DDD6E8\"/><circle cx=\"24\" cy=\"44\" r=\"5\" fill=\"#DDD6E8\"/><circle cx=\"44\" cy=\"44\" r=\"5\" fill=\"#DDD6E8\"/><circle cx=\"86\" cy=\"44\" r=\"5\" fill=\"#DDD6E8\"/><circle cx=\"65\" cy=\"34\" r=\"9\" fill=\"#8A5FC0\"/></svg></span>An image can have <b>only one star</b>. Once you pick it, everything else must yield — desaturate, shrink, blur or push it to the edge. Emphasizing everything emphasizes nothing.</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>Less is more <span class=\"tag hot\">Less is More</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">Mies van der Rohe&#39;s dictum. <b>It isn&#39;t \"fewer is better\" — it&#39;s \"everything left must earn its place\"</b>. Cut until you can&#39;t, and what remains carries weight.</p>\n      <ul class=\"tips\">\n        <li><b>Why it works</b>fewer elements means <b>more attention each</b>; a cleaner frame makes the subject louder.</li>\n        <li><b>How to decide</b>ask: if I remove it, does the message weaken? No → cut it. <b>Optional = delete.</b></li>\n        <li><b>Three places to restrain</b>① number of accessories ② number of colors (aim for ≤3) ③ number of typefaces (≤2).</li>\n        <li><b>Empty space isn&#39;t waste</b>it&#39;s part of the design — it gives the subject room to breathe and reads as refined.</li>\n        <li><b>But avoid emptiness</b>less ≠ careless. What remains must be <b>better in quality and more precisely placed</b>, or it&#39;s just sparse.</li>\n        <li><b>The counterpoint</b>\"Less is a bore\" — postmodernism&#39;s reply. <b>Ornate maximalism is also beauty</b>; it just needs stronger unity and order to hold together.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Gestalt principles <span class=\"tag hot\">Gestalt</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">German <i>Gestalt</i> = \"whole form\". The core claim: <b>the whole is greater than the sum of its parts</b> — the brain automatically organizes scattered elements <b>into meaningful wholes</b>. This is the psychology under every layout and composition.</p>\n      <details><summary>Proximity</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"20\" cy=\"24\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"32\" cy=\"24\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"26\" cy=\"42\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"78\" cy=\"24\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"90\" cy=\"24\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"84\" cy=\"42\" r=\"4\" fill=\"#7B6BB5\"/></svg></span><b>Things placed close together read as one group.</b> This is the strongest grouping force — stronger than color or borders.<br>Use it: to relate two things, move them closer; to separate, pull them apart. Messy layouts usually have <b>related things too far apart and unrelated things too close</b>.</p></details>\n      <details><summary>Similarity</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"22\" cy=\"26\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"42\" cy=\"26\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"62\" cy=\"26\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"82\" cy=\"26\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"22\" cy=\"46\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"62\" cy=\"46\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"82\" cy=\"46\" r=\"4\" fill=\"#7B6BB5\"/><rect x=\"37\" y=\"41\" width=\"10\" height=\"10\" rx=\"2\" fill=\"#8A5FC0\"/></svg></span><b>Things that look alike read as the same kind</b> (same color, shape, size, orientation).<br>Use it: mark related items with one color; conversely, <b>breaking similarity creates emphasis</b> (one red bloom in a field of white).</p></details>\n      <details><summary>Closure</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"4\" stroke-linecap=\"round\"><path d=\"M55 16 A18 18 0 0 1 73 34\"/><path d=\"M73 34 A18 18 0 0 1 55 52\"/><path d=\"M55 52 A18 18 0 0 1 37 34\"/></g></svg></span><b>The brain fills in gaps</b>, seeing incomplete shapes as complete.<br>Use it: you don&#39;t need to draw the whole outline — implied edges read as more refined (many logos work this way). A figure partly hidden by foreground is still mentally completed.</p></details>\n      <details><summary>Continuity</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M6 54 Q55 8 104 54\" fill=\"none\" stroke=\"#7B6BB5\" stroke-dasharray=\"3 3\" opacity=\".6\"/><circle cx=\"12\" cy=\"50\" r=\"3.4\" fill=\"#8A5FC0\"/><circle cx=\"34\" cy=\"28\" r=\"3.4\" fill=\"#8A5FC0\"/><circle cx=\"55\" cy=\"20\" r=\"3.4\" fill=\"#8A5FC0\"/><circle cx=\"76\" cy=\"28\" r=\"3.4\" fill=\"#8A5FC0\"/><circle cx=\"98\" cy=\"50\" r=\"3.4\" fill=\"#8A5FC0\"/></svg></span><b>The eye keeps traveling along a line or curve</b>, even continuing across breaks.<br>Use it: this is the psychology behind leading lines — arrange elements along an invisible line and the gaze follows it.</p></details>\n      <details><summary>Common fate</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-width=\"2\" stroke-linecap=\"round\" opacity=\".8\"><path d=\"M16 20 l12 6\"/><path d=\"M16 34 l12 6\"/><path d=\"M16 48 l12 6\"/><path d=\"M52 20 l12 6\"/><path d=\"M52 34 l12 6\"/></g><text x=\"82\" y=\"39\" font-size=\"11\" fill=\"#8A5FC0\">→</text></svg></span><b>Elements moving (or pointing) the same way read as a group.</b><br>Use it: petals, hair and hems drifting in one direction give the frame a unified motion — let everything ride \"the same wind\" and it instantly coheres.</p></details>\n      <details><summary>Figure–ground</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#2A2138\"/><circle cx=\"55\" cy=\"33\" r=\"16\" fill=\"#F6F4FB\"/></svg></span><b>The brain splits any image into subject (figure) and background (ground).</b> With weak contrast it gets confused and the subject sinks into the backdrop.<br>Use it: ensure a clear difference in <b>value, saturation or sharpness</b>. <b>Rubin&#39;s vase</b> (a vase or two faces) is the famous figure-ground reversal.</p></details>\n      <details><summary>Prägnanz (good figure)</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"33\" r=\"15\" fill=\"#8A5FC0\"/></svg></span>Gestalt&#39;s overarching law: <b>we interpret what we see in the simplest, most stable way possible.</b><br>Use it: simpler shapes are easier to remember and more comfortable to look at. This is <b>the scientific basis of \"less is more\"</b> — complexity taxes the brain.</p></details>\n      <details><summary>Symmetry</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"55\" y1=\"6\" x2=\"55\" y2=\"60\" stroke=\"#DDD6E8\" stroke-dasharray=\"3 3\"/><circle cx=\"38\" cy=\"33\" r=\"10\" fill=\"#8A5FC0\"/><circle cx=\"72\" cy=\"33\" r=\"10\" fill=\"#8A5FC0\"/></svg></span><b>Symmetrical elements read as a group and feel stable and complete.</b><br>Use it: symmetry brings dignity and order (gowns, thrones, cathedrals); beware stiffness — break it with <b>asymmetric details</b>.</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>Design principle diagrams <span class=\"tag ok\">Balance · contrast · ratio</span></h3>\n      <div class=\"dgm-grid\"><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 82\"><rect width=\"120\" height=\"82\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"60\" y1=\"6\" x2=\"60\" y2=\"76\" stroke=\"#DDD6E8\" stroke-dasharray=\"2 3\"/><circle cx=\"40\" cy=\"45\" r=\"14\" fill=\"#8A5FC0\"/><circle cx=\"80\" cy=\"45\" r=\"14\" fill=\"#8A5FC0\"/><text x=\"8\" y=\"76\" font-size=\"10\" fill=\"#2A2138\">Symmetry</text></svg></div><figcaption>Symmetrical</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 82\"><rect width=\"120\" height=\"82\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"60\" y1=\"6\" x2=\"60\" y2=\"76\" stroke=\"#DDD6E8\" stroke-dasharray=\"2 3\"/><circle cx=\"38\" cy=\"45\" r=\"18\" fill=\"#8A5FC0\"/><circle cx=\"86\" cy=\"38\" r=\"7\" fill=\"#8A5FC0\"/><circle cx=\"82\" cy=\"58\" r=\"5\" fill=\"#7B6BB5\"/><text x=\"8\" y=\"76\" font-size=\"10\" fill=\"#2A2138\">Asymmetry</text></svg></div><figcaption>非Symmetrical</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 82\"><rect width=\"120\" height=\"82\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"60\" y1=\"6\" x2=\"60\" y2=\"76\" stroke=\"#DDD6E8\" stroke-dasharray=\"2 3\"/><circle cx=\"82.0\" cy=\"45.0\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"71.0000168525543\" cy=\"64.05254915342096\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"49.00003370513441\" cy=\"64.05257834288632\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"38.000000000077456\" cy=\"45.00005837897546\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"48.99993258983446\" cy=\"25.947480036178575\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"70.99991573709944\" cy=\"25.947392467782475\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"60\" cy=\"45\" r=\"9\" fill=\"#8A5FC0\"/><text x=\"8\" y=\"76\" font-size=\"10\" fill=\"#2A2138\">Radial</text></svg></div><figcaption>Radial</figcaption></figure></div>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 200 70\"><rect width=\"200\" height=\"70\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<rect x=\"8\" y=\"12\" width=\"86\" height=\"46\" rx=\"5\" fill=\"#CFC7E0\"/><circle cx=\"51\" cy=\"35\" r=\"10\" fill=\"#C3BAD8\"/><text x=\"14\" y=\"24\" font-size=\"9\" fill=\"#8880A0\">✗ weak contrast</text>\n<rect x=\"106\" y=\"12\" width=\"86\" height=\"46\" rx=\"5\" fill=\"#22182E\"/><circle cx=\"149\" cy=\"35\" r=\"10\" fill=\"#F3ECFA\"/><text x=\"112\" y=\"24\" font-size=\"9\" fill=\"#B0A6C8\">✓ dark + bright</text></svg></div><figcaption>Contrast: dark ground + bright subject</figcaption></figure>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 200 60\"><rect width=\"200\" height=\"60\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<rect x=\"8\" y=\"16\" width=\"88\" height=\"28\" rx=\"4\" fill=\"#D6CEE8\"/><line x1=\"52\" y1=\"16\" x2=\"52\" y2=\"44\" stroke=\"#C0554E\" stroke-width=\"2\"/><text x=\"14\" y=\"55\" font-size=\"9\" fill=\"#C0554E\">✗ halved · stiff</text>\n<rect x=\"106\" y=\"16\" width=\"88\" height=\"28\" rx=\"4\" fill=\"#D6CEE8\"/><line x1=\"164\" y1=\"16\" x2=\"164\" y2=\"44\" stroke=\"#3D8E8A\" stroke-width=\"2\"/><text x=\"112\" y=\"55\" font-size=\"9\" fill=\"#3D8E8A\">✓ 1:2 (thirds)</text></svg></div><figcaption>Proportion: a third beats halving</figcaption></figure>\n    </div>\n    <div class=\"card\">\n      <h3>Design-principle diagrams (2) <span class=\"tag ok\">Figure-ground · ratio</span></h3>\n      <div class=\"dgm-grid\"><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\"><rect width=\"120\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"60\" y1=\"10\" x2=\"60\" y2=\"72\" stroke=\"#DDD6E8\" stroke-dasharray=\"3 3\"/><circle cx=\"38\" cy=\"40\" r=\"13\" fill=\"#8A5FC0\"/><circle cx=\"82\" cy=\"40\" r=\"13\" fill=\"#8A5FC0\"/><text x=\"60\" y=\"84\" font-size=\"9.5\" fill=\"#2A2138\" text-anchor=\"middle\">Symmetry</text></svg></div><figcaption>Symmetrical</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\"><rect width=\"120\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"60\" y1=\"10\" x2=\"60\" y2=\"72\" stroke=\"#DDD6E8\" stroke-dasharray=\"3 3\"/><circle cx=\"36\" cy=\"40\" r=\"16\" fill=\"#8A5FC0\"/><circle cx=\"86\" cy=\"34\" r=\"7\" fill=\"#7B6BB5\"/><circle cx=\"88\" cy=\"52\" r=\"5\" fill=\"#7B6BB5\"/><text x=\"60\" y=\"84\" font-size=\"9.5\" fill=\"#2A2138\" text-anchor=\"middle\">Asymmetry</text></svg></div><figcaption>非Symmetrical</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\"><rect width=\"120\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"60\" y1=\"10\" x2=\"60\" y2=\"72\" stroke=\"#DDD6E8\" stroke-dasharray=\"3 3\"/><line x1=\"60\" y1=\"40\" x2=\"88.0\" y2=\"40.0\" stroke=\"#7B6BB5\" stroke-width=\"2\"/><line x1=\"60\" y1=\"40\" x2=\"79.79898987322333\" y2=\"59.79898987322333\" stroke=\"#7B6BB5\" stroke-width=\"2\"/><line x1=\"60\" y1=\"40\" x2=\"60.0\" y2=\"68.0\" stroke=\"#7B6BB5\" stroke-width=\"2\"/><line x1=\"60\" y1=\"40\" x2=\"40.20101012677667\" y2=\"59.798989873223334\" stroke=\"#7B6BB5\" stroke-width=\"2\"/><line x1=\"60\" y1=\"40\" x2=\"32.0\" y2=\"40.0\" stroke=\"#7B6BB5\" stroke-width=\"2\"/><line x1=\"60\" y1=\"40\" x2=\"40.201010126776666\" y2=\"20.201010126776673\" stroke=\"#7B6BB5\" stroke-width=\"2\"/><line x1=\"60\" y1=\"40\" x2=\"59.99999999999999\" y2=\"12.0\" stroke=\"#7B6BB5\" stroke-width=\"2\"/><line x1=\"60\" y1=\"40\" x2=\"79.79898987322332\" y2=\"20.201010126776666\" stroke=\"#7B6BB5\" stroke-width=\"2\"/><circle cx=\"60\" cy=\"40\" r=\"8\" fill=\"#8A5FC0\"/><text x=\"60\" y=\"84\" font-size=\"9.5\" fill=\"#2A2138\" text-anchor=\"middle\">Radial</text></svg></div><figcaption>Radial</figcaption></figure></div>\n      <div class=\"dgm-grid\"><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\"><rect width=\"120\" height=\"90\" rx=\"7\" fill=\"#2A2138\"/><circle cx=\"60\" cy=\"42\" r=\"15\" fill=\"#F3E9C0\"/><text x=\"60\" y=\"80\" font-size=\"9.5\" fill=\"#fff\" text-anchor=\"middle\">Contrast · dark sets off light</text></svg></div><figcaption>Contrast</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\"><rect width=\"120\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<rect x=\"20\" y=\"14\" width=\"80\" height=\"20\" rx=\"3\" fill=\"#7B6BB5\" opacity=\".4\"/><rect x=\"20\" y=\"36\" width=\"80\" height=\"40\" rx=\"3\" fill=\"#8A5FC0\"/>\n<text x=\"60\" y=\"86\" font-size=\"9.5\" fill=\"#2A2138\" text-anchor=\"middle\">Ratio · 1:2 thirds</text></svg></div><figcaption>Ratio</figcaption></figure></div>\n    </div>\n    <div class=\"card\">\n      <h3>Advanced design principles <span class=\"tag gold\">What pros use</span></h3>\n      <details><summary>Tension</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"40\" cy=\"33\" r=\"14\" fill=\"#8A5FC0\"/><circle cx=\"72\" cy=\"33\" r=\"14\" fill=\"#7B6BB5\"/><line x1=\"55\" y1=\"20\" x2=\"55\" y2=\"46\" stroke=\"#C0554E\" stroke-dasharray=\"2 2\" opacity=\".5\"/></svg></span>Placing elements <b>almost-but-not-quite touching</b>, or nearly off the edge, creates a psychological tension that makes an image feel alive. Dead center is the least tense; a <b>deliberate imbalance</b> grips more.</p></details>\n      <details><summary>Movement / direction</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M14 50 Q55 10 98 40\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"2.4\" marker-end=\"url(#am)\"/><defs><marker id=\"am\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\"><path d=\"M0 0 L7 3.5 L0 7 z\" fill=\"#8A5FC0\"/></marker></defs></svg></span>Use directional elements (diagonal lines, a gaze, an outstretched hand, flowing fabric) to build <b>\"invisible arrows\"</b> that pull the eye through the frame. Even a still image can have flow.</p></details>\n      <details><summary>Depth</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"24\" width=\"90\" height=\"30\" rx=\"4\" fill=\"#7B6BB5\" opacity=\".25\"/><rect x=\"26\" y=\"30\" width=\"60\" height=\"24\" rx=\"4\" fill=\"#7B6BB5\" opacity=\".5\"/><rect x=\"44\" y=\"34\" width=\"24\" height=\"24\" rx=\"5\" fill=\"#8A5FC0\"/></svg></span>Give the foreground, midground and background their own content and separate them with <b>focus, value, temperature and size</b>. The flat surface gains a space you can \"enter\" — one of the clearest gaps between amateur and pro.</p></details>\n      <details><summary>Texture contrast</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"16\" width=\"44\" height=\"34\" rx=\"4\" fill=\"#7B6BB5\" opacity=\".3\"/><rect x=\"58\" y=\"16\" width=\"44\" height=\"34\" rx=\"4\" fill=\"#2A2138\"/></svg></span>Juxtapose coarse and fine, smooth and rough, hard and soft to boost richness and tactility. All-one-texture reads flat; <b>one contrasting texture can rescue a whole image</b>.</p></details>\n      <details><summary>Simplification &amp; selection</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"33\" r=\"12\" fill=\"#8A5FC0\"/></svg></span>Half of design is deciding what to include; the other half is <b>deciding what to remove</b>. Strong work is usually not added up but <b>subtracted down</b> — keep what best expresses the theme and cut the rest.</p></details>\n      <details><summary>Gestalt grouping in practice</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"22\" cy=\"26\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"33\" cy=\"26\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"44\" cy=\"26\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"70\" cy=\"44\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"81\" cy=\"44\" r=\"4\" fill=\"#7B6BB5\"/><circle cx=\"92\" cy=\"44\" r=\"4\" fill=\"#7B6BB5\"/></svg></span>Deliberately organize elements into <b>2–3 groups</b> (via proximity, similarity, a shared frame) — far more readable than scattered pieces. The eye likes \"blocks\", not \"crumbs\".</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>The ten principles of form <span class=\"tag hot\">why an arrangement reads as good</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 0\">Composition is the method: how the elements are arranged. These principles are the logic underneath every one of those methods. Every composition rule above is a combination of these ten. Same three lenses: photography, painting, design.</p>\n    </div>\n    <div class=\"card\">\n      <h3>The ten principles of form <span class=\"tag gold\">all ten</span></h3>\n      <details><summary>1. Repetition</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g fill=\"#8A5FC0\" opacity=\".75\"><rect x=\"12\" y=\"22\" width=\"12\" height=\"22\" rx=\"3\"/><rect x=\"31\" y=\"22\" width=\"12\" height=\"22\" rx=\"3\"/><rect x=\"50\" y=\"22\" width=\"12\" height=\"22\" rx=\"3\"/><rect x=\"69\" y=\"22\" width=\"12\" height=\"22\" rx=\"3\"/><rect x=\"88\" y=\"22\" width=\"12\" height=\"22\" rx=\"3\"/></g></svg></span><b class=\"fp-lede\">The same or similar shape, colour or line recurring at regular intervals.</b><i><b>Photo</b>A run of street lamps, windows or chairs whose regularity produces a visual beat.</i><i><b>Paint</b>Pointillism's countless dots and the continuous motifs of decorative painting build surface density through repeated marks.</i><i><b>Design</b>Consistent button styling and repeating pack patterns keep the visual language uniform and lower the cognitive load.</i></p></details>\n      <details><summary>2. Gradation</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><defs><linearGradient id=\"fpg\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\"><stop offset=\"0\" stop-color=\"#8A5FC0\"/><stop offset=\"1\" stop-color=\"#8A5FC0\" stop-opacity=\".08\"/></linearGradient></defs><rect x=\"6\" y=\"14\" width=\"98\" height=\"38\" rx=\"4\" fill=\"url(#fpg)\"/></svg></span><b class=\"fp-lede\">A stepwise change across size, colour, density or tone.</b><i><b>Photo</b>The sunset sky running orange-red into deep blue; street lamps shrinking with distance.</i><i><b>Paint</b>Ink painting's \"five shades of black\", and aerial perspective where things pale as they recede, are both gradation.</i><i><b>Design</b>Gradient backgrounds and a stepped scale of type weights make transitions feel natural rather than abrupt.</i></p></details>\n      <details><summary>3. Symmetry</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"55\" y1=\"4\" x2=\"55\" y2=\"62\" stroke=\"#7B6BB5\" stroke-dasharray=\"3 3\" opacity=\".6\"/><circle cx=\"34\" cy=\"33\" r=\"13\" fill=\"#8A5FC0\"/><circle cx=\"76\" cy=\"33\" r=\"13\" fill=\"#8A5FC0\"/></svg></span><b class=\"fp-lede\">Shape, count and colour matching on both sides of a central axis.</b><i><b>Photo</b>Reflections in water and building facades, producing gravity, stability and ceremony.</i><i><b>Paint</b>Altarpieces and court portraits place the most important figure dead centre with the sides answering each other exactly, using formal balance to assert unshakeable authority.</i><i><b>Design</b>Book covers, invitations and wordmarks use it to say elegant, trustworthy, formal.</i></p></details>\n      <details><summary>4. Equilibrium</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M55 50 L46 58 L64 58 Z\" fill=\"#7B6BB5\" opacity=\".6\"/><line x1=\"14\" y1=\"46\" x2=\"96\" y2=\"46\" stroke=\"#7B6BB5\" stroke-width=\"2\"/><circle cx=\"30\" cy=\"32\" r=\"14\" fill=\"#8A5FC0\"/><circle cx=\"84\" cy=\"38\" r=\"7\" fill=\"#E08A3C\"/></svg></span><b class=\"fp-lede\">Not a mirror copy but visual balance through weight. Symmetry is twins; equilibrium is a see-saw - the two sides differ, but they weigh the same.</b><i><b>Photo</b>A large figure on the left held in check by a small block of text or a single object on the right.</i><i><b>Paint</b>A mass of figures on one side answered by a large sweep of drapery, light or distant landscape on the other.</i><i><b>Design</b>A big image on the left, anchored by a heavy headline on the right so the page does not tip.</i></p></details>\n      <details><summary>5. Harmony</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g><rect x=\"12\" y=\"20\" width=\"20\" height=\"26\" rx=\"4\" fill=\"#8A5FC0\" opacity=\".45\"/><rect x=\"36\" y=\"20\" width=\"20\" height=\"26\" rx=\"4\" fill=\"#8A5FC0\" opacity=\".65\"/><rect x=\"60\" y=\"20\" width=\"20\" height=\"26\" rx=\"4\" fill=\"#8A5FC0\" opacity=\".85\"/><rect x=\"84\" y=\"20\" width=\"14\" height=\"26\" rx=\"4\" fill=\"#8A5FC0\"/></g></svg></span><b class=\"fp-lede\">Elements that share something, so they sit together without fighting.</b><i><b>Photo</b>Autumn yellows or a blue-green seascape, where every hue in the frame lives in one narrow band.</i><i><b>Paint</b>The unifying glaze of classical oil painting: an amber or blue-green transparent layer over everything, pulling all the colours into one atmosphere.</i><i><b>Design</b>A single palette across a deck, one corner radius across a UI: the whole thing reads as one thing.</i></p></details>\n      <details><summary>6. Contrast</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"1\" y=\"1\" width=\"54\" height=\"64\" rx=\"6\" fill=\"#2A2138\"/><circle cx=\"28\" cy=\"33\" r=\"12\" fill=\"#F6F4FB\"/><circle cx=\"82\" cy=\"33\" r=\"12\" fill=\"#2A2138\"/></svg></span><b class=\"fp-lede\">Setting unlike elements against one another so each brings out the other. No contrast, no focus.</b><i><b>Photo</b>Tonal contrast (silhouette), scale contrast (a person under a billboard), colour contrast (one red in a field of green).</i><i><b>Paint</b>Caravaggio's tenebrism brings figures out of near-black for maximum drama; the Impressionists set warm against cool to make colours vibrate.</i><i><b>Design</b>Large against small, white space against dense information, cool against warm: this is how hierarchy is built.</i></p></details>\n      <details><summary>7. Proportion</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"10\" width=\"60\" height=\"46\" rx=\"3\" fill=\"#7B6BB5\" opacity=\".25\"/><rect x=\"68\" y=\"10\" width=\"34\" height=\"46\" rx=\"3\" fill=\"#8A5FC0\" opacity=\".7\"/><text x=\"12\" y=\"38\" font-size=\"8\" fill=\"#7B6BB5\">1</text><text x=\"80\" y=\"38\" font-size=\"8\" fill=\"#fff\">.618</text></svg></span><b class=\"fp-lede\">The size relationships between elements, and between a part and the whole.</b><i><b>Photo</b>A figure occupying a tiny fraction of a vast landscape, which is what makes the landscape vast.</i><i><b>Paint</b>Anatomical proportion: the head-to-body ratio decides whether a figure reads as divine (elongated) or real; the golden section is used again and again to divide the picture.</i><i><b>Design</b>The relative size of headline, body and image sets the reading order; the golden ratio turns up constantly in logos and text blocks.</i></p></details>\n      <details><summary>8. Rhythm</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g fill=\"#8A5FC0\"><rect x=\"10\" y=\"18\" width=\"9\" height=\"30\" rx=\"2\"/><rect x=\"25\" y=\"28\" width=\"9\" height=\"10\" rx=\"2\" opacity=\".55\"/><rect x=\"40\" y=\"18\" width=\"9\" height=\"30\" rx=\"2\"/><rect x=\"55\" y=\"28\" width=\"9\" height=\"10\" rx=\"2\" opacity=\".55\"/><rect x=\"70\" y=\"18\" width=\"9\" height=\"30\" rx=\"2\"/><rect x=\"85\" y=\"28\" width=\"9\" height=\"10\" rx=\"2\" opacity=\".55\"/></g></svg></span><b class=\"fp-lede\">Repetition, gradation and stress producing a musical flow through the frame.</b><i><b>Photo</b>Fence shadows striping the ground; the eye hops along the stripes.</i><i><b>Paint</b>The rise and fall of mountains and the alternating density of trees in a handscroll let the eye move tight-loose-tight-loose, like breathing.</i><i><b>Design</b>Text, image and white space alternating down a long page give the reader paragraphs to breathe in while scrolling.</i></p></details>\n      <details><summary>9. Simplicity</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"33\" r=\"12\" fill=\"#8A5FC0\"/></svg></span><b class=\"fp-lede\">Removing every unnecessary decoration to leave the core shape and colour.</b><i><b>Photo</b>Minimalist photography down to one lamp and one wall, forcing the viewer to look at pure geometry.</i><i><b>Paint</b>Stripping away from the representational until only the basic relationship of shape and colour remains, pointing at form itself.</i><i><b>Design</b>The minimal poster, the Muji register: fewest elements, clearest message.</i></p></details>\n      <details><summary>10. Unity and variety</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g fill=\"#8A5FC0\"><circle cx=\"22\" cy=\"26\" r=\"9\"/><rect x=\"40\" y=\"16\" width=\"18\" height=\"18\" rx=\"4\"/><circle cx=\"76\" cy=\"24\" r=\"7\"/><rect x=\"18\" y=\"42\" width=\"14\" height=\"14\" rx=\"3\"/><circle cx=\"52\" cy=\"48\" r=\"7\"/><rect x=\"70\" y=\"40\" width=\"18\" height=\"16\" rx=\"4\"/></g></svg></span><b class=\"fp-lede\">Variation inside order and order inside variation - the highest synthesis. Too unified is monotonous, too varied is chaotic, and the difficulty is entirely in the judgement.</b><i><b>Photo</b>In a group photo everyone poses and reacts differently (variety) while wearing the same clothes against the same backdrop (unity).</i><i><b>Paint</b>In a large group painting each figure has its own movement and expression, but all the colour is unified under one light source and the whole is gathered by a larger geometry - a triangle or a spiral.</i><i><b>Design</b>Across a brand system, pages vary in layout while colour, type and logo position stay strict: recognisable and still interesting.</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>Composition rule to underlying principle <span class=\"tag ok\">cross-reference</span></h3>\n      <table><thead><tr><th>Composition rule</th><th>Main principles behind it</th></tr></thead><tbody>\n        <tr><td>Rule of thirds</td><td>proportion, equilibrium</td></tr>\n        <tr><td>Symmetry</td><td>symmetry, equilibrium</td></tr>\n        <tr><td>Leading lines</td><td>rhythm, gradation</td></tr>\n        <tr><td>Triangle</td><td>equilibrium, proportion</td></tr>\n        <tr><td>Negative space</td><td>simplicity, contrast</td></tr>\n        <tr><td>Fill the frame</td><td>contrast, repetition</td></tr>\n        <tr><td>Pattern and its break</td><td>repetition, contrast</td></tr>\n        <tr><td>Radial</td><td>gradation, rhythm</td></tr>\n        <tr><td>Curves</td><td>rhythm, harmony</td></tr>\n        <tr><td>Framing</td><td>contrast, simplicity</td></tr>\n        <tr><td>Multi-point perspective</td><td>variety, equilibrium</td></tr>\n        <tr><td>Dutch angle</td><td>contrast, rhythm</td></tr>\n      </tbody></table>\n      <p class=\"cond\" style=\"margin:10px 0 0\">No composition runs on one principle; each is a stack of several. The moment you stop memorising \"put the subject on an intersection\" and start seeing \"this works because proportion and equilibrium are doing the work\", you have the underlying grammar - and you can recombine it, break it, and build your own judgement.</p>\n    </div>\n", "ae-light": "\n    <div class=\"card\">\n      <h3>Lighting diagrams <span class=\"tag ok\">Light and shadow</span></h3>\n      <div class=\"dgm-grid\">\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"60\" cy=\"45\" r=\"24\" fill=\"#F6E7DC\" stroke=\"#DDD6E8\"/>\n<circle cx=\"60\" cy=\"80\" r=\"5\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1.2\">\n<line x1=\"51\" y1=\"80\" x2=\"54\" y2=\"80\"/><line x1=\"66\" y1=\"80\" x2=\"69\" y2=\"80\"/>\n<line x1=\"60\" y1=\"71\" x2=\"60\" y2=\"74\"/><line x1=\"60\" y1=\"86\" x2=\"60\" y2=\"89\"/></g></svg></div><figcaption>Front light · flat and bright</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"60\" cy=\"45\" r=\"24\" fill=\"#F6E7DC\" stroke=\"#DDD6E8\"/><path d=\"M60 21 A24 24 0 0 1 60 69 Z\" fill=\"#8B7B93\" opacity=\".55\"/>\n<circle cx=\"14\" cy=\"45\" r=\"5\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1.2\">\n<line x1=\"5\" y1=\"45\" x2=\"8\" y2=\"45\"/><line x1=\"20\" y1=\"45\" x2=\"23\" y2=\"45\"/>\n<line x1=\"14\" y1=\"36\" x2=\"14\" y2=\"39\"/><line x1=\"14\" y1=\"51\" x2=\"14\" y2=\"54\"/></g></svg></div><figcaption>Side light · maximum dimension</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"60\" cy=\"45\" r=\"24\" fill=\"#F6E7DC\" stroke=\"#DDD6E8\"/><circle cx=\"60\" cy=\"45\" r=\"24\" fill=\"#8B7B93\" opacity=\".72\"/><circle cx=\"60\" cy=\"45\" r=\"24\" fill=\"none\" stroke=\"#FFF3C4\" stroke-width=\"3\"/>\n<circle cx=\"60\" cy=\"10\" r=\"5\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1.2\">\n<line x1=\"51\" y1=\"10\" x2=\"54\" y2=\"10\"/><line x1=\"66\" y1=\"10\" x2=\"69\" y2=\"10\"/>\n<line x1=\"60\" y1=\"1\" x2=\"60\" y2=\"4\"/><line x1=\"60\" y1=\"16\" x2=\"60\" y2=\"19\"/></g></svg></div><figcaption>Backlight · silhouette + rim</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"60\" cy=\"45\" r=\"24\" fill=\"#F6E7DC\" stroke=\"#DDD6E8\"/><path d=\"M60 21 A24 24 0 0 1 60 69 Z\" fill=\"#8B7B93\" opacity=\".55\"/><polygon points=\"66,44 76,50 66,56\" fill=\"#F6E7DC\"/>\n<circle cx=\"22\" cy=\"14\" r=\"5\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1.2\">\n<line x1=\"13\" y1=\"14\" x2=\"16\" y2=\"14\"/><line x1=\"28\" y1=\"14\" x2=\"31\" y2=\"14\"/>\n<line x1=\"22\" y1=\"5\" x2=\"22\" y2=\"8\"/><line x1=\"22\" y1=\"20\" x2=\"22\" y2=\"23\"/></g></svg></div><figcaption>Rembrandt · triangle on the dark cheek</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"60\" cy=\"45\" r=\"24\" fill=\"#F6E7DC\" stroke=\"#DDD6E8\"/><path d=\"M36 45 A24 24 0 0 0 84 45 Z\" fill=\"#8B7B93\" opacity=\".35\"/><ellipse cx=\"60\" cy=\"53\" rx=\"7\" ry=\"3.5\" fill=\"#8B7B93\" opacity=\".7\"/>\n<circle cx=\"60\" cy=\"8\" r=\"5\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1.2\">\n<line x1=\"51\" y1=\"8\" x2=\"54\" y2=\"8\"/><line x1=\"66\" y1=\"8\" x2=\"69\" y2=\"8\"/>\n<line x1=\"60\" y1=\"-1\" x2=\"60\" y2=\"2\"/><line x1=\"60\" y1=\"14\" x2=\"60\" y2=\"17\"/></g></svg></div><figcaption>Butterfly · shadow under the nose</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"118\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"60\" cy=\"45\" r=\"24\" fill=\"#F6E7DC\" stroke=\"#DDD6E8\"/><path d=\"M36 45 A24 24 0 0 1 84 45 Z\" fill=\"#8B7B93\" opacity=\".6\"/>\n<circle cx=\"60\" cy=\"82\" r=\"5\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1.2\">\n<line x1=\"51\" y1=\"82\" x2=\"54\" y2=\"82\"/><line x1=\"66\" y1=\"82\" x2=\"69\" y2=\"82\"/>\n<line x1=\"60\" y1=\"73\" x2=\"60\" y2=\"76\"/><line x1=\"60\" y1=\"88\" x2=\"60\" y2=\"91\"/></g></svg></div><figcaption>Uplight · eerie</figcaption></figure>\n      </div>\n    </div>\n    <div class=\"card\">\n      <h3>Direction of light <span class=\"tag gold\">Sets the mood</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">Same outfit, different light direction — completely different feeling.</p>\n      <details><summary>Front light</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"#F3E7DC\"/><circle cx=\"55\" cy=\"58\" r=\"3.5\" fill=\"#B8892E\"/></svg></span>Light from the front: <b>clear, bright, even</b> — but <b>flat</b>, with little dimension. Best when you want to show every detail of the outfit.</p></details>\n      <details><summary>Side light (90°)</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"#F3E7DC\"/><path d=\"M55 19 A17 17 0 0 1 55 53 Z\" fill=\"#8B7B93\" opacity=\".55\"/><circle cx=\"10\" cy=\"36\" r=\"3.5\" fill=\"#B8892E\"/></svg></span>Light from the side, half lit and half dark. <b>Maximum dimension</b> — it reveals folds and fabric texture. Use it when you want the image to have thickness.</p></details>\n      <details><summary>Backlight</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"#F3E7DC\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"#8B7B93\" opacity=\".7\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"none\" stroke=\"#FFF3C4\" stroke-width=\"2.5\"/><circle cx=\"55\" cy=\"8\" r=\"3.5\" fill=\"#B8892E\"/></svg></span>Light behind the subject, who darkens toward a <b>silhouette</b> rimmed with light. The dreamiest, most atmospheric option — sheer fabric, lace and hair glow in backlight, ideal for ethereal looks.</p></details>\n      <details><summary>Rembrandt light (45°)</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"#F3E7DC\"/><path d=\"M55 19 A17 17 0 0 1 55 53 Z\" fill=\"#8B7B93\" opacity=\".55\"/><polygon points=\"60,35 69,40 60,45\" fill=\"#F3E7DC\"/><circle cx=\"16\" cy=\"10\" r=\"3.5\" fill=\"#B8892E\"/></svg></span>Light from 45° above and to the side, leaving a small <b>inverted triangle of light</b> on the shadowed cheek. Classical, painterly, elegant and dramatic — the portrait standard.</p></details>\n      <details><summary>Butterfly light (top-front)</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"#F3E7DC\"/><ellipse cx=\"55\" cy=\"44\" rx=\"6\" ry=\"3\" fill=\"#8B7B93\" opacity=\".7\"/><circle cx=\"55\" cy=\"7\" r=\"3.5\" fill=\"#B8892E\"/></svg></span>Light from directly above and in front, casting a <b>butterfly-shaped shadow</b> under the nose. Clean, glamorous, star-like — great for straight-on beauty shots.</p></details>\n      <details><summary>Uplight</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"#F3E7DC\"/><path d=\"M38 36 A17 17 0 0 1 72 36 Z\" fill=\"#8B7B93\" opacity=\".6\"/><circle cx=\"55\" cy=\"60\" r=\"3.5\" fill=\"#B8892E\"/></svg></span>Light from below. It defies nature and reads as <b>unsettling, eerie, sinister</b> — use it deliberately for dark or mirror themes.</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>Quality of light <span class=\"tag ok\">Hard vs soft</span></h3>\n      <ul class=\"tips\">\n        <li><b>Hard light</b>small, direct source; <b>crisp-edged</b> shadows, strong contrast. Dramatic, sharp, severe.</li>\n        <li><b>Soft light</b>large, diffused source (overcast, sheer curtains); <b>soft-edged</b> shadows. Gentle, dreamy, hazy.</li>\n        <li><b>Chiaroscuro</b>the classical technique of extreme light-dark contrast — a shaft of light in deep darkness. The Renaissance signature, perfect for gothic themes.</li>\n        <li><b>Rim light</b>a light from behind and to the side tracing the edge, <b>cutting the figure out of the background</b> — the rescue for dark clothes on dark backdrops.</li>\n        <li><b>Ambient occlusion</b>creases and contact points go darker. Remember this or the figure floats off the background.</li>\n        <li><b>Color temperature</b>warm (amber) = cozy, nostalgic, sunset; cool (blue) = calm, lonely, moonlit. <b>Warm subject + cool background</b> is the most flattering combination.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Advanced light <span class=\"tag gold\">Finer still</span></h3>\n      <details><summary>Three-point lighting</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"#F3E7DC\"/><path d=\"M55 19 A17 17 0 0 1 55 53 Z\" fill=\"#8B7B93\" opacity=\".4\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"none\" stroke=\"#FFF3C4\" stroke-width=\"2\"/><circle cx=\"96\" cy=\"52\" r=\"3\" fill=\"#3D8E8A\"/><circle cx=\"16\" cy=\"12\" r=\"3.5\" fill=\"#B8892E\"/></svg></span>The studio foundation: a <b>key light</b> (shapes form and shadow) + a <b>fill light</b> (opens shadows, controls contrast, usually weaker) + a <b>rim/back light</b> (traces the edge, separates from the background). With all three, the figure \"stands up\".</p></details>\n      <details><summary>High key vs low key</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#EFEAF6\"/><circle cx=\"55\" cy=\"33\" r=\"15\" fill=\"#CFC5E4\"/></svg></span><b>High key</b>: bright overall, mostly mid-to-light tones, minimal shadow — fresh, pure, dreamy, commercial. <b>Low key</b>: dark overall, large shadows with small highlights — mysterious, dramatic, emotional, cinematic. Decide the key first, then light for it.</p></details>\n      <details><summary>Quality: diffusion &amp; falloff</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"#F3E7DC\"/><path d=\"M55 19 A17 17 0 0 1 55 53 Z\" fill=\"#8B7B93\" opacity=\".5\"/><circle cx=\"14\" cy=\"36\" r=\"3.5\" fill=\"#B8892E\"/></svg></span>A source that is <b>bigger and closer = softer</b> (blurred shadow edges); <b>smaller and farther = harder</b> (crisp edges). Light also follows the inverse-square law — <b>it falls off faster the farther you go</b>, which you can use to darken the background and lift the subject.</p></details>\n      <details><summary>Bounce &amp; fill</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"#F3E7DC\"/><path d=\"M55 19 A17 17 0 0 1 55 53 Z\" fill=\"#8B7B93\" opacity=\".35\"/><rect x=\"86\" y=\"24\" width=\"8\" height=\"24\" rx=\"2\" fill=\"#EFE7C8\"/><circle cx=\"16\" cy=\"12\" r=\"3.5\" fill=\"#B8892E\"/></svg></span>Shadows needn&#39;t be dead black — bounce the key back into them with a <b>reflector or light-colored surface</b> to keep detail and soften contrast. Whether the shadows \"breathe\" is a hallmark of a refined photo.</p></details>\n      <details><summary>Colored light &amp; warm–cool cross</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"36\" r=\"17\" fill=\"#F3E7DC\"/><path d=\"M55 19 A17 17 0 0 0 55 53 Z\" fill=\"#5A78C0\" opacity=\".5\"/><path d=\"M55 19 A17 17 0 0 1 55 53 Z\" fill=\"#E0813F\" opacity=\".45\"/><circle cx=\"55\" cy=\"7\" r=\"3.5\" fill=\"#B8892E\"/></svg></span><b>Warm key, cool fill</b> (or vice versa) is the universal cinematic recipe: one cheek warm-amber, the other cool-blue — dimension and mood at once. Sunset&#39;s warm light against the sky&#39;s cool shadow is the natural example.</p></details>\n      <details><summary>Silhouette &amp; semi-silhouette</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#EDE6D6\"/><circle cx=\"55\" cy=\"30\" r=\"12\" fill=\"#2A2138\"/><rect x=\"45\" y=\"40\" width=\"20\" height=\"22\" rx=\"6\" fill=\"#2A2138\"/></svg></span>Under strong backlight, crush the subject <b>fully to a silhouette</b> = minimal, poetic, mysterious (form alone speaks); a <b>semi-silhouette</b> (a little frontal detail kept) balances mood and information. The outline must be clean and the pose clear for a silhouette to work.</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>Light and shadow <span class=\"tag hot\">light decides what the viewer feels</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 0\">Composition is the skeleton, the form principles are the grammar, light is the flesh. Keep the composition and change the light, and the same picture can go from hope to despair. The analyser now reads the quality of the light, its tonality, the colour in the shadows, the warm/cool split and volumetric shafts.</p>\n    </div>\n    <div class=\"card\">\n      <h3>1. Direction <span class=\"tag gold\">where the shadow falls decides the form and the character</span></h3>\n      <details><summary>Front / flat light</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><ellipse cx=\"55\" cy=\"34\" rx=\"20\" ry=\"25\" fill=\"#EDE6F5\"/><path d=\"M55 9 A20 25 0 0 0 55 59 Z\" fill=\"#EDE6F5\"/><circle cx=\"55\" cy=\"-2\" r=\"0\"/><circle cx=\"55\" cy=\"62\" r=\"5\" fill=\"#7B6BB5\" opacity=\".25\"/></svg></span><b class=\"fp-lede\">The source is behind you, pointing straight at the subject; the shadow falls behind and is barely visible.</b><i><b>Photo</b>The base lighting for ID photos and commercial product shots. Maximum detail, minimum form - it flattens a face.</i><i><b>Paint</b>Classical portraiture almost never uses pure front light alone because it eats every modelling stroke. But Dunhuang murals and gongbi figures use its logic deliberately, with even light standing for an existence beyond earthly shadow.</i><i><b>Design</b>The standard for white-background e-commerce: no shadow, no clutter, nothing between the buyer and the product.</i></p></details>\n      <details><summary>Side light</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><ellipse cx=\"55\" cy=\"34\" rx=\"20\" ry=\"25\" fill=\"#3B3348\"/><path d=\"M55 9 A20 25 0 0 0 55 59 Z\" fill=\"#EDE6F5\"/></svg></span><b class=\"fp-lede\">The source comes from the left or right; half lit, half dark.</b><i><b>Photo</b>Used for male portraits and weathered skin because it exaggerates texture and surface detail.</i><i><b>Paint</b>Rembrandt's signature: light strikes one side of the face, leaving a small inverted triangle on the other, so the figure emerges from the dark like sculpture.</i><i><b>Design</b>Type effects and game concept art use side light to carve out muscle and armour, giving a flat image instant volume.</i></p></details>\n      <details><summary>Backlight</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><ellipse cx=\"55\" cy=\"34\" rx=\"20\" ry=\"25\" fill=\"#2A2138\"/><ellipse cx=\"55\" cy=\"34\" rx=\"24\" ry=\"29\" fill=\"none\" stroke=\"#E08A3C\" stroke-width=\"3\" opacity=\".55\"/></svg></span><b class=\"fp-lede\">The source sits directly behind the subject.</b><i><b>Photo</b>The silhouette maker: colour and detail are stripped away and only the purest outline remains.</i><i><b>Paint</b>Turner's late seascapes fire the sun straight out of the picture; ships and waves dissolve in the glare and the edges of things are eaten by light, close to abstraction.</i><i><b>Design</b>Light bursting from behind a figure on a cover reads as arrival or hope; backlit flare is also used to open a picture up.</i></p></details>\n      <details><summary>Top light</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><ellipse cx=\"55\" cy=\"34\" rx=\"20\" ry=\"25\" fill=\"#EDE6F5\"/><path d=\"M55 9 A20 25 0 0 0 55 59 Z\" fill=\"#EDE6F5\"/><ellipse cx=\"55\" cy=\"46\" rx=\"14\" ry=\"8\" fill=\"#3B3348\" opacity=\".75\"/><path d=\"M40 4 L70 4 L64 12 L46 12 Z\" fill=\"#E08A3C\" opacity=\".5\"/></svg></span><b class=\"fp-lede\">Light falls from directly above, pooling shadow in the eye sockets and under the chin.</b><i><b>Photo</b>Noon sun or a stage spot. Sunken eyes read as judgement, authority, oppression or exhaustion.</i><i><b>Paint</b>Often credited to Caravaggio, but with a caveat: his signature is actually a high raking SIDE light (the so-called cellar light), not pure top light. What genuine top light does is drag the shadow vertically to the floor, so the composition itself says falling and weight.</i><i><b>Design</b>The key light of horror game posters and thrillers, manufacturing unease.</i></p></details>\n      <details><summary>Under light</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><ellipse cx=\"55\" cy=\"34\" rx=\"20\" ry=\"25\" fill=\"#3B3348\"/><path d=\"M55 9 A20 25 0 0 0 55 59 Z\" fill=\"#3B3348\"/><ellipse cx=\"55\" cy=\"24\" rx=\"15\" ry=\"10\" fill=\"#EDE6F5\" opacity=\".55\"/><path d=\"M40 62 L70 62 L64 54 L46 54 Z\" fill=\"#E08A3C\" opacity=\".5\"/></svg></span><b class=\"fp-lede\">Light comes from below, inverting everyday experience.</b><i><b>Photo</b>The classic horror and Halloween look, turning a familiar face uncanny.</i><i><b>Paint</b>La Tour's candlelit pictures are the usual example, but his candle generally sits within the scene at or just below face height, often shielded by a hand - it is not strictly under-lighting. What it really demonstrates is the meditative quality of a single weak source. For true under-lighting, look at stage and horror lighting.</i><i><b>Design</b>Common on theatre and thriller posters for exactly that wrongness.</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>2. Quality <span class=\"tag ok\">hard or soft decides whether the shadow edge is a line or a fade</span></h3>\n      <details><summary>Hard light</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"14\" width=\"40\" height=\"38\" rx=\"4\" fill=\"#EDE6F5\"/><rect x=\"52\" y=\"14\" width=\"46\" height=\"38\" rx=\"4\" fill=\"#2A2138\"/></svg></span><b class=\"fp-lede\">A point source (noon sun, bare spot). Shadow edges are crisp and the tonal jump is huge.</b><i><b>Photo</b>The light of documentary and street work, bringing conflict and a masculine edge.</i><i><b>Paint</b>Caravaggio's tenebrism: the highlight drops straight to the shadow with almost no transition, as if the figure were pulled out of an abyss by lightning.</i><i><b>Design</b>Renders of metal and tech products use hard light to sharpen the edges and read as force.</i></p></details>\n      <details><summary>Soft / diffused light</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><defs><linearGradient id=\"lqs\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\"><stop offset=\"0\" stop-color=\"#EDE6F5\"/><stop offset=\"1\" stop-color=\"#2A2138\"/></linearGradient></defs><rect x=\"10\" y=\"14\" width=\"88\" height=\"38\" rx=\"4\" fill=\"url(#lqs)\"/></svg></span><b class=\"fp-lede\">A large scattered source (cloud, softbox). Shadow edges blur and the turn is smooth.</b><i><b>Photo</b>The safest portrait light: it hides pores and fine lines and reads as tender.</i><i><b>Paint</b>Vermeer's Dutch interiors, where silver-grey daylight diffuses from a left-hand window and wraps clothes and faces so softly they almost merge into the air.</i><i><b>Design</b>Japanese and Nordic graphic design leans on soft gradients for comfort, nature and purity.</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>3. Tonality <span class=\"tag warn\">the gap between light and dark sets the register</span></h3>\n      <details><summary>High contrast</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"18\" width=\"42\" height=\"30\" rx=\"3\" fill=\"#F8F5FC\"/><rect x=\"58\" y=\"18\" width=\"42\" height=\"30\" rx=\"3\" fill=\"#15101E\"/></svg></span><b class=\"fp-lede\">Bright highlights, blocked shadows, very little grey in between.</b><i><b>Photo</b>Black-and-white documentary and film noir: forceful, suited to strong emotion.</i><i><b>Paint</b>Printmaking, especially woodcut, can only work in black and white, so the artist has to compress every mid-grey into cut and blank. Enormously powerful.</i><i><b>Design</b>Rock posters and streetwear brands slam high-contrast black and white together for defiance.</i></p></details>\n      <details><summary>Low contrast</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g><rect x=\"8\" y=\"18\" width=\"19\" height=\"30\" fill=\"#E4DCEE\"/><rect x=\"27\" y=\"18\" width=\"19\" height=\"30\" fill=\"#C6BBD8\"/><rect x=\"46\" y=\"18\" width=\"19\" height=\"30\" fill=\"#A79ABE\"/><rect x=\"65\" y=\"18\" width=\"19\" height=\"30\" fill=\"#8B7EA4\"/><rect x=\"84\" y=\"18\" width=\"18\" height=\"30\" fill=\"#6F6289\"/></g></svg></span><b class=\"fp-lede\">A rich range of greys from lightest to darkest, with no pure black or white.</b><i><b>Photo</b>Airy, gentle portraiture: highlights not blown, shadows not crushed.</i><i><b>Paint</b>Monet's late water lilies abandon strong contrast entirely; the whole canvas is a field of mist made of subtle warms and cools, already moving toward abstraction.</i><i><b>Design</b>The register of premium skincare and baby brands: soft, unaggressive, approachable.</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>4. Function and special cases <span class=\"tag hot\">light that is doing a job</span></h3>\n      <details><summary>Sculptural / form light</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"34\" r=\"22\" fill=\"#B9AECD\"/><path d=\"M55 12 A22 22 0 0 1 55 56 Z\" fill=\"#6F6289\"/><ellipse cx=\"46\" cy=\"26\" rx=\"8\" ry=\"10\" fill=\"#EDE6F5\" opacity=\".8\"/></svg></span><b class=\"fp-lede\">Light purely to reveal shape, turn and texture, with no interest in drama.</b><i><b>Photo</b>In product photography, a light is swept across a surface at a chosen angle to force out fabric weave or the facets of a stone.</i><i><b>Paint</b>The basis of academic drawing: one fixed source analyses the planes of a cast, reducing complex form to light, half-tone, shadow, core shadow and reflected light.</i><i><b>Design</b>The default lighting you rotate a model under in 3D software, whose entire purpose is to make structure legible.</i></p></details>\n      <details><summary>Ambient and bounced light</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"34\" r=\"22\" fill=\"#4A4159\"/><path d=\"M55 12 A22 22 0 0 1 55 56 Z\" fill=\"#2A2138\"/><path d=\"M33 34 A22 22 0 0 0 55 56 Z\" fill=\"#5E7EA8\" opacity=\".75\"/></svg></span><b class=\"fp-lede\">Light comes not just from the source but from everything in the environment. Beginners ignore it; it is the main thing that decides whether light looks real.</b><i><b>Photo</b>Fill from a white wall or a golden sunset landing on a face - the shadow is not black, it is faint light carrying the colour of its surroundings.</i><i><b>Paint</b>The Impressionists turned \"shadow is not black-brown but the blue of the sky or the green of the grass\" into a whole method. Worth noting they did not discover it: Chevreul described simultaneous contrast in 1839 and Delacroix was already painting coloured shadow. Their contribution was making it systematic and total.</i><i><b>Design</b>Without that mutual bleed, a realistic illustration or composite looks stiff and pasted-on immediately.</i></p></details>\n      <details><summary>Volumetric shafts</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g opacity=\".8\"><path d=\"M28 2 L46 2 L26 64 L6 64 Z\" fill=\"#E08A3C\" opacity=\".35\"/><path d=\"M56 2 L74 2 L58 64 L38 64 Z\" fill=\"#E08A3C\" opacity=\".35\"/><path d=\"M84 2 L102 2 L92 64 L72 64 Z\" fill=\"#E08A3C\" opacity=\".35\"/></g></svg></span><b class=\"fp-lede\">Light passing through a medium - a gap in cloud, dust by a window, mist in a forest - becomes visible as beams.</b><i><b>Photo</b>Waiting for the moment crepuscular rays break through gives a landscape the shock of something arriving.</i><i><b>Paint</b>In Romantic and religious painting, shafts breaking cloud stand for revelation, hope or divine intervention.</i><i><b>Design</b>Game scenes and film posters use them as spectacle, aiming the eye at whatever the beam lands on.</i></p></details>\n      <details><summary>Colour of light (temperature)</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"6\" y=\"12\" width=\"46\" height=\"42\" rx=\"4\" fill=\"#E8A63C\"/><rect x=\"58\" y=\"12\" width=\"46\" height=\"42\" rx=\"4\" fill=\"#3C6FA8\"/></svg></span><b class=\"fp-lede\">Light has its own colour, from candle orange to overcast blue, and temperature defines the mood directly.</b><i><b>Photo</b>Catching warm low-temperature light against the high-temperature blue hour gives you golden hour and blue hour in one frame.</i><i><b>Paint</b>Monet's series of the same subject at different hours (haystacks, Rouen cathedral) proved local colour does not exist: everything depends on the colour of the light at that moment.</i><i><b>Design</b>Pairing cool and warm light is the single most recognisable visual signature of cyberpunk.</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>5. The underlying attitude <span class=\"tag gold\">the three fields differ in kind</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 0\"><b>Photography</b> light is FOUND. It tests your sensitivity to what is already there: where is it coming from, what quality is it, where does the shadow fall?<br><b>Painting</b> light is DESIGNED. You have to decide the position, strength and colour of the source out of nothing.<br><b>Design</b> light is SIMULATED. Flat drop shadow or full 3D render, it is only ever a tool for building hierarchy and mood.<br><br>In one line: composition decides what the story is, light decides what the viewer feels.</p>\n    </div>\n", "ae-photo": "\n    <div class=\"card\">\n      <h3>Portrait diagrams <span class=\"tag ok\">Crop · space · pose</span></h3>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 150 120\" role=\"img\">\n<g fill=\"#EFE6F5\" stroke=\"#7B6BB5\" stroke-width=\"1.2\">\n<circle cx=\"46\" cy=\"20\" r=\"11\"/><rect x=\"35\" y=\"33\" width=\"22\" height=\"34\" rx=\"8\"/><rect x=\"38\" y=\"66\" width=\"16\" height=\"42\" rx=\"7\"/></g>\n<g stroke=\"#D06666\" stroke-width=\"1.6\" stroke-dasharray=\"4 3\">\n<line x1=\"20\" y1=\"32\" x2=\"76\" y2=\"32\"/><line x1=\"20\" y1=\"66\" x2=\"76\" y2=\"66\"/><line x1=\"20\" y1=\"106\" x2=\"76\" y2=\"106\"/></g>\n<text x=\"80\" y=\"35\" font-size=\"8.5\" fill=\"#C05555\">✗ neck</text>\n<text x=\"80\" y=\"69\" font-size=\"8.5\" fill=\"#C05555\">✗ knee</text>\n<text x=\"80\" y=\"109\" font-size=\"8.5\" fill=\"#C05555\">✗ ankle</text>\n<g stroke=\"#3D8E8A\" stroke-width=\"1.8\">\n<line x1=\"20\" y1=\"47\" x2=\"76\" y2=\"47\"/><line x1=\"20\" y1=\"84\" x2=\"76\" y2=\"84\"/></g>\n<text x=\"80\" y=\"50\" font-size=\"8.5\" fill=\"#3D8E8A\">✓ chest</text>\n<text x=\"80\" y=\"87\" font-size=\"8.5\" fill=\"#3D8E8A\">✓ mid-thigh</text></svg></div><figcaption>Crop rule: red = joints (never), green = safe zones</figcaption></figure>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 240 96\" role=\"img\">\n<rect x=\"2\" y=\"6\" width=\"112\" height=\"84\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<circle cx=\"58\" cy=\"46\" r=\"15\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><circle cx=\"64\" cy=\"44\" r=\"2.4\" fill=\"#2A2138\"/>\n<line x1=\"58\" y1=\"10\" x2=\"58\" y2=\"29\" stroke=\"#8A5FC0\" stroke-width=\"1.2\" stroke-dasharray=\"3 2\"/>\n<text x=\"62\" y=\"20\" font-size=\"8\" fill=\"#8A5FC0\">headroom</text>\n<rect x=\"126\" y=\"6\" width=\"112\" height=\"84\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<circle cx=\"164\" cy=\"48\" r=\"15\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><circle cx=\"171\" cy=\"46\" r=\"2.4\" fill=\"#2A2138\"/>\n<path d=\"M182 48 L214 48\" stroke=\"#3D8E8A\" stroke-width=\"1.4\" marker-end=\"url(#ar)\"/>\n<defs><marker id=\"ar\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0 0 L6 3 L0 6 z\" fill=\"#3D8E8A\"/></marker></defs>\n<text x=\"186\" y=\"42\" font-size=\"8\" fill=\"#3D8E8A\">lead room</text></svg></div><figcaption>Keep headroom tight; leave lead room where they look</figcaption></figure>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 240 110\" role=\"img\">\n<g stroke=\"#7B6BB5\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\">\n<circle cx=\"42\" cy=\"18\" r=\"9\" fill=\"#EFE6F5\"/><line x1=\"42\" y1=\"27\" x2=\"42\" y2=\"62\"/><line x1=\"42\" y1=\"62\" x2=\"34\" y2=\"98\"/><line x1=\"42\" y1=\"62\" x2=\"52\" y2=\"98\"/><line x1=\"28\" y1=\"38\" x2=\"56\" y2=\"38\"/></g>\n<text x=\"16\" y=\"110\" font-size=\"8.5\" fill=\"#2A2138\">stiff, even weight</text>\n<g stroke=\"#8A5FC0\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\">\n<circle cx=\"160\" cy=\"18\" r=\"9\" fill=\"#EFE6F5\"/>\n<path d=\"M160 27 Q168 44 158 62\" />\n<line x1=\"158\" y1=\"62\" x2=\"152\" y2=\"98\"/><line x1=\"158\" y1=\"62\" x2=\"172\" y2=\"94\"/>\n<line x1=\"147\" y1=\"36\" x2=\"174\" y2=\"41\"/></g>\n<text x=\"128\" y=\"110\" font-size=\"8.5\" fill=\"#8A5FC0\">contrapposto · S-curve</text></svg></div><figcaption>Contrapposto: weight on one leg, shoulders counter the hips</figcaption></figure>\n    </div>\n    <div class=\"card\">\n      <h3>Angle &amp; framing <span class=\"tag gold\">Changes the story</span></h3>\n      <details><summary>Eye level</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"8\" y1=\"58\" x2=\"102\" y2=\"58\" stroke=\"#DDD6E8\"/><rect x=\"50\" y=\"24\" width=\"12\" height=\"34\" rx=\"5\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><circle cx=\"56\" cy=\"19\" r=\"6\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><circle cx=\"20\" cy=\"38\" r=\"5\" fill=\"#8A5FC0\"/><line x1=\"25\" y1=\"38\" x2=\"48\" y2=\"32\" stroke=\"#8A5FC0\" stroke-width=\"1.4\" stroke-dasharray=\"3 2\"/></svg></span>Level with the subject: <b>equal, natural, realistic</b> — the neutral choice for everyday feel and formal portraits.</p></details>\n      <details><summary>Low angle (looking up)</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"8\" y1=\"58\" x2=\"102\" y2=\"58\" stroke=\"#DDD6E8\"/><rect x=\"50\" y=\"24\" width=\"12\" height=\"34\" rx=\"5\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><circle cx=\"56\" cy=\"19\" r=\"6\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><circle cx=\"20\" cy=\"54\" r=\"5\" fill=\"#8A5FC0\"/><line x1=\"25\" y1=\"54\" x2=\"50\" y2=\"44\" stroke=\"#8A5FC0\" stroke-width=\"1.4\" stroke-dasharray=\"3 2\"/></svg></span>Makes the subject <b>tall, imposing, commanding</b> — for royalty, villains and high-presence looks.</p></details>\n      <details><summary>High angle (looking down)</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"8\" y1=\"58\" x2=\"102\" y2=\"58\" stroke=\"#DDD6E8\"/><rect x=\"50\" y=\"24\" width=\"12\" height=\"34\" rx=\"5\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><circle cx=\"56\" cy=\"19\" r=\"6\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><circle cx=\"20\" cy=\"20\" r=\"5\" fill=\"#8A5FC0\"/><line x1=\"25\" y1=\"20\" x2=\"52\" y2=\"22\" stroke=\"#8A5FC0\" stroke-width=\"1.4\" stroke-dasharray=\"3 2\"/></svg></span>Makes the subject <b>small, delicate, endearing</b>; also good for showing the full skirt and floor decoration.</p></details>\n      <details><summary>Shot sizes</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"30\" y=\"8\" width=\"50\" height=\"52\" rx=\"4\" fill=\"none\" stroke=\"#8A5FC0\" stroke-dasharray=\"3 2\"/><circle cx=\"55\" cy=\"24\" r=\"9\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><rect x=\"45\" y=\"34\" width=\"20\" height=\"26\" rx=\"5\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/></svg></span><b>Full/wide</b> = sets the scene and the whole outfit; <b>medium</b> = balances figure and clothing; <b>close-up</b> = expression, jewelry, texture. A good set has <b>all three</b>.</p></details>\n      <details><summary>Depth of field</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"30\" cy=\"34\" r=\"11\" fill=\"#CFC0E8\" opacity=\".5\"/><circle cx=\"82\" cy=\"34\" r=\"13\" fill=\"#C9BBE4\" opacity=\".4\"/><rect x=\"48\" y=\"24\" width=\"14\" height=\"34\" rx=\"6\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><circle cx=\"55\" cy=\"20\" r=\"7\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/></svg></span><b>Shallow</b> (blurred background) = subject pops, dreamy; <b>deep</b> (all sharp) = full information, grandeur. Portraits favor shallow, scenery favors deep.</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>Working habits <span class=\"tag ok\">Practical</span></h3>\n      <ul class=\"tips\">\n        <li><b>Decide the star first</b>the outfit? the expression? the mood? Different stars need different framing and light.</li>\n        <li><b>Subtraction beats addition</b>a messy frame usually has <b>too much</b>, not too little. Remove whatever doesn&#39;t serve the theme.</li>\n        <li><b>Backgrounds serve the subject</b>a busy background eats the figure; dark clothes on light backgrounds (and vice versa) is always safe.</li>\n        <li><b>Watch the edges</b>check all four borders for half-cropped oddities — clean edges are half of looking professional.</li>\n        <li><b>One image, one idea</b>the less you try to say, the stronger it reads.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Portrait framing &amp; cropping <span class=\"tag hot\">Pro portraiture</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">How close you get and where you cut decides both intimacy and polish.</p>\n      <details><summary>Shot size = psychological distance</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"30\" y=\"8\" width=\"50\" height=\"52\" rx=\"4\" fill=\"none\" stroke=\"#8A5FC0\" stroke-dasharray=\"3 2\"/><circle cx=\"55\" cy=\"24\" r=\"9\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><rect x=\"45\" y=\"34\" width=\"20\" height=\"26\" rx=\"5\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/></svg></span><b>Extreme close-up</b> (features) = strongest emotion, most intimate; <b>close-up</b> (head &amp; shoulders) = intimate, expression-led; <b>bust</b> (waist up) = figure and pose together, the workhorse; <b>medium</b> (knees up) = gestures and the main garment; <b>full length</b> = the complete look; <b>wide</b> = small figure, big scene, all atmosphere.<br>Closer = more emotion; wider = more narrative.</p></details>\n      <details><summary>Cropping taboos (the joint rule)</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"46\" y=\"10\" width=\"18\" height=\"30\" rx=\"7\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><circle cx=\"55\" cy=\"8\" r=\"6\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><line x1=\"30\" y1=\"40\" x2=\"80\" y2=\"40\" stroke=\"#C0554E\" stroke-width=\"1.6\" stroke-dasharray=\"4 3\"/><line x1=\"30\" y1=\"52\" x2=\"80\" y2=\"52\" stroke=\"#3D8E8A\" stroke-width=\"1.6\"/><text x=\"83\" y=\"43\" font-size=\"8\" fill=\"#C0554E\">✗</text><text x=\"83\" y=\"55\" font-size=\"8\" fill=\"#3D8E8A\">✓</text></svg></span><b>Never crop at a joint</b> — wrists, elbows, knees, ankles, neck. Cutting at joints reads as amputation and feels deeply wrong.<br><b>Do instead</b>: crop through <b>mid-thigh, waist, chest or mid-upper-arm</b> — the fleshy parts. Also avoid cutting off fingers or half a foot.</p></details>\n      <details><summary>Headroom</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"38\" r=\"14\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><line x1=\"55\" y1=\"6\" x2=\"55\" y2=\"23\" stroke=\"#8A5FC0\" stroke-dasharray=\"3 2\"/><text x=\"59\" y=\"16\" font-size=\"7.5\" fill=\"#8A5FC0\">headroom</text></svg></span>The gap between the head and the top edge. <b>Too much sinks the subject and empties the frame; too little feels crushed.</b><br>Rule: the closer the shot, the less headroom — in an extreme close-up you may <b>crop into the top of the head</b>, which is standard professional practice and makes the features fuller.</p></details>\n      <details><summary>Lead room / nose room</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"40\" cy=\"34\" r=\"14\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><circle cx=\"47\" cy=\"32\" r=\"2.4\" fill=\"#2A2138\"/><path d=\"M56 34 L96 34\" stroke=\"#3D8E8A\" stroke-width=\"1.3\" stroke-dasharray=\"3 2\"/><text x=\"60\" y=\"28\" font-size=\"7.5\" fill=\"#3D8E8A\">lead room</text></svg></span>The side the subject faces or looks toward <b>needs more space</b>.<br>Without it you get the \"facing a wall\" effect — the gaze hits the frame edge and viewers feel vaguely uncomfortable. This is the <b>most overlooked yet most effective</b> rule in portrait composition.</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>Pose &amp; body line <span class=\"tag gold\">Bring the figure to life</span></h3>\n      <details><summary>Contrapposto</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#8A5FC0\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"><circle cx=\"55\" cy=\"14\" r=\"7\" fill=\"#EFE6F5\"/><path d=\"M55 21 Q62 34 52 48\"/><line x1=\"52\" y1=\"48\" x2=\"46\" y2=\"60\"/><line x1=\"52\" y1=\"48\" x2=\"64\" y2=\"58\"/><line x1=\"44\" y1=\"28\" x2=\"66\" y2=\"32\"/></g></svg></span>The ancient Greek invention: <b>shift the weight onto one leg</b> so the hips tilt one way and the shoulders the other, and the body relaxes into an S.<br>Effect: it <b>instantly kills the stiff at-attention stance</b> and creates natural grace. This is the foundation of all posing — shift the weight to one foot first.</p></details>\n      <details><summary>The S-curve and the triangle</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M55 10 Q46 26 58 38 Q68 48 50 60\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"2.4\" stroke-linecap=\"round\"/></svg></span><b>S-curve</b>: the body undulates in an S (head, shoulders, waist, hips counter-swaying) — the classic soft, feminine line.<br><b>Triangle</b>: hand on hip, arm propped, or a seated pose with the skirt spread all form triangles and read as <b>stable</b>. Use S for grace, triangle for gravitas.</p></details>\n      <details><summary>Shoulder line &amp; angle</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"16\" r=\"7\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><line x1=\"34\" y1=\"40\" x2=\"76\" y2=\"30\" stroke=\"#8A5FC0\" stroke-width=\"2.4\" stroke-linecap=\"round\"/><text x=\"30\" y=\"56\" font-size=\"8\" fill=\"#2A2138\">~45°</text></svg></span><b>Shoulders parallel to the camera = formal, powerful, symmetrical</b>; <b>shoulders angled = slimmer, more natural, more dimensional</b>. Most portraits turn the body about 45° and bring the face back to the lens — the most flattering and dimensional setup.</p></details>\n      <details><summary>What to do with hands</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><ellipse cx=\"55\" cy=\"34\" rx=\"10\" ry=\"15\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"2\"/><g stroke=\"#7B6BB5\" stroke-width=\"2\" stroke-linecap=\"round\"><line x1=\"49\" y1=\"22\" x2=\"47\" y2=\"12\"/><line x1=\"55\" y1=\"20\" x2=\"55\" y2=\"10\"/><line x1=\"61\" y1=\"22\" x2=\"63\" y2=\"12\"/></g></svg></span>Hands are where portraits go wrong. Rules: <b>①give them a job</b> (touch hair, hem, a prop); <b>②avoid the back of the hand facing the lens</b> (it reads large and slab-like) — the <b>edge of the hand</b> is far more elegant; <b>③keep fingers softly curved, never rigid and clamped</b>; ④leave a gap between arms and torso for a slimmer line.</p></details>\n      <details><summary>Watch for mergers</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"46\" y=\"14\" width=\"18\" height=\"34\" rx=\"7\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><line x1=\"55\" y1=\"4\" x2=\"55\" y2=\"60\" stroke=\"#C0554E\" stroke-width=\"3\" opacity=\".5\"/><text x=\"60\" y=\"40\" font-size=\"8\" fill=\"#C0554E\">✗ merge</text></svg></span>From the camera&#39;s angle, avoid <b>poles growing out of heads</b>, arms merging with background lines, or props slicing the neck. Check that the figure&#39;s outline doesn&#39;t stick to the background.</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>The four portrait lighting patterns <span class=\"tag ok\">Face light</span></h3>\n      <ul class=\"tips\">\n        <li><b>Butterfly / Paramount</b>light directly above and in front; butterfly shadow under the nose. <b>Glamorous, starlike</b> — for frontal beauty shots and symmetrical faces.</li>\n        <li><b>Loop</b>light offset 30–45°, casting a <b>small loop</b> of nose shadow on the cheek. The most natural and versatile pattern, flattering on most faces.</li>\n        <li><b>Rembrandt</b>light around 45°, leaving an <b>inverted triangle of light</b> on the shadowed cheek. Dramatic, painterly, the most narrative.</li>\n        <li><b>Split</b>light at a full 90°, splitting the face <b>half lit, half dark</b>. Intense, mysterious, conflicted — perfect for dark or dual-nature themes.</li>\n        <li><b>Catchlight</b>that spark of reflection in the eye. <b>Without it the eyes look dead</b> — the make-or-break detail of portraiture; always check for light in the eyes.</li>\n        <li><b>Lighting ratio</b>the gap between lit and shadow sides. <b>Low ratio</b> = soft and fresh; <b>high ratio</b> = dramatic and intense. Fill for gentleness, let shadows fall for depth.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Focal length &amp; facial distortion <span class=\"tag ok\">Why you step back</span></h3>\n      <ul class=\"tips\">\n        <li><b>Wide (&lt;35mm)</b>up close it <b>enlarges the nose and stretches the face</b>. Fine for exaggeration and environmental portraits, wrong for close-ups.</li>\n        <li><b>Normal (50mm)</b>close to human vision — natural and honest, the all-rounder for full-length and environmental work.</li>\n        <li><b>Portrait range (85–135mm)</b><b>the acknowledged flattering focal lengths</b>. Compression keeps features proportional and blurs backgrounds softly.</li>\n        <li><b>Distance is the real cause</b>distortion comes from being too close, not from the lens itself. <b>Step back and zoom in</b> and the face normalizes.</li>\n        <li><b>Background compression</b>long lenses pull the background closer and larger, turning a distant flower wall or the moon into a huge backdrop element.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Camera angle diagrams <span class=\"tag ok\">Where the camera is</span></h3>\n      <div class=\"dgm-grid\"><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 88\"><rect width=\"120\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"46\" cy=\"24\" r=\"9\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"38\" y=\"34\" width=\"16\" height=\"30\" rx=\"6\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"86\" y=\"34\" width=\"16\" height=\"12\" rx=\"2\" fill=\"#8A5FC0\"/><line x1=\"86\" y1=\"40\" x2=\"58\" y2=\"40\" stroke=\"#3D8E8A\" stroke-dasharray=\"3 2\"/><text x=\"10\" y=\"82\" font-size=\"10\" fill=\"#2A2138\">Eye</text></svg></div><figcaption>Eye level · natural</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 88\"><rect width=\"120\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"46\" cy=\"24\" r=\"9\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"38\" y=\"34\" width=\"16\" height=\"30\" rx=\"6\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"82\" y=\"66\" width=\"16\" height=\"12\" rx=\"2\" fill=\"#8A5FC0\"/><line x1=\"86\" y1=\"66\" x2=\"52\" y2=\"34\" stroke=\"#3D8E8A\" stroke-dasharray=\"3 2\"/><text x=\"10\" y=\"82\" font-size=\"10\" fill=\"#2A2138\">Low angle</text></svg></div><figcaption>Low · imposing</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 88\"><rect width=\"120\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"46\" cy=\"24\" r=\"9\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"38\" y=\"34\" width=\"16\" height=\"30\" rx=\"6\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"82\" y=\"8\" width=\"16\" height=\"12\" rx=\"2\" fill=\"#8A5FC0\"/><line x1=\"86\" y1=\"20\" x2=\"52\" y2=\"40\" stroke=\"#3D8E8A\" stroke-dasharray=\"3 2\"/><text x=\"10\" y=\"82\" font-size=\"10\" fill=\"#2A2138\">High angle</text></svg></div><figcaption>High · delicate</figcaption></figure></div>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 200 92\"><rect width=\"200\" height=\"92\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<g transform=\"translate(6,8)\"><circle cx=\"26\" cy=\"18\" r=\"9\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"17\" y=\"28\" width=\"18\" height=\"26\" rx=\"6\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"20\" y=\"54\" width=\"12\" height=\"20\" rx=\"4\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"1\" y=\"1\" width=\"52\" height=\"76\" rx=\"4\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"1.5\"/><text x=\"6\" y=\"90\" font-size=\"9\" fill=\"#2A2138\">Full</text></g>\n<g transform=\"translate(72,8)\"><circle cx=\"26\" cy=\"18\" r=\"9\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"17\" y=\"28\" width=\"18\" height=\"26\" rx=\"6\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"6\" y=\"1\" width=\"42\" height=\"52\" rx=\"4\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"1.5\"/><text x=\"6\" y=\"90\" font-size=\"9\" fill=\"#2A2138\">Waist-up</text></g>\n<g transform=\"translate(140,8)\"><circle cx=\"30\" cy=\"24\" r=\"15\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><rect x=\"12\" y=\"1\" width=\"40\" height=\"40\" rx=\"4\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"1.5\"/><text x=\"10\" y=\"90\" font-size=\"9\" fill=\"#2A2138\">Close</text></g></svg></div><figcaption>Shot size: closer = more emotion, wider = more story</figcaption></figure>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 200 88\"><rect width=\"200\" height=\"88\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<g transform=\"translate(6,6)\"><circle cx=\"60\" cy=\"20\" r=\"6\" fill=\"#DDD6E8\"/><circle cx=\"30\" cy=\"30\" r=\"5\" fill=\"#DDD6E8\"/><circle cx=\"80\" cy=\"40\" r=\"7\" fill=\"#DDD6E8\"/><circle cx=\"46\" cy=\"46\" r=\"9\" fill=\"#8A5FC0\"/><rect x=\"1\" y=\"1\" width=\"88\" height=\"72\" rx=\"4\" fill=\"none\" stroke=\"#DDD6E8\"/><text x=\"6\" y=\"88\" font-size=\"9\" fill=\"#2A2138\">Shallow DOF</text></g>\n<g transform=\"translate(104,6)\"><circle cx=\"60\" cy=\"20\" r=\"6\" fill=\"#7B6BB5\"/><circle cx=\"30\" cy=\"30\" r=\"5\" fill=\"#7B6BB5\"/><circle cx=\"80\" cy=\"40\" r=\"7\" fill=\"#7B6BB5\"/><circle cx=\"46\" cy=\"46\" r=\"9\" fill=\"#8A5FC0\"/><rect x=\"1\" y=\"1\" width=\"88\" height=\"72\" rx=\"4\" fill=\"none\" stroke=\"#DDD6E8\"/><text x=\"6\" y=\"88\" font-size=\"9\" fill=\"#2A2138\">Deep DOF</text></g></svg></div><figcaption>DOF: shallow for portraits, deep for scenery</figcaption></figure>\n    </div>\n    <div class=\"card\">\n      <h3>Camera diagrams <span class=\"tag ok\">Angle · shot · depth</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 10px\">The camera position (dot) sets how the subject feels.</p>\n      <div class=\"dgm-grid\"><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<line x1=\"10\" y1=\"80\" x2=\"110\" y2=\"80\" stroke=\"#DDD6E8\"/>\n<rect x=\"54\" y=\"34\" width=\"14\" height=\"40\" rx=\"6\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><circle cx=\"61\" cy=\"28\" r=\"8\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/>\n<circle cx=\"26\" cy=\"74\" r=\"6\" fill=\"#8A5FC0\"/><path d=\"M32 74 L54 58\" stroke=\"#8A5FC0\" stroke-width=\"1.6\" stroke-dasharray=\"3 2\" marker-end=\"url(#a2)\"/>\n<defs><marker id=\"a2\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0 0 L6 3 L0 6 z\" fill=\"#8A5FC0\"/></marker></defs>\n<text x=\"60\" y=\"92\" font-size=\"9.5\" fill=\"#2A2138\" text-anchor=\"middle\">Low angle · imposing</text></svg></div><figcaption>Low angle</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<line x1=\"10\" y1=\"80\" x2=\"110\" y2=\"80\" stroke=\"#DDD6E8\"/>\n<rect x=\"54\" y=\"34\" width=\"14\" height=\"40\" rx=\"6\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><circle cx=\"61\" cy=\"28\" r=\"8\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/>\n<circle cx=\"26\" cy=\"50\" r=\"6\" fill=\"#3D8E8A\"/><path d=\"M32 50 L52 44\" stroke=\"#3D8E8A\" stroke-width=\"1.6\" stroke-dasharray=\"3 2\" marker-end=\"url(#a2_2)\"/>\n<defs><marker id=\"a2_2\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0 0 L6 3 L0 6 z\" fill=\"#3D8E8A\"/></marker></defs>\n<text x=\"60\" y=\"92\" font-size=\"9.5\" fill=\"#2A2138\" text-anchor=\"middle\">Eye level · natural</text></svg></div><figcaption>Eye level</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<line x1=\"10\" y1=\"80\" x2=\"110\" y2=\"80\" stroke=\"#DDD6E8\"/>\n<rect x=\"54\" y=\"34\" width=\"14\" height=\"40\" rx=\"6\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><circle cx=\"61\" cy=\"28\" r=\"8\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/>\n<circle cx=\"26\" cy=\"24\" r=\"6\" fill=\"#B8892E\"/><path d=\"M32 24 L56 34\" stroke=\"#B8892E\" stroke-width=\"1.6\" stroke-dasharray=\"3 2\" marker-end=\"url(#a2_3)\"/>\n<defs><marker id=\"a2_3\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0 0 L6 3 L0 6 z\" fill=\"#B8892E\"/></marker></defs>\n<text x=\"60\" y=\"92\" font-size=\"9.5\" fill=\"#2A2138\" text-anchor=\"middle\">High angle · delicate</text></svg></div><figcaption>High angle</figcaption></figure></div>\n      <div class=\"dgm-grid\"><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<clipPath id=\"c16\"><rect x=\"30\" y=\"16\" width=\"60\" height=\"72\"/></clipPath>\n<g clip-path=\"url(#c16)\"><circle cx=\"60\" cy=\"30\" r=\"13\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><rect x=\"46\" y=\"42\" width=\"28\" height=\"30\" rx=\"8\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><rect x=\"50\" y=\"70\" width=\"20\" height=\"24\" rx=\"6\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/></g>\n<rect x=\"30\" y=\"16\" width=\"60\" height=\"72\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n<text x=\"60\" y=\"92\" font-size=\"9\" fill=\"#2A2138\" text-anchor=\"middle\">Close-up · emotion</text></svg></div><figcaption>Close-up</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<clipPath id=\"c40\"><rect x=\"30\" y=\"40\" width=\"60\" height=\"48\"/></clipPath>\n<g clip-path=\"url(#c40)\"><circle cx=\"60\" cy=\"30\" r=\"13\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><rect x=\"46\" y=\"42\" width=\"28\" height=\"30\" rx=\"8\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><rect x=\"50\" y=\"70\" width=\"20\" height=\"24\" rx=\"6\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/></g>\n<rect x=\"30\" y=\"40\" width=\"60\" height=\"48\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n<text x=\"60\" y=\"92\" font-size=\"9\" fill=\"#2A2138\" text-anchor=\"middle\">Bust · the workhorse</text></svg></div><figcaption>Bust</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<circle cx=\"34\" cy=\"40\" r=\"13\" fill=\"#CFC0E8\" opacity=\".5\"/><circle cx=\"86\" cy=\"40\" r=\"16\" fill=\"#C9BBE4\" opacity=\".4\"/>\n<rect x=\"52\" y=\"30\" width=\"16\" height=\"44\" rx=\"7\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/><circle cx=\"60\" cy=\"24\" r=\"8\" fill=\"#E6DAF0\" stroke=\"#7B6BB5\"/>\n<text x=\"60\" y=\"92\" font-size=\"9\" fill=\"#2A2138\" text-anchor=\"middle\">Shallow DOF · subject pops</text></svg></div><figcaption>Shallow DOF</figcaption></figure></div>\n    </div>\n    <div class=\"card\">\n      <h3>Advanced photography ideas <span class=\"tag gold\">Beyond composition</span></h3>\n      <details><summary>The decisive moment</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"33\" r=\"20\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"2\"/><circle cx=\"55\" cy=\"33\" r=\"4\" fill=\"#8A5FC0\"/><path d=\"M55 13 L55 6 M75 33 L82 33 M55 53 L55 60 M35 33 L28 33\" stroke=\"#8A5FC0\" stroke-width=\"2\"/></svg></span>Cartier-Bresson&#39;s idea: release the shutter <b>when action, emotion and composition all peak at once</b>. Even in posed work — catch the frame where the skirt lifts highest or the glance turns back, far better than a stiff freeze.</p></details>\n      <details><summary>Depth of field trade-off</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"33\" r=\"18\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"2\" opacity=\"1.0\"/><circle cx=\"55\" cy=\"33\" r=\"15\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"2\" opacity=\"0.8200000000000001\"/><circle cx=\"55\" cy=\"33\" r=\"12\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"2\" opacity=\"0.64\"/><circle cx=\"55\" cy=\"33\" r=\"9\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"2\" opacity=\"0.45999999999999996\"/></svg></span><b>Wide aperture (shallow DOF)</b> = creamy background, subject pops, but low margin for error; <b>narrow aperture (deep DOF)</b> = front-to-back sharp, full information, grandeur. Shallow for close-ups, deep for environmental storytelling.</p></details>\n      <details><summary>Negative space as narrative</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"86\" cy=\"46\" r=\"9\" fill=\"#8A5FC0\"/></svg></span>Large empty space isn&#39;t just technique — it <b>tells a story</b>: solitude, smallness, calm, resonance. The empty part is often where the emotion is densest.</p></details>\n      <details><summary>Gaze &amp; the fourth wall</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"30\" r=\"13\" fill=\"#EFE6F5\" stroke=\"#7B6BB5\"/><circle cx=\"55\" cy=\"30\" r=\"3\" fill=\"#2A2138\"/><path d=\"M55 30 L55 62\" stroke=\"#3D8E8A\" stroke-dasharray=\"3 2\"/></svg></span>A subject <b>looking at the lens</b> = direct dialogue with the viewer, more tension; <b>looking off-frame</b> = story and imagination (what are they seeing?). Completely different moods — choose by the story you want.</p></details>\n      <details><summary>Tonal unity (grading)</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"16\" width=\"30\" height=\"34\" rx=\"4\" fill=\"#E05A5A\"/><rect x=\"42\" y=\"16\" width=\"30\" height=\"34\" rx=\"4\" fill=\"#4C93C4\"/><rect x=\"76\" y=\"16\" width=\"26\" height=\"34\" rx=\"4\" fill=\"#9DC44A\"/><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#20A0A0\" opacity=\".28\"/></svg></span>In post, give the whole photo a <b>unified color bias</b> (teal-orange, Morandi, cool blue…) — the fastest step from \"snapshot\" to \"piece\". Set a mood first, then pull every color toward it.</p></details>\n      <details><summary>Room to breathe</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"16\" y=\"14\" width=\"78\" height=\"38\" rx=\"4\" fill=\"none\" stroke=\"#7B6BB5\" stroke-dasharray=\"4 3\"/><circle cx=\"55\" cy=\"33\" r=\"10\" fill=\"#8A5FC0\"/></svg></span>Don&#39;t jam important elements against the frame edge. A little <b>safe margin</b> all around keeps the image from feeling suffocated and leaves room when cropping.</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>Portrait framing <span class=\"tag hot\">look at the person first</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 0\">Every composition rule above applies to portraiture, but portraiture has one variable nothing else has: the person. The analyser now reads shot size, joint cropping, headroom, eye height and head angle - and joint cropping is the rule most often broken and least often flagged.</p>\n    </div>\n    <div class=\"card\">\n      <h3>1. Shot size <span class=\"tag gold\">decide how much body before you raise the camera</span></h3>\n      <details><summary>Close-up</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"34\" r=\"30\" fill=\"#8A5FC0\"/><circle cx=\"45\" cy=\"28\" r=\"3\" fill=\"#fff\"/><circle cx=\"66\" cy=\"28\" r=\"3\" fill=\"#fff\"/></svg></span><i><b>Frame</b>Forehead to chin, or even part of the face - the eyes, the mouth.</i><i><b>Purpose</b>Magnify emotion and read the finest flicker of it. Strip out the environment and force the most intimate possible eye contact.</i><i><b>Key</b>Focus always on the eyes. Cropping into the forehead is fine; cutting exactly at the neck or the jaw is not. Wide aperture for a background that dissolves.</i></p></details>\n      <details><summary>Head and shoulders</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"16\" r=\"7\" fill=\"#8A5FC0\"/><rect x=\"46\" y=\"25\" width=\"18\" height=\"41\" rx=\"6\" fill=\"#8A5FC0\"/><line x1=\"4\" y1=\"52\" x2=\"106\" y2=\"52\" stroke=\"#C0554E\" stroke-dasharray=\"3 3\"/></svg></span><i><b>Frame</b>Crown to collarbone or chest.</i><i><b>Purpose</b>ID photos, casting shots, makeup portfolios. The job is to say clearly what this person looks like.</i><i><b>Key</b>Avoid a wide lens enlarging the nose; light the face evenly; keep the background clean, with space balanced across the top and both sides.</i></p></details>\n      <details><summary>Half length</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"12\" r=\"7\" fill=\"#8A5FC0\"/><rect x=\"46\" y=\"21\" width=\"18\" height=\"45\" rx=\"6\" fill=\"#8A5FC0\"/><line x1=\"4\" y1=\"46\" x2=\"106\" y2=\"46\" stroke=\"#C0554E\" stroke-dasharray=\"3 3\"/></svg></span><i><b>Frame</b>Crown to waist or hip.</i><i><b>Purpose</b>The workhorse of portraiture. The expression still reads, and hands and clothing enter the story.</i><i><b>Key</b>Hand placement decides it. Let the fingers curl naturally; never let an open palm face the lens flat. Keep the crop away from elbows and wrists.</i></p></details>\n      <details><summary>Three-quarter</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"8\" r=\"7\" fill=\"#8A5FC0\"/><rect x=\"46\" y=\"17\" width=\"18\" height=\"49\" rx=\"6\" fill=\"#8A5FC0\"/><line x1=\"4\" y1=\"58\" x2=\"106\" y2=\"58\" stroke=\"#C0554E\" stroke-dasharray=\"3 3\"/></svg></span><i><b>Frame</b>Crown to mid-calf.</i><i><b>Purpose</b>Tighter than full length, but shows more posture and more of how the clothes move than half length does.</i><i><b>Key</b>Never land the cut on the knee or the ankle. A staggered stance lengthens the line.<br><span style=\"color:var(--rose)\">Correction: this framing is often called the \"American shot\", but the plan américain actually cuts at <b>mid-thigh, just above the knee</b> - it comes from Westerns needing the holster in frame. Cutting at the calf is a different (also safe) crop.</span></i></p></details>\n      <details><summary>Full length</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"6\" r=\"7\" fill=\"#8A5FC0\"/><rect x=\"46\" y=\"15\" width=\"18\" height=\"45\" rx=\"6\" fill=\"#8A5FC0\"/></svg></span><i><b>Frame</b>Crown to feet.</i><i><b>Purpose</b>Shows the whole outfit, the body language, and the relationship between person and place. Right for street and fashion.</i><i><b>Key</b>A low angle on the wide end lengthens the legs. Leave measured space above the head and below the feet, and keep the horizon off the neck.</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>2. Portrait-specific composition <span class=\"tag ok\">the general rules, applied to a person</span></h3>\n      <details><summary>Gaze room</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"34\" cy=\"30\" r=\"11\" fill=\"#8A5FC0\"/><rect x=\"52\" y=\"8\" width=\"52\" height=\"50\" rx=\"4\" fill=\"#7B6BB5\" opacity=\".10\"/><path d=\"M46 28 L96 24\" stroke=\"#7B6BB5\" stroke-width=\"1.2\" stroke-dasharray=\"3 3\"/></svg></span><i><b>Frame</b>Leave more space on the side the sitter is looking toward than behind their head.</i><i><b>Purpose</b>The viewer follows the look, which creates conversation and extends the story. Eyes left with the body jammed against the left edge feels oppressive.</i><i><b>Key</b>The exception: pressing the sitter against the edge they are looking at deliberately manufactures isolation and being cornered.</i></p></details>\n      <details><summary>Headroom</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"40\" r=\"14\" fill=\"#8A5FC0\"/><line x1=\"6\" y1=\"18\" x2=\"104\" y2=\"18\" stroke=\"#7B6BB5\" stroke-dasharray=\"3 3\"/><text x=\"55\" y=\"13\" font-size=\"7.5\" fill=\"#7B6BB5\" text-anchor=\"middle\">headroom</text></svg></span><i><b>Frame</b>The gap between the crown and the top of the frame has to be judged, not left to chance.</i><i><b>Purpose</b>A shaved or touching crown reads as hitting a wall; too much and the figure sinks into the bottom of the frame.</i><i><b>Key</b>Close-ups and head shots can crop into the crown. At half length and wider, keep the whole head outline plus a little air.</i></p></details>\n      <details><summary>Never cut at a joint</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"44\" y=\"4\" width=\"22\" height=\"58\" rx=\"8\" fill=\"#8A5FC0\"/><g stroke=\"#C0554E\" stroke-width=\"2\"><line x1=\"30\" y1=\"20\" x2=\"80\" y2=\"20\"/><line x1=\"30\" y1=\"44\" x2=\"80\" y2=\"44\"/></g><g stroke=\"#3D8E8A\" stroke-width=\"2\"><line x1=\"34\" y1=\"32\" x2=\"76\" y2=\"32\"/></g></svg></span><i><b>Frame</b>The rule most easily broken and most often ignored.</i><i><b>Purpose</b><b>Safe cuts</b>: mid-thigh, mid-upper-arm, mid-calf. <b>Never cut at</b>: neck, elbow, wrist, knee, ankle, waist.</i><i><b>Key</b>A cut at a joint reads as amputation and viewers feel it whether or not they can name it. The analyser now checks this automatically.</i></p></details>\n      <details><summary>Foreground and background layers</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"30\" r=\"12\" fill=\"#8A5FC0\"/><path d=\"M2 66 C22 46 32 60 44 66 Z\" fill=\"#7B6BB5\" opacity=\".5\"/><path d=\"M108 66 C88 44 76 58 64 66 Z\" fill=\"#7B6BB5\" opacity=\".5\"/></svg></span><i><b>Frame</b>Build space with depth of field.</i><i><b>Purpose</b>Grass, gauze or glass in front of the lens blurs into a block of colour, adding a sense of looking in - useful for breaking up a frame that is too plain.</i><i><b>Key</b>For the background, pick streets or stairs with leading lines. An environmental portrait usually succeeds or fails on whether the background's lines serve the person.</i></p></details>\n      <details><summary>Framing the person</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"18\" y=\"8\" width=\"74\" height=\"50\" rx=\"5\" fill=\"none\" stroke=\"#7B6BB5\" stroke-width=\"5\" opacity=\".35\"/><circle cx=\"55\" cy=\"32\" r=\"11\" fill=\"#8A5FC0\"/></svg></span><i><b>Frame</b>Surround the sitter with a doorway, a window, a gap in branches.</i><i><b>Purpose</b>The frame shuts out the clutter and makes the eye jump straight to the face inside it.</i><i><b>Key</b>In portraiture a frame also implies protection, which makes the sitter look more settled and more storied.</i></p></details>\n      <details><summary>Negative space for emotion</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"86\" cy=\"42\" r=\"8\" fill=\"#8A5FC0\"/><rect x=\"8\" y=\"8\" width=\"60\" height=\"50\" rx=\"5\" fill=\"#7B6BB5\" opacity=\".07\"/></svg></span><i><b>Frame</b>Lots of empty frame with the person in one corner.</i><i><b>Purpose</b>The same device carries completely different feelings depending on the person's size and where they are looking.</i><i><b>Key</b>Isolation (tiny figure, huge space) / freedom (gaze into open sky) / minimal fashion (precisely off-centre on a flat backdrop).</i></p></details>\n      <details><summary>Geometry from the body</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><polygon points=\"55,10 88,56 22,56\" fill=\"none\" stroke=\"#7B6BB5\" stroke-dasharray=\"4 3\"/><path d=\"M55 14 C40 26 68 36 52 50\" stroke=\"#8A5FC0\" stroke-width=\"2.5\" fill=\"none\"/></svg></span><i><b>Frame</b>Not just the background's lines - the body's own.</i><i><b>Purpose</b><b>Triangle</b>: an arm propping the head, hands on hips, a knee drawn up. Instant weight. <b>S-curve</b>: weight on one foot, hip tilted, shoulders counter-tilted. <b>Diagonal</b>: reclining or leaning, the body's axis crossing the frame.</i><i><b>Key</b>The S-curve is the classic pose, running as one continuous line from neck through chest and waist to legs.</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>3. The deeper habits <span class=\"tag warn\">composition always serves the person</span></h3>\n      <details><summary>The eyes are sacred</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-dasharray=\"3 3\"><line x1=\"37\" y1=\"4\" x2=\"37\" y2=\"62\"/><line x1=\"73\" y1=\"4\" x2=\"73\" y2=\"62\"/><line x1=\"4\" y1=\"22\" x2=\"106\" y2=\"22\"/></g><circle cx=\"37\" cy=\"22\" r=\"5\" fill=\"#8A5FC0\"/><circle cx=\"73\" cy=\"22\" r=\"5\" fill=\"#8A5FC0\"/></svg></span><i><b>Frame</b>The closest thing portraiture has to an iron rule.</i><i><b>Purpose</b>The eyes are always the sharpest and brightest point in the frame. They are the first thing any viewer looks for.</i><i><b>Key</b>Eyes near one of the two upper intersections of the thirds grid is the most natural place for them.</i></p></details>\n      <details><summary>Perspective and lens choice</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><ellipse cx=\"30\" cy=\"34\" rx=\"17\" ry=\"22\" fill=\"#8A5FC0\" opacity=\".45\"/><ellipse cx=\"78\" cy=\"34\" rx=\"11\" ry=\"21\" fill=\"#8A5FC0\"/></svg></span><i><b>Frame</b>Framing is bound to focal length.</i><i><b>Purpose</b><b>24-35mm</b>: up close, whatever is nearest is exaggerated. Good for lengthening legs from a low angle, bad for faces. <b>50-135mm</b>: closest to what the eye sees, no distortion - the safe range. <b>200mm+</b>: compresses space, dissolves backgrounds, and lets you catch undisturbed emotion from a distance.</i><i><b>Key</b>The distortion is not really caused by the lens; it is caused by <b>distance</b>. A wide lens makes you step closer, and it is the closeness that enlarges the nose. At the same distance, different focal lengths give identical perspective.</i></p></details>\n      <details><summary>Dutch angle as an emotional switch</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"6\" y1=\"48\" x2=\"104\" y2=\"22\" stroke=\"#7B6BB5\" stroke-width=\"1.6\"/><rect x=\"44\" y=\"16\" width=\"18\" height=\"30\" rx=\"7\" fill=\"#8A5FC0\" transform=\"rotate(-15 53 31)\"/></svg></span><i><b>Frame</b>In portraiture, tilt is not a free effect.</i><i><b>Purpose</b>Use it for: disorder, unease, adolescent defiance, movement, or a fashion shoot deliberately breaking the balance.</i><i><b>Key</b>Do not use it for: formal portraits, weddings, corporate headshots. A crooked horizon there reads as unprofessional.</i></p></details>\n      <details><summary>Frontal, profile and three-quarter</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><ellipse cx=\"34\" cy=\"34\" rx=\"16\" ry=\"21\" fill=\"#8A5FC0\"/><ellipse cx=\"78\" cy=\"34\" rx=\"9\" ry=\"21\" fill=\"#8A5FC0\" opacity=\".6\"/></svg></span><i><b>Frame</b>Three angles, three characters.</i><i><b>Purpose</b><b>Frontal</b>: direct contact, maximum impact. <b>Profile (90 degrees)</b>: strongest outline, suits defined features, reads as reflection or distance. <b>Three-quarter (45 degrees)</b>: the most useful and most flattering.</i><i><b>Key</b>Three-quarter shows both eyes and the face's outline at once, with the light turning naturally across the cheek. It is the default for most portraits.</i></p></details>\n      <details><summary>Hands and face</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"55\" cy=\"26\" r=\"14\" fill=\"#8A5FC0\"/><path d=\"M40 44 C46 36 52 40 55 44\" stroke=\"#7B6BB5\" stroke-width=\"3\" fill=\"none\" stroke-linecap=\"round\"/></svg></span><i><b>Frame</b>At half length and tighter, the hands decide it.</i><i><b>Purpose</b>Hands can rest at the chin, cheek or lips, but must never press into the face.</i><i><b>Key</b>Keep the fingers softly curled; never splay all five at the lens, which makes them read far larger than they are. Hands near the frame edge follow the same no-joint-cropping rule.</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>In summary <span class=\"tag gold\">look at the person, then apply the rule</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 0\">Composition always serves the person's emotion, presence and story. If your head is full of thirds and leading lines while you miss what the sitter's eyes and body are doing right now, a technically correct photograph is still an empty formula. A good portrait is composition, light and the soul of that particular moment, all at once.</p>\n    </div>\n", "ae-color": "\n    <div class=\"card\">\n      <h3>Color wheel diagrams <span class=\"tag ok\">Schemes at a glance</span></h3>\n      <div class=\"dgm-grid\">\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 120\" role=\"img\"><path d=\"M60.0 8.0 A52 52 0 0 1 86.0 15.0 L75.0 34.0 A30 30 0 0 0 60.0 30.0 Z\" fill=\"#E05A5A\" opacity=\"1\"/><path d=\"M86.0 15.0 A52 52 0 0 1 105.0 34.0 L86.0 45.0 A30 30 0 0 0 75.0 34.0 Z\" fill=\"#E0813F\" opacity=\"1\"/><path d=\"M105.0 34.0 A52 52 0 0 1 112.0 60.0 L90.0 60.0 A30 30 0 0 0 86.0 45.0 Z\" fill=\"#E0A93F\" opacity=\"1\"/><path d=\"M112.0 60.0 A52 52 0 0 1 105.0 86.0 L86.0 75.0 A30 30 0 0 0 90.0 60.0 Z\" fill=\"#D7C63F\" opacity=\"1\"/><path d=\"M105.0 86.0 A52 52 0 0 1 86.0 105.0 L75.0 86.0 A30 30 0 0 0 86.0 75.0 Z\" fill=\"#9DC44A\" opacity=\"1\"/><path d=\"M86.0 105.0 A52 52 0 0 1 60.0 112.0 L60.0 90.0 A30 30 0 0 0 75.0 86.0 Z\" fill=\"#5FB36A\" opacity=\"1\"/><path d=\"M60.0 112.0 A52 52 0 0 1 34.0 105.0 L45.0 86.0 A30 30 0 0 0 60.0 90.0 Z\" fill=\"#4CB0A6\" opacity=\"1\"/><path d=\"M34.0 105.0 A52 52 0 0 1 15.0 86.0 L34.0 75.0 A30 30 0 0 0 45.0 86.0 Z\" fill=\"#4C93C4\" opacity=\"1\"/><path d=\"M15.0 86.0 A52 52 0 0 1 8.0 60.0 L30.0 60.0 A30 30 0 0 0 34.0 75.0 Z\" fill=\"#5A6FC0\" opacity=\"1\"/><path d=\"M8.0 60.0 A52 52 0 0 1 15.0 34.0 L34.0 45.0 A30 30 0 0 0 30.0 60.0 Z\" fill=\"#7B5FC0\" opacity=\"1\"/><path d=\"M15.0 34.0 A52 52 0 0 1 34.0 15.0 L45.0 34.0 A30 30 0 0 0 34.0 45.0 Z\" fill=\"#A85FC0\" opacity=\"1\"/><path d=\"M34.0 15.0 A52 52 0 0 1 60.0 8.0 L60.0 30.0 A30 30 0 0 0 45.0 34.0 Z\" fill=\"#C45A93\" opacity=\"1\"/></svg></div><figcaption>12-hue color wheel</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 120\" role=\"img\"><path d=\"M60.0 8.0 A52 52 0 0 1 86.0 15.0 L75.0 34.0 A30 30 0 0 0 60.0 30.0 Z\" fill=\"#E05A5A\" opacity=\"0.22\"/><path d=\"M86.0 15.0 A52 52 0 0 1 105.0 34.0 L86.0 45.0 A30 30 0 0 0 75.0 34.0 Z\" fill=\"#E0813F\" opacity=\"0.22\"/><path d=\"M105.0 34.0 A52 52 0 0 1 112.0 60.0 L90.0 60.0 A30 30 0 0 0 86.0 45.0 Z\" fill=\"#E0A93F\" opacity=\"0.22\"/><path d=\"M112.0 60.0 A52 52 0 0 1 105.0 86.0 L86.0 75.0 A30 30 0 0 0 90.0 60.0 Z\" fill=\"#D7C63F\" opacity=\"0.22\"/><path d=\"M105.0 86.0 A52 52 0 0 1 86.0 105.0 L75.0 86.0 A30 30 0 0 0 86.0 75.0 Z\" fill=\"#9DC44A\" opacity=\"0.22\"/><path d=\"M86.0 105.0 A52 52 0 0 1 60.0 112.0 L60.0 90.0 A30 30 0 0 0 75.0 86.0 Z\" fill=\"#5FB36A\" opacity=\"0.22\"/><path d=\"M60.0 112.0 A52 52 0 0 1 34.0 105.0 L45.0 86.0 A30 30 0 0 0 60.0 90.0 Z\" fill=\"#4CB0A6\" opacity=\"0.22\"/><path d=\"M34.0 105.0 A52 52 0 0 1 15.0 86.0 L34.0 75.0 A30 30 0 0 0 45.0 86.0 Z\" fill=\"#4C93C4\" opacity=\"0.22\"/><path d=\"M15.0 86.0 A52 52 0 0 1 8.0 60.0 L30.0 60.0 A30 30 0 0 0 34.0 75.0 Z\" fill=\"#5A6FC0\" opacity=\"1\"/><path d=\"M8.0 60.0 A52 52 0 0 1 15.0 34.0 L34.0 45.0 A30 30 0 0 0 30.0 60.0 Z\" fill=\"#7B5FC0\" opacity=\"1\"/><path d=\"M15.0 34.0 A52 52 0 0 1 34.0 15.0 L45.0 34.0 A30 30 0 0 0 34.0 45.0 Z\" fill=\"#A85FC0\" opacity=\"1\"/><path d=\"M34.0 15.0 A52 52 0 0 1 60.0 8.0 L60.0 30.0 A30 30 0 0 0 45.0 34.0 Z\" fill=\"#C45A93\" opacity=\"0.22\"/><polygon points=\"20.4,70.6 20.4,49.4 31.0,31.0\" fill=\"none\" stroke=\"#2A2138\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/></svg></div><figcaption>Analogous · harmonious</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 120\" role=\"img\"><path d=\"M60.0 8.0 A52 52 0 0 1 86.0 15.0 L75.0 34.0 A30 30 0 0 0 60.0 30.0 Z\" fill=\"#E05A5A\" opacity=\"1\"/><path d=\"M86.0 15.0 A52 52 0 0 1 105.0 34.0 L86.0 45.0 A30 30 0 0 0 75.0 34.0 Z\" fill=\"#E0813F\" opacity=\"0.22\"/><path d=\"M105.0 34.0 A52 52 0 0 1 112.0 60.0 L90.0 60.0 A30 30 0 0 0 86.0 45.0 Z\" fill=\"#E0A93F\" opacity=\"0.22\"/><path d=\"M112.0 60.0 A52 52 0 0 1 105.0 86.0 L86.0 75.0 A30 30 0 0 0 90.0 60.0 Z\" fill=\"#D7C63F\" opacity=\"0.22\"/><path d=\"M105.0 86.0 A52 52 0 0 1 86.0 105.0 L75.0 86.0 A30 30 0 0 0 86.0 75.0 Z\" fill=\"#9DC44A\" opacity=\"0.22\"/><path d=\"M86.0 105.0 A52 52 0 0 1 60.0 112.0 L60.0 90.0 A30 30 0 0 0 75.0 86.0 Z\" fill=\"#5FB36A\" opacity=\"0.22\"/><path d=\"M60.0 112.0 A52 52 0 0 1 34.0 105.0 L45.0 86.0 A30 30 0 0 0 60.0 90.0 Z\" fill=\"#4CB0A6\" opacity=\"1\"/><path d=\"M34.0 105.0 A52 52 0 0 1 15.0 86.0 L34.0 75.0 A30 30 0 0 0 45.0 86.0 Z\" fill=\"#4C93C4\" opacity=\"0.22\"/><path d=\"M15.0 86.0 A52 52 0 0 1 8.0 60.0 L30.0 60.0 A30 30 0 0 0 34.0 75.0 Z\" fill=\"#5A6FC0\" opacity=\"0.22\"/><path d=\"M8.0 60.0 A52 52 0 0 1 15.0 34.0 L34.0 45.0 A30 30 0 0 0 30.0 60.0 Z\" fill=\"#7B5FC0\" opacity=\"0.22\"/><path d=\"M15.0 34.0 A52 52 0 0 1 34.0 15.0 L45.0 34.0 A30 30 0 0 0 34.0 45.0 Z\" fill=\"#A85FC0\" opacity=\"0.22\"/><path d=\"M34.0 15.0 A52 52 0 0 1 60.0 8.0 L60.0 30.0 A30 30 0 0 0 45.0 34.0 Z\" fill=\"#C45A93\" opacity=\"0.22\"/><line x1=\"70.6\" y1=\"20.4\" x2=\"49.4\" y2=\"99.6\" stroke=\"#2A2138\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/></svg></div><figcaption>Complementary · maximum contrast</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 120\" role=\"img\"><path d=\"M60.0 8.0 A52 52 0 0 1 86.0 15.0 L75.0 34.0 A30 30 0 0 0 60.0 30.0 Z\" fill=\"#E05A5A\" opacity=\"1\"/><path d=\"M86.0 15.0 A52 52 0 0 1 105.0 34.0 L86.0 45.0 A30 30 0 0 0 75.0 34.0 Z\" fill=\"#E0813F\" opacity=\"0.22\"/><path d=\"M105.0 34.0 A52 52 0 0 1 112.0 60.0 L90.0 60.0 A30 30 0 0 0 86.0 45.0 Z\" fill=\"#E0A93F\" opacity=\"0.22\"/><path d=\"M112.0 60.0 A52 52 0 0 1 105.0 86.0 L86.0 75.0 A30 30 0 0 0 90.0 60.0 Z\" fill=\"#D7C63F\" opacity=\"0.22\"/><path d=\"M105.0 86.0 A52 52 0 0 1 86.0 105.0 L75.0 86.0 A30 30 0 0 0 86.0 75.0 Z\" fill=\"#9DC44A\" opacity=\"1\"/><path d=\"M86.0 105.0 A52 52 0 0 1 60.0 112.0 L60.0 90.0 A30 30 0 0 0 75.0 86.0 Z\" fill=\"#5FB36A\" opacity=\"0.22\"/><path d=\"M60.0 112.0 A52 52 0 0 1 34.0 105.0 L45.0 86.0 A30 30 0 0 0 60.0 90.0 Z\" fill=\"#4CB0A6\" opacity=\"0.22\"/><path d=\"M34.0 105.0 A52 52 0 0 1 15.0 86.0 L34.0 75.0 A30 30 0 0 0 45.0 86.0 Z\" fill=\"#4C93C4\" opacity=\"0.22\"/><path d=\"M15.0 86.0 A52 52 0 0 1 8.0 60.0 L30.0 60.0 A30 30 0 0 0 34.0 75.0 Z\" fill=\"#5A6FC0\" opacity=\"1\"/><path d=\"M8.0 60.0 A52 52 0 0 1 15.0 34.0 L34.0 45.0 A30 30 0 0 0 30.0 60.0 Z\" fill=\"#7B5FC0\" opacity=\"0.22\"/><path d=\"M15.0 34.0 A52 52 0 0 1 34.0 15.0 L45.0 34.0 A30 30 0 0 0 34.0 45.0 Z\" fill=\"#A85FC0\" opacity=\"0.22\"/><path d=\"M34.0 15.0 A52 52 0 0 1 60.0 8.0 L60.0 30.0 A30 30 0 0 0 45.0 34.0 Z\" fill=\"#C45A93\" opacity=\"0.22\"/><polygon points=\"70.6,20.4 89.0,89.0 20.4,70.6\" fill=\"none\" stroke=\"#2A2138\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/></svg></div><figcaption>Triadic · evenly spaced</figcaption></figure>\n      </div>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 240 46\" role=\"img\">\n<rect x=\"0\" y=\"6\" width=\"144\" height=\"26\" rx=\"4\" fill=\"#7B6BB5\"/>\n<rect x=\"148\" y=\"6\" width=\"72\" height=\"26\" rx=\"4\" fill=\"#7B6BB5\" opacity=\".45\"/>\n<rect x=\"224\" y=\"6\" width=\"16\" height=\"26\" rx=\"4\" fill=\"#B8892E\"/>\n<text x=\"60\" y=\"24\" font-size=\"11\" fill=\"#fff\">Main 60%</text>\n<text x=\"158\" y=\"24\" font-size=\"10\" fill=\"#fff\">2nd 30%</text>\n<text x=\"196\" y=\"44\" font-size=\"9\" fill=\"#B8892E\">Accent 10%</text></svg></div><figcaption>60-30-10: dominant, secondary, accent</figcaption></figure>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 240 70\" role=\"img\">\n<rect x=\"2\" y=\"6\" width=\"112\" height=\"58\" rx=\"6\" fill=\"#6E5FA8\"/><circle cx=\"58\" cy=\"35\" r=\"18\" fill=\"#B9A9E0\"/>\n<text x=\"8\" y=\"20\" font-size=\"9\" fill=\"#fff\">Values differ ✓</text>\n<rect x=\"126\" y=\"6\" width=\"112\" height=\"58\" rx=\"6\" fill=\"#8478B0\"/><circle cx=\"182\" cy=\"35\" r=\"18\" fill=\"#8B80B6\"/>\n<text x=\"132\" y=\"20\" font-size=\"9\" fill=\"#fff\">Too close ✗</text></svg></div><figcaption>Value test: the subject must survive in greyscale</figcaption></figure>\n    </div>\n    <div class=\"card\">\n      <h3>Color schemes <span class=\"tag gold\">Follow these and you&#39;re fine</span></h3>\n      <details><summary>Monochrome</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"22\" width=\"16\" height=\"22\" rx=\"3\" fill=\"#4A3A80\"/><rect x=\"28\" y=\"22\" width=\"16\" height=\"22\" rx=\"3\" fill=\"#6E5FA8\"/><rect x=\"46\" y=\"22\" width=\"16\" height=\"22\" rx=\"3\" fill=\"#9184C4\"/><rect x=\"64\" y=\"22\" width=\"16\" height=\"22\" rx=\"3\" fill=\"#B4A9DC\"/></svg></span>One hue, varying only <b>value and saturation</b> (pale violet → violet → deep violet). Safest, most refined, most unified — fight monotony with material contrast.</p></details>\n      <details><summary>Analogous</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 66 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"64\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M33.0 7.0 A26 26 0 0 1 46.0 10.5 L40.5 20.0 A15 15 0 0 0 33.0 18.0 Z\" fill=\"#E05A5A\" opacity=\"0.2\"/><path d=\"M46.0 10.5 A26 26 0 0 1 55.5 20.0 L46.0 25.5 A15 15 0 0 0 40.5 20.0 Z\" fill=\"#E0813F\" opacity=\"0.2\"/><path d=\"M55.5 20.0 A26 26 0 0 1 59.0 33.0 L48.0 33.0 A15 15 0 0 0 46.0 25.5 Z\" fill=\"#E0A93F\" opacity=\"0.2\"/><path d=\"M59.0 33.0 A26 26 0 0 1 55.5 46.0 L46.0 40.5 A15 15 0 0 0 48.0 33.0 Z\" fill=\"#D7C63F\" opacity=\"0.2\"/><path d=\"M55.5 46.0 A26 26 0 0 1 46.0 55.5 L40.5 46.0 A15 15 0 0 0 46.0 40.5 Z\" fill=\"#9DC44A\" opacity=\"0.2\"/><path d=\"M46.0 55.5 A26 26 0 0 1 33.0 59.0 L33.0 48.0 A15 15 0 0 0 40.5 46.0 Z\" fill=\"#5FB36A\" opacity=\"0.2\"/><path d=\"M33.0 59.0 A26 26 0 0 1 20.0 55.5 L25.5 46.0 A15 15 0 0 0 33.0 48.0 Z\" fill=\"#4CB0A6\" opacity=\"0.2\"/><path d=\"M20.0 55.5 A26 26 0 0 1 10.5 46.0 L20.0 40.5 A15 15 0 0 0 25.5 46.0 Z\" fill=\"#4C93C4\" opacity=\"0.2\"/><path d=\"M10.5 46.0 A26 26 0 0 1 7.0 33.0 L18.0 33.0 A15 15 0 0 0 20.0 40.5 Z\" fill=\"#5A6FC0\" opacity=\"1\"/><path d=\"M7.0 33.0 A26 26 0 0 1 10.5 20.0 L20.0 25.5 A15 15 0 0 0 18.0 33.0 Z\" fill=\"#7B5FC0\" opacity=\"1\"/><path d=\"M10.5 20.0 A26 26 0 0 1 20.0 10.5 L25.5 20.0 A15 15 0 0 0 20.0 25.5 Z\" fill=\"#A85FC0\" opacity=\"1\"/><path d=\"M20.0 10.5 A26 26 0 0 1 33.0 7.0 L33.0 18.0 A15 15 0 0 0 25.5 20.0 Z\" fill=\"#C45A93\" opacity=\"0.2\"/></svg></span>Neighbors on the color wheel (blue + blue-violet + violet). <b>Harmonious yet richer than monochrome</b> — the best everyday choice.</p></details>\n      <details><summary>Complementary</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 66 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"64\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M33.0 7.0 A26 26 0 0 1 46.0 10.5 L40.5 20.0 A15 15 0 0 0 33.0 18.0 Z\" fill=\"#E05A5A\" opacity=\"1\"/><path d=\"M46.0 10.5 A26 26 0 0 1 55.5 20.0 L46.0 25.5 A15 15 0 0 0 40.5 20.0 Z\" fill=\"#E0813F\" opacity=\"0.2\"/><path d=\"M55.5 20.0 A26 26 0 0 1 59.0 33.0 L48.0 33.0 A15 15 0 0 0 46.0 25.5 Z\" fill=\"#E0A93F\" opacity=\"0.2\"/><path d=\"M59.0 33.0 A26 26 0 0 1 55.5 46.0 L46.0 40.5 A15 15 0 0 0 48.0 33.0 Z\" fill=\"#D7C63F\" opacity=\"0.2\"/><path d=\"M55.5 46.0 A26 26 0 0 1 46.0 55.5 L40.5 46.0 A15 15 0 0 0 46.0 40.5 Z\" fill=\"#9DC44A\" opacity=\"0.2\"/><path d=\"M46.0 55.5 A26 26 0 0 1 33.0 59.0 L33.0 48.0 A15 15 0 0 0 40.5 46.0 Z\" fill=\"#5FB36A\" opacity=\"0.2\"/><path d=\"M33.0 59.0 A26 26 0 0 1 20.0 55.5 L25.5 46.0 A15 15 0 0 0 33.0 48.0 Z\" fill=\"#4CB0A6\" opacity=\"1\"/><path d=\"M20.0 55.5 A26 26 0 0 1 10.5 46.0 L20.0 40.5 A15 15 0 0 0 25.5 46.0 Z\" fill=\"#4C93C4\" opacity=\"0.2\"/><path d=\"M10.5 46.0 A26 26 0 0 1 7.0 33.0 L18.0 33.0 A15 15 0 0 0 20.0 40.5 Z\" fill=\"#5A6FC0\" opacity=\"0.2\"/><path d=\"M7.0 33.0 A26 26 0 0 1 10.5 20.0 L20.0 25.5 A15 15 0 0 0 18.0 33.0 Z\" fill=\"#7B5FC0\" opacity=\"0.2\"/><path d=\"M10.5 20.0 A26 26 0 0 1 20.0 10.5 L25.5 20.0 A15 15 0 0 0 20.0 25.5 Z\" fill=\"#A85FC0\" opacity=\"0.2\"/><path d=\"M20.0 10.5 A26 26 0 0 1 33.0 7.0 L33.0 18.0 A15 15 0 0 0 25.5 20.0 Z\" fill=\"#C45A93\" opacity=\"0.2\"/></svg></span>Opposites on the wheel (red↔green, blue↔orange, yellow↔violet). <b>Maximum impact</b>, but easily gaudy — the trick is <b>one big, one small</b>: the main color dominates, the complement is a mere accent.</p></details>\n      <details><summary>Triadic</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 66 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"64\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M33.0 7.0 A26 26 0 0 1 46.0 10.5 L40.5 20.0 A15 15 0 0 0 33.0 18.0 Z\" fill=\"#E05A5A\" opacity=\"1\"/><path d=\"M46.0 10.5 A26 26 0 0 1 55.5 20.0 L46.0 25.5 A15 15 0 0 0 40.5 20.0 Z\" fill=\"#E0813F\" opacity=\"0.2\"/><path d=\"M55.5 20.0 A26 26 0 0 1 59.0 33.0 L48.0 33.0 A15 15 0 0 0 46.0 25.5 Z\" fill=\"#E0A93F\" opacity=\"0.2\"/><path d=\"M59.0 33.0 A26 26 0 0 1 55.5 46.0 L46.0 40.5 A15 15 0 0 0 48.0 33.0 Z\" fill=\"#D7C63F\" opacity=\"0.2\"/><path d=\"M55.5 46.0 A26 26 0 0 1 46.0 55.5 L40.5 46.0 A15 15 0 0 0 46.0 40.5 Z\" fill=\"#9DC44A\" opacity=\"1\"/><path d=\"M46.0 55.5 A26 26 0 0 1 33.0 59.0 L33.0 48.0 A15 15 0 0 0 40.5 46.0 Z\" fill=\"#5FB36A\" opacity=\"0.2\"/><path d=\"M33.0 59.0 A26 26 0 0 1 20.0 55.5 L25.5 46.0 A15 15 0 0 0 33.0 48.0 Z\" fill=\"#4CB0A6\" opacity=\"0.2\"/><path d=\"M20.0 55.5 A26 26 0 0 1 10.5 46.0 L20.0 40.5 A15 15 0 0 0 25.5 46.0 Z\" fill=\"#4C93C4\" opacity=\"0.2\"/><path d=\"M10.5 46.0 A26 26 0 0 1 7.0 33.0 L18.0 33.0 A15 15 0 0 0 20.0 40.5 Z\" fill=\"#5A6FC0\" opacity=\"1\"/><path d=\"M7.0 33.0 A26 26 0 0 1 10.5 20.0 L20.0 25.5 A15 15 0 0 0 18.0 33.0 Z\" fill=\"#7B5FC0\" opacity=\"0.2\"/><path d=\"M10.5 20.0 A26 26 0 0 1 20.0 10.5 L25.5 20.0 A15 15 0 0 0 20.0 25.5 Z\" fill=\"#A85FC0\" opacity=\"0.2\"/><path d=\"M20.0 10.5 A26 26 0 0 1 33.0 7.0 L33.0 18.0 A15 15 0 0 0 25.5 20.0 Z\" fill=\"#C45A93\" opacity=\"0.2\"/></svg></span>Three evenly spaced hues. Lively, rich, festive — again, <b>rank them</b>; never use all three equally.</p></details>\n      <details><summary>The 60-30-10 rule</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"22\" width=\"58\" height=\"22\" rx=\"3\" fill=\"#7B6BB5\"/><rect x=\"68\" y=\"22\" width=\"28\" height=\"22\" rx=\"3\" fill=\"#7B6BB5\" opacity=\".45\"/><rect x=\"98\" y=\"22\" width=\"8\" height=\"22\" rx=\"2\" fill=\"#B8892E\"/></svg></span>The most practical formula: <b>60% dominant</b> (sets the tone) + <b>30% secondary</b> (adds richness) + <b>10% accent</b> (the highlight, usually brightest). When styling stalls, apply this.</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>Color psychology &amp; value <span class=\"tag ok\">Mood control</span></h3>\n      <ul class=\"tips\">\n        <li><b>Value sets the mood</b>high (light) = airy, pure, dreamy; low (dark) = heavy, mysterious, luxurious.</li>\n        <li><b>Saturation sets intensity</b>high = vivid and loud; low (muted) = elegant, mature, cinematic. <b>Desaturating is the fastest way to look refined.</b></li>\n        <li><b>Temperature sets distance</b>warm advances (larger, closer), cool recedes (farther, calmer). To make the subject pop: <b>warm subject + cool background</b>.</li>\n        <li><b>Color feelings</b>white = purity/blankness, black = mystery/mourning, red = desire/danger, blue = melancholy/calm, purple = nobility/mystery, gold-silver = opulence/cold.</li>\n        <li><b>Neutrals are the universal fixer</b>when colors fight, adding black, white, grey, gold or silver instantly pulls it together.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Color theory basics <span class=\"tag gold\">Three attributes</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">Once you see color on three axes, palettes stop being guesswork.</p>\n      <ul class=\"tips\">\n        <li><b>Hue</b>the color itself (red, blue, green…) — its position on the <b>color wheel</b>. It answers \"which color\".</li>\n        <li><b>Value / brightness</b>light to dark. <b>Value matters most of the three</b> — convert the image to greyscale; if the subject disappears, your values are too close.</li>\n        <li><b>Saturation / chroma</b>how vivid the color is. High = intense; low (greyed) = elegant and refined.</li>\n        <li><b>Primary → secondary → tertiary</b>primaries mix into secondaries, then into greyed tertiaries. <b>Tertiaries wear best</b> and carry most sophisticated palettes.</li>\n        <li><b>Distance on the wheel = relationship</b>adjacent (within 30°) = analogous, harmonious; 90° = moderate variety; 180° = complementary, maximum contrast.</li>\n        <li><b>Color is relational, never absolute</b>the same grey looks light on a dark ground and dark on a light one (<b>simultaneous contrast</b>). Always judge in context.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Itten&#39;s seven color contrasts <span class=\"tag hot\">Itten</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">Bauhaus master Johannes Itten&#39;s seven contrasts — the complete toolbox for color design.</p>\n      <details><summary>① Contrast of hue</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 66 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"64\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M33.0 7.0 A26 26 0 0 1 46.0 10.5 L40.5 20.0 A15 15 0 0 0 33.0 18.0 Z\" fill=\"#E05A5A\" opacity=\"1\"/><path d=\"M46.0 10.5 A26 26 0 0 1 55.5 20.0 L46.0 25.5 A15 15 0 0 0 40.5 20.0 Z\" fill=\"#E0813F\" opacity=\"0.2\"/><path d=\"M55.5 20.0 A26 26 0 0 1 59.0 33.0 L48.0 33.0 A15 15 0 0 0 46.0 25.5 Z\" fill=\"#E0A93F\" opacity=\"0.2\"/><path d=\"M59.0 33.0 A26 26 0 0 1 55.5 46.0 L46.0 40.5 A15 15 0 0 0 48.0 33.0 Z\" fill=\"#D7C63F\" opacity=\"0.2\"/><path d=\"M55.5 46.0 A26 26 0 0 1 46.0 55.5 L40.5 46.0 A15 15 0 0 0 46.0 40.5 Z\" fill=\"#9DC44A\" opacity=\"1\"/><path d=\"M46.0 55.5 A26 26 0 0 1 33.0 59.0 L33.0 48.0 A15 15 0 0 0 40.5 46.0 Z\" fill=\"#5FB36A\" opacity=\"0.2\"/><path d=\"M33.0 59.0 A26 26 0 0 1 20.0 55.5 L25.5 46.0 A15 15 0 0 0 33.0 48.0 Z\" fill=\"#4CB0A6\" opacity=\"0.2\"/><path d=\"M20.0 55.5 A26 26 0 0 1 10.5 46.0 L20.0 40.5 A15 15 0 0 0 25.5 46.0 Z\" fill=\"#4C93C4\" opacity=\"0.2\"/><path d=\"M10.5 46.0 A26 26 0 0 1 7.0 33.0 L18.0 33.0 A15 15 0 0 0 20.0 40.5 Z\" fill=\"#5A6FC0\" opacity=\"1\"/><path d=\"M7.0 33.0 A26 26 0 0 1 10.5 20.0 L20.0 25.5 A15 15 0 0 0 18.0 33.0 Z\" fill=\"#7B5FC0\" opacity=\"0.2\"/><path d=\"M10.5 20.0 A26 26 0 0 1 20.0 10.5 L25.5 20.0 A15 15 0 0 0 20.0 25.5 Z\" fill=\"#A85FC0\" opacity=\"0.2\"/><path d=\"M20.0 10.5 A26 26 0 0 1 33.0 7.0 L33.0 18.0 A15 15 0 0 0 25.5 20.0 Z\" fill=\"#C45A93\" opacity=\"0.2\"/></svg></span>Pure hues against each other — red vs blue vs yellow. <b>The most primal, vivid and energetic</b>, but also the easiest to look childish. When using it, <b>vary the areas</b>.</p></details>\n      <details><summary>② Light–dark contrast</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"20\" width=\"40\" height=\"26\" rx=\"3\" fill=\"#EEE9F6\"/><rect x=\"60\" y=\"20\" width=\"40\" height=\"26\" rx=\"3\" fill=\"#2A2138\"/></svg></span>Light against dark — <b>the most important one</b>. A black-and-white photo has only this contrast and still works; that&#39;s the proof. Too little and everything mushes together.</p></details>\n      <details><summary>③ Warm–cool contrast</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"20\" width=\"40\" height=\"26\" rx=\"3\" fill=\"#D8823F\"/><rect x=\"60\" y=\"20\" width=\"40\" height=\"26\" rx=\"3\" fill=\"#4C93C4\"/></svg></span>Warm (red-orange-yellow) against cool (blue-cyan-green). It delivers both <b>space</b> (warm advances, cool recedes) and <b>emotion</b> (warm feeling, cool reason). <b>Cool background + warm subject</b> is the universal recipe.</p></details>\n      <details><summary>④ Complementary contrast</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 66 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"64\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M33.0 7.0 A26 26 0 0 1 46.0 10.5 L40.5 20.0 A15 15 0 0 0 33.0 18.0 Z\" fill=\"#E05A5A\" opacity=\"1\"/><path d=\"M46.0 10.5 A26 26 0 0 1 55.5 20.0 L46.0 25.5 A15 15 0 0 0 40.5 20.0 Z\" fill=\"#E0813F\" opacity=\"0.2\"/><path d=\"M55.5 20.0 A26 26 0 0 1 59.0 33.0 L48.0 33.0 A15 15 0 0 0 46.0 25.5 Z\" fill=\"#E0A93F\" opacity=\"0.2\"/><path d=\"M59.0 33.0 A26 26 0 0 1 55.5 46.0 L46.0 40.5 A15 15 0 0 0 48.0 33.0 Z\" fill=\"#D7C63F\" opacity=\"0.2\"/><path d=\"M55.5 46.0 A26 26 0 0 1 46.0 55.5 L40.5 46.0 A15 15 0 0 0 46.0 40.5 Z\" fill=\"#9DC44A\" opacity=\"0.2\"/><path d=\"M46.0 55.5 A26 26 0 0 1 33.0 59.0 L33.0 48.0 A15 15 0 0 0 40.5 46.0 Z\" fill=\"#5FB36A\" opacity=\"0.2\"/><path d=\"M33.0 59.0 A26 26 0 0 1 20.0 55.5 L25.5 46.0 A15 15 0 0 0 33.0 48.0 Z\" fill=\"#4CB0A6\" opacity=\"1\"/><path d=\"M20.0 55.5 A26 26 0 0 1 10.5 46.0 L20.0 40.5 A15 15 0 0 0 25.5 46.0 Z\" fill=\"#4C93C4\" opacity=\"0.2\"/><path d=\"M10.5 46.0 A26 26 0 0 1 7.0 33.0 L18.0 33.0 A15 15 0 0 0 20.0 40.5 Z\" fill=\"#5A6FC0\" opacity=\"0.2\"/><path d=\"M7.0 33.0 A26 26 0 0 1 10.5 20.0 L20.0 25.5 A15 15 0 0 0 18.0 33.0 Z\" fill=\"#7B5FC0\" opacity=\"0.2\"/><path d=\"M10.5 20.0 A26 26 0 0 1 20.0 10.5 L25.5 20.0 A15 15 0 0 0 20.0 25.5 Z\" fill=\"#A85FC0\" opacity=\"0.2\"/><path d=\"M20.0 10.5 A26 26 0 0 1 33.0 7.0 L33.0 18.0 A15 15 0 0 0 25.5 20.0 Z\" fill=\"#C45A93\" opacity=\"0.2\"/></svg></span>Opposites on the wheel (red↔green). Each makes the other look more vivid — maximum tension; <b>never use them in equal amounts</b>, always one large and one small.</p></details>\n      <details><summary>⑤ Saturation contrast</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"20\" width=\"40\" height=\"26\" rx=\"3\" fill=\"#9A8FB0\"/><rect x=\"60\" y=\"20\" width=\"40\" height=\"26\" rx=\"3\" fill=\"#8A2FC0\"/></svg></span>Vivid against muted. <b>A single vivid note in a greyed field is the most eye-catching thing there is</b> — the most elegant form of emphasis, far softer than complementaries.</p></details>\n      <details><summary>⑥ Contrast of extension (area)</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"20\" width=\"76\" height=\"26\" rx=\"3\" fill=\"#5A6FC0\"/><rect x=\"88\" y=\"24\" width=\"14\" height=\"18\" rx=\"2\" fill=\"#E0C63F\"/></svg></span>Contrast of size between color areas. Itten showed that <b>colors differ in visual force, so they need different areas</b>: yellow is bright and strong — a touch suffices; violet is dark and weak — it needs a large field to balance. This is the theory behind the 60-30-10 rule.</p></details>\n      <details><summary>⑦ Simultaneous contrast</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"18\" width=\"44\" height=\"30\" rx=\"3\" fill=\"#C0554E\"/><rect x=\"58\" y=\"18\" width=\"44\" height=\"30\" rx=\"3\" fill=\"#3D8E5A\"/><circle cx=\"30\" cy=\"33\" r=\"7\" fill=\"#9A9A9A\"/><circle cx=\"80\" cy=\"33\" r=\"7\" fill=\"#9A9A9A\"/></svg></span>An <b>optical illusion</b>: the same color looks different on different backgrounds (grey shifts green on red). The lesson — <b>color is always a relationship, never an absolute</b>; changing the background changes the subject&#39;s color.</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>More color schemes <span class=\"tag gold\">Advanced combos</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">Beyond mono / analogous / complementary / triadic, here are finer approaches.</p>\n      <details><summary>Split-complementary</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"22\" width=\"31\" height=\"22\" rx=\"3\" fill=\"#5A6FC0\"/><rect x=\"41\" y=\"22\" width=\"31\" height=\"22\" rx=\"3\" fill=\"#E0A93F\"/><rect x=\"74\" y=\"22\" width=\"31\" height=\"22\" rx=\"3\" fill=\"#E05A5A\"/></svg></span>Take one main color and pair it with the two colors <b>either side of its complement</b> (not the complement itself).<br>Upside: <b>you keep complementary tension without the harshness</b> — far easier to handle. The safest way to use contrast without looking gaudy.</p></details>\n      <details><summary>Tetradic (rectangle)</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#5A6FC0\"/><rect x=\"33\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#E0813F\"/><rect x=\"58\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#C45A93\"/><rect x=\"83\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#9DC44A\"/></svg></span><b>Two complementary pairs</b> on the wheel (a rectangle) — four colors. The richest and most opulent, but the hardest to balance: <b>pick one as dominant</b>, the rest support, and mind the warm/cool split.</p></details>\n      <details><summary>Square</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#E05A5A\"/><rect x=\"33\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#9DC44A\"/><rect x=\"58\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#4C93C4\"/><rect x=\"83\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#A85FC0\"/></svg></span>Four <b>evenly spaced</b> colors (a square). More balanced than the rectangle but harder to unify — good for vivid, festive, playful themes; again, mute three and feature one.</p></details>\n      <details><summary>Duotone</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"22\" width=\"44\" height=\"22\" rx=\"3\" fill=\"#2A2138\"/><rect x=\"54\" y=\"22\" width=\"44\" height=\"22\" rx=\"3\" fill=\"#B4A9DC\"/></svg></span>The whole image uses <b>only two colors</b> (usually one dark, one light), tinting even the shadows and highlights.<br>Effect: <b>extreme unity with a strong poster-like style</b> — a modern favorite, loved by dark and vintage looks.</p></details>\n      <details><summary>Earth tones</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#6E4A2A\"/><rect x=\"33\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#A9834E\"/><rect x=\"58\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#C7B08A\"/><rect x=\"83\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#8A7A4A\"/></svg></span>Brown, tan, khaki, olive, ochre, cream — low-saturation warm colors drawn from nature. <b>Naturally harmonious, warm, easy on the eye</b>, because they already coexist in nature. The universal base for vintage, wafū and autumn themes.</p></details>\n      <details><summary>Morandi colors</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#9E9AA6\"/><rect x=\"33\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#AFA6A0\"/><rect x=\"58\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#A6ADAA\"/><rect x=\"83\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#B6ACB4\"/></svg></span>The <b>sophisticated greys</b> beloved of painter Giorgio Morandi — every color has <b>grey mixed in</b>, desaturated until they nearly match.<br>Effect: soft, quiet, elegant, understated. <b>The secret of \"refined\" is desaturating everything</b> onto the same grey level.</p></details>\n      <details><summary>Pastel / macaron</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#F3C6D6\"/><rect x=\"33\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#C6E8D6\"/><rect x=\"58\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#F3E8B8\"/><rect x=\"83\" y=\"22\" width=\"23\" height=\"22\" rx=\"3\" fill=\"#D6C6E8\"/></svg></span>High-value, low-to-mid-saturation <b>sweet pale colors</b> (pink, mint, butter, lilac).<br>Effect: soft, dreamy, cute, youthful. The staple of ethereal and girlish styles; the trick is to <b>raise all values and lower all saturations</b> so they read as a family.</p></details>\n      <details><summary>Neon / fluorescent</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#2A2138\"/><rect x=\"8\" y=\"22\" width=\"28\" height=\"22\" rx=\"3\" fill=\"#39FF9E\"/><rect x=\"38\" y=\"22\" width=\"28\" height=\"22\" rx=\"3\" fill=\"#FF3D9A\"/><rect x=\"68\" y=\"22\" width=\"28\" height=\"22\" rx=\"3\" fill=\"#3DE0FF\"/></svg></span>Ultra-saturated bright colors on a <b>dark (especially black) background</b> for a glowing effect.<br>Effect: intense, edgy, cyber, futuristic. <b>It must sit on a dark base</b> to \"light up\"; keep the bright colors to two or three.</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>Advanced color ideas <span class=\"tag ok\">Add depth</span></h3>\n      <details><summary>Local, light &amp; reflected color</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"34\" cy=\"33\" r=\"15\" fill=\"#C8A0A0\"/><circle cx=\"34\" cy=\"33\" r=\"15\" fill=\"#E0A040\" opacity=\".28\"/><path d=\"M49 33 A15 15 0 0 1 64 20\" fill=\"none\"/><rect x=\"70\" y=\"20\" width=\"30\" height=\"26\" rx=\"4\" fill=\"#B03030\" opacity=\".25\"/></svg></span>An object&#39;s color is really three layered: <b>local color</b> (its own), <b>light color</b> (warm light yellows white cloth), and <b>reflected color</b> (a white skirt by a red wall picks up red).<br>Whether an image looks refined often comes down to letting reflected color tie the whole scene together.</p></details>\n      <details><summary>Warm and cool are relative</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"22\" width=\"44\" height=\"22\" rx=\"3\" fill=\"#C43A5A\"/><rect x=\"54\" y=\"22\" width=\"44\" height=\"22\" rx=\"3\" fill=\"#E0603A\"/></svg></span>A single hue has warm and cool versions — <b>a blue-leaning red (magenta) is cool, an orange-leaning red (vermilion) is warm</b>. Skilled palettes \"find cool within warm and warm within cool\" so even one hue can breathe.</p></details>\n      <details><summary>The importance of grey</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"22\" width=\"44\" height=\"22\" rx=\"3\" fill=\"#8E96A6\"/><rect x=\"54\" y=\"22\" width=\"44\" height=\"22\" rx=\"3\" fill=\"#A69890\"/></svg></span>There is <b>no pure grey, only tinted grey</b> — cool blue-greys, warm brown-greys. Large areas of grey set the whole mood: warm grey for calm, cool grey for chill. <b>Mastering grey is mastering color.</b></p></details>\n      <details><summary>Area rule for contrasting colors</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"20\" width=\"76\" height=\"26\" rx=\"3\" fill=\"#5A6FC0\"/><rect x=\"88\" y=\"24\" width=\"14\" height=\"18\" rx=\"2\" fill=\"#E0C63F\"/></svg></span>The more vivid or bright a color, the <b>smaller the area</b> it needs to balance. Itten&#39;s ideal ratio: yellow:orange:red:violet:blue:green ≈ 3:4:6:9:8:6 (weaker colors need more area). In practice: <b>vivid as accent, muted as base.</b></p></details>\n      <details><summary>Advancing and receding color</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#3A4A7A\"/><circle cx=\"55\" cy=\"33\" r=\"14\" fill=\"#E0813F\"/></svg></span><b>Warm, bright, saturated colors \"advance\"</b> (look closer, larger); <b>cool, dark, muted colors \"recede\"</b> (look farther, smaller). Give the subject an advancing color and the background a receding one — a color route to spatial depth.</p></details>\n      <details><summary>A unifying color cast</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"8\" y=\"14\" width=\"26\" height=\"16\" rx=\"3\" fill=\"#E05A5A\"/><rect x=\"42\" y=\"14\" width=\"26\" height=\"16\" rx=\"3\" fill=\"#4C93C4\"/><rect x=\"76\" y=\"14\" width=\"26\" height=\"16\" rx=\"3\" fill=\"#9DC44A\"/><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#E0A040\" opacity=\".3\"/></svg></span>Lay <b>one unified tone over the whole image</b> (all warm-yellow, or all cool-blue), like tinted glass. This is the core of film color grading — it instantly gathers scattered colors into a single mood.</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>Schemes on the colour wheel <span class=\"tag hot\">seven geometries</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">Every scheme below takes its colours from a geometric relationship on the wheel. Knowing them is what turns colour choice from instinct into reasoning. The analyser reports which one your image matches and how well.</p>\n      <details><summary>Monochromatic</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">One hue only, with depth built from lightness and saturation.</b><i><b>Photo</b>Blue-register portraiture running from pale sky to deep sea, telling the story through tone rather than hue conflict.</i><i><b>Paint</b>Picasso's Blue Period, the whole canvas steeped in one cold blue, concentrating grief and poverty into a single register.</i><i><b>Design</b>Minimal brand systems and Apple product pages often run one hue against black, white and grey. Clean and controlled.</i></p></details>\n      <details><summary>Analogous</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">Two to four neighbouring hues that share a pigment (yellow, yellow-green, green).</b><i><b>Photo</b>Autumn - red, orange, yellow. Rich and layered without conflict; the commonest harmony in nature.</i><i><b>Paint</b>Monet's haystacks, where a sunset sky of orange, pink and pale violet makes the whole air seem to glow.</i><i><b>Design</b>Wellness and organic brands pair green with yellow-green or blue-green for nature, health and calm.</i></p></details>\n      <details><summary>Complementary</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">Two hues directly opposite on the wheel (red/green, blue/orange, yellow/violet). Maximum contrast.</b><i><b>Photo</b>A gold sunset sky over a dark blue silhouette: warm against cool, tension at maximum.</i><i><b>Paint</b>Van Gogh's Cafe Terrace at Night slams yellow lamplight against deep blue sky, and each colour makes the other glow.</i><i><b>Design</b>The favourite of sportswear and sale posters. Control the area ratio or it turns garish; 70/30 is the safe formula.</i></p></details>\n      <details><summary>Split-complementary</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">One main hue plus the two colours either side of its complement. Softer than a straight complement and much harder to get wrong.</b><i><b>Photo</b>Orange-red and pink buildings under a blue sky: the contrast holds, but orange-red and pink are analogous to each other, so it reads more coherent.</i><i><b>Paint</b>Warm yellow skin against a background of blue-green and blue-violet: the warm/cool contrast stands, and the background still has variety.</i><i><b>Design</b>A blue primary button with orange and red used for secondary cues: it jumps without stabbing.</i></p></details>\n      <details><summary>Triadic</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">Three hues at the corners of an equilateral triangle (red, yellow, blue). Rich, balanced, lively.</b><i><b>Photo</b>A fairground with a red balloon, yellow ride and blue sky each holding a corner of the frame.</i><i><b>Paint</b>Mondrian's geometric abstraction, using the three primaries against black, white and grey - the purest visual balance there is.</i><i><b>Design</b>Children's and education brands use the primaries for energy, creativity and plain happiness.</i></p></details>\n      <details><summary>Tetradic (rectangle)</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">Four hues at the corners of a rectangle, which is really two complementary pairs. Very rich, and hard to control.</b><i><b>Photo</b>A city at night with blue, orange, red and green neon at once: dazzling, easily chaotic, right for urban clamour.</i><i><b>Paint</b>Gauguin's Tahiti paintings, where red earth, green leaf, yellow skin and violet shade weave a sense of abundance.</i><i><b>Design</b>Bold illustrated posters and streetwear. The key is letting one colour hold the area and using the other three as accents.</i></p></details>\n      <details><summary>Achromatic</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">Black, white and grey only, with hue removed entirely.</b><i><b>Photo</b>Black-and-white documentary strips out the distraction of colour and forces attention onto light, texture, expression and structure.</i><i><b>Paint</b>Chinese ink painting substitutes ink for colour: five shades of black, and a range of feeling wider than colour would give.</i><i><b>Design</b>Minimal posters and luxury fashion. Black, white and grey read as timeless, cool and absolutely modern.</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>Style palettes with swatches <span class=\"tag gold\">ready to use</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 6px\">Hex codes below can be pasted straight into design software, or used as a reference for grading and palette mixing. The report's style-palette row tells you which group your image sits closest to.</p>\n      <details><summary>Morandi (muted grey)</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">Every colour carries a layer of grey: low saturation, mid-to-high lightness, gentle and restrained.</b></p>\n        <div class=\"pal-sw\"><i style=\"background:#C2A4A3\"><b style=\"color:#1B1226\">#C2A4A3</b></i><i style=\"background:#A3B5A6\"><b style=\"color:#1B1226\">#A3B5A6</b></i><i style=\"background:#8D9CA9\"><b style=\"color:#1B1226\">#8D9CA9</b></i><i style=\"background:#C1B9B0\"><b style=\"color:#1B1226\">#C1B9B0</b></i><i style=\"background:#B0A1B4\"><b style=\"color:#1B1226\">#B0A1B4</b></i></div>\n        <p class=\"lens3\"><i><b>Photo</b>Drop saturation and lift the shadows into grey.</i><i><b>Paint</b>Morandi's own still lifes, every bottle unified under one grey veil.</i><i><b>Design</b>Nordic interiors, indie cafes, skincare brands.</i></p></details>\n      <details><summary>Macaron</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">High lightness, low-to-mid saturation: sweet, powdery, weightless.</b></p>\n        <div class=\"pal-sw\"><i style=\"background:#F2C4CE\"><b style=\"color:#1B1226\">#F2C4CE</b></i><i style=\"background:#C0E3D4\"><b style=\"color:#1B1226\">#C0E3D4</b></i><i style=\"background:#FDE7C4\"><b style=\"color:#1B1226\">#FDE7C4</b></i><i style=\"background:#D6C9E2\"><b style=\"color:#1B1226\">#D6C9E2</b></i><i style=\"background:#C2D9EA\"><b style=\"color:#1B1226\">#C2D9EA</b></i></div>\n        <p class=\"lens3\"><i><b>Photo</b>Overexpose a stop and pull the contrast down.</i><i><b>Paint</b>Rococo pastels, painting the lightness of aristocratic life.</i><i><b>Design</b>Patisseries, baby brands, spring packaging.</i></p></details>\n      <details><summary>Earth tones</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">Brown, tan, beige, khaki and olive, taken from soil, rock and wood. Warm and steady.</b></p>\n        <div class=\"pal-sw\"><i style=\"background:#B8A68B\"><b style=\"color:#1B1226\">#B8A68B</b></i><i style=\"background:#B27A5E\"><b style=\"color:#FFFFFF\">#B27A5E</b></i><i style=\"background:#7E8B68\"><b style=\"color:#FFFFFF\">#7E8B68</b></i><i style=\"background:#F5F0E6\"><b style=\"color:#1B1226\">#F5F0E6</b></i><i style=\"background:#5C4332\"><b style=\"color:#FFFFFF\">#5C4332</b></i></div>\n        <p class=\"lens3\"><i><b>Photo</b>Cafe, leather and wood still life, warm white balance.</i><i><b>Paint</b>The costume palette of Rembrandt's portraits: deep brown woven with warm gold.</i><i><b>Design</b>Outdoor brands and stationery, for reliability and plainness.</i></p></details>\n      <details><summary>Black, white and grey</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">Colour removed entirely; everything is built from lightness contrast.</b></p>\n        <div class=\"pal-sw\"><i style=\"background:#FFFFFF\"><b style=\"color:#1B1226\">#FFFFFF</b></i><i style=\"background:#E0E0E0\"><b style=\"color:#1B1226\">#E0E0E0</b></i><i style=\"background:#999999\"><b style=\"color:#1B1226\">#999999</b></i><i style=\"background:#3D3D3D\"><b style=\"color:#FFFFFF\">#3D3D3D</b></i><i style=\"background:#000000\"><b style=\"color:#FFFFFF\">#000000</b></i></div>\n        <p class=\"lens3\"><i><b>Photo</b>Moriyama-style high-contrast street work, nothing left but light.</i><i><b>Paint</b>Ink and charcoal, using grey to interrogate form itself.</i><i><b>Design</b>Apple, Muji, luxury fashion.</i></p></details>\n      <details><summary>Neon</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">Very high saturation and mid-high brightness, as if lit from within. Digital and streetwise.</b></p>\n        <div class=\"pal-sw\"><i style=\"background:#BF5FFF\"><b style=\"color:#1B1226\">#BF5FFF</b></i><i style=\"background:#39FF14\"><b style=\"color:#1B1226\">#39FF14</b></i><i style=\"background:#FF69B4\"><b style=\"color:#1B1226\">#FF69B4</b></i><i style=\"background:#FF8C00\"><b style=\"color:#1B1226\">#FF8C00</b></i><i style=\"background:#00E5FF\"><b style=\"color:#1B1226\">#00E5FF</b></i></div>\n        <p class=\"lens3\"><i><b>Photo</b>Neon signage at night, UV-lit portraiture.</i><i><b>Paint</b>Pop art and Haring's graffiti, using fluorescents for direct bodily impact.</i><i><b>Design</b>Festival posters, sportswear, cyberpunk UI.</i></p></details>\n      <details><summary>Faded retro</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">Low saturation, warm and yellowed, imitating the way old photographs and print fade with time.</b></p>\n        <div class=\"pal-sw\"><i style=\"background:#E8D8B8\"><b style=\"color:#1B1226\">#E8D8B8</b></i><i style=\"background:#C25A5A\"><b style=\"color:#FFFFFF\">#C25A5A</b></i><i style=\"background:#7A9A9E\"><b style=\"color:#1B1226\">#7A9A9E</b></i><i style=\"background:#A68A6B\"><b style=\"color:#1B1226\">#A68A6B</b></i><i style=\"background:#B5A898\"><b style=\"color:#1B1226\">#B5A898</b></i></div>\n        <p class=\"lens3\"><i><b>Photo</b>Film simulation, with yellow-green or cyan pushed into the shadows.</i><i><b>Paint</b>Old advertising art and hand-painted film posters, softened by age.</i><i><b>Design</b>Nostalgic menus and retro packaging.</i></p></details>\n      <details><summary>Cyberpunk</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">Cool blues and purples dominate; magenta and orange come in as highlight and accent. High contrast, high saturation.</b></p>\n        <div class=\"pal-sw\"><i style=\"background:#1A0B2E\"><b style=\"color:#FFFFFF\">#1A0B2E</b></i><i style=\"background:#00F0FF\"><b style=\"color:#1B1226\">#00F0FF</b></i><i style=\"background:#FF007F\"><b style=\"color:#FFFFFF\">#FF007F</b></i><i style=\"background:#0D1B2A\"><b style=\"color:#FFFFFF\">#0D1B2A</b></i><i style=\"background:#F5A623\"><b style=\"color:#1B1226\">#F5A623</b></i></div>\n        <p class=\"lens3\"><i><b>Photo</b>Rain-slick Hong Kong and Tokyo streets: teal shadow, magenta highlight.</i><i><b>Paint</b>Sci-fi illustration and future-city concept art.</i><i><b>Design</b>Game posters, esports brands, sci-fi title design.</i></p></details>\n      <details><summary>Memphis</summary>\n        <p class=\"lens3\"><b class=\"fp-lede\">Bright, saturated, even clashing colours with geometry and dots. It refuses minimalism and embraces decoration and play.</b></p>\n        <div class=\"pal-sw\"><i style=\"background:#FF6B6B\"><b style=\"color:#1B1226\">#FF6B6B</b></i><i style=\"background:#FFD93D\"><b style=\"color:#1B1226\">#FFD93D</b></i><i style=\"background:#6BCB77\"><b style=\"color:#1B1226\">#6BCB77</b></i><i style=\"background:#9B59B6\"><b style=\"color:#FFFFFF\">#9B59B6</b></i><i style=\"background:#2C3E50\"><b style=\"color:#FFFFFF\">#2C3E50</b></i></div>\n        <p class=\"lens3\"><i><b>Photo</b>Highly styled set photography with coloured seamless and geometric props.</i><i><b>Paint</b>Eighties postmodern painting returning to decoration.</i><i><b>Design</b>The Memphis Group's furniture and posters, still visible in UI illustration today.</i></p></details>\n    </div>\n", "ae-style": "\n    <div class=\"card\">\n      <h3>Style-recipe diagrams <span class=\"tag hot\">Light + color at a glance</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 10px\">The little face shows <b>light position and shadow</b>; the bars are the <b>suggested palette</b>.</p>\n      <div class=\"dgm-grid\">\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 92\"><rect width=\"120\" height=\"92\" rx=\"7\" fill=\"#F3EFF9\"/><circle cx=\"42\" cy=\"40\" r=\"20\" fill=\"#F7ECEC\"/><circle cx=\"42\" cy=\"40\" r=\"20\" fill=\"#EEDFE8\" opacity=\".5\"/><circle cx=\"42\" cy=\"40\" r=\"20\" fill=\"none\" stroke=\"#FFF3C4\" stroke-width=\"2.5\"/>\n<circle cx=\"42\" cy=\"8\" r=\"4\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1\"><line x1=\"35\" y1=\"8\" x2=\"38\" y2=\"8\"/><line x1=\"46\" y1=\"8\" x2=\"49\" y2=\"8\"/><line x1=\"42\" y1=\"1\" x2=\"42\" y2=\"4\"/></g><rect x=\"76\" y=\"14\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#FFFFFF\"/><rect x=\"76\" y=\"31\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#EAD9F0\"/><rect x=\"76\" y=\"48\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#CFE0F0\"/><rect x=\"76\" y=\"65\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#DCD2EC\"/></svg></div><figcaption>Ethereal: backlit soft light + light/low-sat, key is rim light &amp; haze</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 92\"><rect width=\"120\" height=\"92\" rx=\"7\" fill=\"#221C2E\"/><circle cx=\"42\" cy=\"40\" r=\"20\" fill=\"#E9DBDB\"/><path d=\"M42 20 A20 20 0 0 1 42 60 Z\" fill=\"#100B18\" opacity=\".72\"/>\n<circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1\"><line x1=\"7\" y1=\"14\" x2=\"10\" y2=\"14\"/><line x1=\"18\" y1=\"14\" x2=\"21\" y2=\"14\"/><line x1=\"14\" y1=\"7\" x2=\"14\" y2=\"10\"/></g><rect x=\"76\" y=\"14\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#141019\"/><rect x=\"76\" y=\"31\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#3A2140\"/><rect x=\"76\" y=\"48\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#7C1F1F\"/><rect x=\"76\" y=\"65\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#C9A94E\"/></svg></div><figcaption>Gothic: hard chiaroscuro + dark, one vivid accent (blood red/gold)</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 92\"><rect width=\"120\" height=\"92\" rx=\"7\" fill=\"#EDE7E0\"/><circle cx=\"42\" cy=\"40\" r=\"20\" fill=\"#F3E7DD\"/><path d=\"M42 20 A20 20 0 0 0 42 60 Z\" fill=\"#CFC2B4\" opacity=\".55\"/>\n<circle cx=\"78\" cy=\"40\" r=\"4\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1\"><line x1=\"71\" y1=\"40\" x2=\"74\" y2=\"40\"/><line x1=\"82\" y1=\"40\" x2=\"85\" y2=\"40\"/><line x1=\"78\" y1=\"33\" x2=\"78\" y2=\"36\"/></g><rect x=\"76\" y=\"14\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#F0EBE3\"/><rect x=\"76\" y=\"31\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#D8A7A0\"/><rect x=\"76\" y=\"48\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#C7B7D6\"/><rect x=\"76\" y=\"65\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#AFC0C4\"/></svg></div><figcaption>Wafū: soft side light + muted traditional colors, empty space matters</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 92\"><rect width=\"120\" height=\"92\" rx=\"7\" fill=\"#2A2119\"/><circle cx=\"42\" cy=\"40\" r=\"20\" fill=\"#E6D3BE\"/><path d=\"M42 20 A20 20 0 0 1 42 60 Z\" fill=\"#191008\" opacity=\".68\"/><polygon points=\"47,39 55,44 47,49\" fill=\"#E6D3BE\"/>\n<circle cx=\"18\" cy=\"14\" r=\"4\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1\"><line x1=\"11\" y1=\"14\" x2=\"14\" y2=\"14\"/><line x1=\"22\" y1=\"14\" x2=\"25\" y2=\"14\"/><line x1=\"18\" y1=\"7\" x2=\"18\" y2=\"10\"/></g><rect x=\"76\" y=\"14\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#241A10\"/><rect x=\"76\" y=\"31\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#4A3520\"/><rect x=\"76\" y=\"48\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#6E4A2A\"/><rect x=\"76\" y=\"65\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#B8892E\"/></svg></div><figcaption>Vintage: Rembrandt light + aged/desaturated, cream not white</figcaption></figure>\n      </div>\n    </div>\n    <div class=\"card\">\n      <h3>Texture diagrams <span class=\"tag ok\">How light hits a surface</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 10px\">Material = the shape of the highlight. Read the highlight to name the fabric.</p>\n      <div class=\"dgm-grid\"><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\"><rect width=\"120\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"10\" width=\"100\" height=\"52\" rx=\"8\" fill=\"#6E5FA8\"/><rect x=\"18\" y=\"30\" width=\"84\" height=\"7\" rx=\"3.5\" fill=\"#D9CBF2\" opacity=\".9\"/><text x=\"60\" y=\"80\" font-size=\"10\" fill=\"#2A2138\" text-anchor=\"middle\">Satin · long soft highlight</text></svg></div><figcaption>Satin</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\"><rect width=\"120\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"10\" width=\"100\" height=\"52\" rx=\"8\" fill=\"#3A2846\"/><rect x=\"10\" y=\"10\" width=\"100\" height=\"52\" rx=\"8\" fill=\"none\" stroke=\"#9B7DB8\" stroke-width=\"4\" opacity=\".6\"/><text x=\"60\" y=\"80\" font-size=\"10\" fill=\"#2A2138\" text-anchor=\"middle\">Velvet · glowing edges</text></svg></div><figcaption>Velvet</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\"><rect width=\"120\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"10\" width=\"100\" height=\"52\" rx=\"8\" fill=\"#8891A0\"/><polygon points=\"20,14 30,14 22,58 12,58\" fill=\"#FFFFFF\" opacity=\".95\"/><rect x=\"10\" y=\"40\" width=\"100\" height=\"22\" rx=\"6\" fill=\"#2E3440\" opacity=\".35\"/><text x=\"60\" y=\"80\" font-size=\"10\" fill=\"#2A2138\" text-anchor=\"middle\">Metal · sharp highlight</text></svg></div><figcaption>Metal</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\"><rect width=\"120\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"10\" y=\"10\" width=\"100\" height=\"52\" rx=\"8\" fill=\"#C9B79E\"/><rect x=\"10\" y=\"10\" width=\"100\" height=\"52\" rx=\"8\" fill=\"#000\" opacity=\".04\"/><text x=\"60\" y=\"80\" font-size=\"10\" fill=\"#2A2138\" text-anchor=\"middle\">Cotton/washi · matte</text></svg></div><figcaption>Cotton · washi</figcaption></figure></div>\n    </div>\n    <div class=\"card\">\n      <h3>Style recipe diagrams <span class=\"tag hot\">Light + color</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 10px\">Top = light position &amp; shading (yellow dot = light source); the bar below = suggested palette.</p>\n      <div class=\"dgm-grid\">\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 92\"><rect width=\"120\" height=\"92\" rx=\"7\" fill=\"#F3EFF9\"/>\n<circle cx=\"60\" cy=\"40\" r=\"30\" fill=\"#FFFFFF\" opacity=\".4\"/><circle cx=\"60\" cy=\"34\" r=\"18\" fill=\"#F8ECE6\"/><circle cx=\"60\" cy=\"34\" r=\"18\" fill=\"#fff\" opacity=\".25\"/><circle cx=\"60\" cy=\"34\" r=\"18\" fill=\"none\" stroke=\"#FFF6DE\" stroke-width=\"2.5\"/>\n<circle cx=\"60\" cy=\"10\" r=\"4.5\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1\" opacity=\".8\">\n<line x1=\"52\" y1=\"10\" x2=\"55\" y2=\"10\"/><line x1=\"65\" y1=\"10\" x2=\"68\" y2=\"10\"/>\n<line x1=\"60\" y1=\"2\" x2=\"60\" y2=\"5\"/><line x1=\"60\" y1=\"15\" x2=\"60\" y2=\"18\"/></g>\n<rect x=\"8.0\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#FFFFFF\"/><rect x=\"28.8\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#F0E9DE\"/><rect x=\"49.6\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#DDE7F2\"/><rect x=\"70.4\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#E6DEF2\"/><rect x=\"91.2\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#D8D2E6\"/></svg></div><figcaption>Ethereal: backlight + rim, high value/low saturation</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 92\"><rect width=\"120\" height=\"92\" rx=\"7\" fill=\"#1E1A28\"/>\n<circle cx=\"60\" cy=\"34\" r=\"18\" fill=\"#E8DDE0\"/><path d=\"M60 16 A18 18 0 0 1 60 52 Z\" fill=\"#00000066\"/><circle cx=\"60\" cy=\"34\" r=\"18\" fill=\"none\" stroke=\"#C9A24B\" stroke-width=\"2.5\"/>\n<circle cx=\"18\" cy=\"14\" r=\"4.5\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1\" opacity=\".8\">\n<line x1=\"10\" y1=\"14\" x2=\"13\" y2=\"14\"/><line x1=\"23\" y1=\"14\" x2=\"26\" y2=\"14\"/>\n<line x1=\"18\" y1=\"6\" x2=\"18\" y2=\"9\"/><line x1=\"18\" y1=\"19\" x2=\"18\" y2=\"22\"/></g>\n<rect x=\"8.0\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#15121C\"/><rect x=\"28.8\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#3A2740\"/><rect x=\"49.6\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#5A2233\"/><rect x=\"70.4\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#8A1F2E\"/><rect x=\"91.2\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#C9A24B\"/></svg></div><figcaption>Gothic: side light + deep dark, a note of blood-red/gold</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 92\"><rect width=\"120\" height=\"92\" rx=\"7\" fill=\"#EDE9F0\"/>\n<rect x=\"0\" y=\"0\" width=\"120\" height=\"92\" fill=\"#B9C0D8\" opacity=\".08\"/><circle cx=\"60\" cy=\"34\" r=\"18\" fill=\"#F3E9E2\"/><path d=\"M60 16 A18 18 0 0 1 60 52 Z\" fill=\"#0000001A\"/>\n<circle cx=\"16\" cy=\"30\" r=\"4.5\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1\" opacity=\".8\">\n<line x1=\"8\" y1=\"30\" x2=\"11\" y2=\"30\"/><line x1=\"21\" y1=\"30\" x2=\"24\" y2=\"30\"/>\n<line x1=\"16\" y1=\"22\" x2=\"16\" y2=\"25\"/><line x1=\"16\" y1=\"35\" x2=\"16\" y2=\"38\"/></g>\n<rect x=\"8.0\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#F5F2EC\"/><rect x=\"28.8\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#E8D8D0\"/><rect x=\"49.6\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#D8C8E0\"/><rect x=\"70.4\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#DCE2E0\"/><rect x=\"91.2\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#C9BCC6\"/></svg></div><figcaption>Wafū: soft side light, muted traditional colors, empty space</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 92\"><rect width=\"120\" height=\"92\" rx=\"7\" fill=\"#2A2018\"/>\n<circle cx=\"60\" cy=\"34\" r=\"18\" fill=\"#EAD9C4\"/><path d=\"M60 16 A18 18 0 0 1 60 52 Z\" fill=\"#00000055\"/><polygon points=\"66,32 74,37 66,42\" fill=\"#EAD9C4\"/>\n<circle cx=\"24\" cy=\"14\" r=\"4.5\" fill=\"#B8892E\"/><g stroke=\"#B8892E\" stroke-width=\"1\" opacity=\".8\">\n<line x1=\"16\" y1=\"14\" x2=\"19\" y2=\"14\"/><line x1=\"29\" y1=\"14\" x2=\"32\" y2=\"14\"/>\n<line x1=\"24\" y1=\"6\" x2=\"24\" y2=\"9\"/><line x1=\"24\" y1=\"19\" x2=\"24\" y2=\"22\"/></g>\n<rect x=\"8.0\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#6B4A2E\"/><rect x=\"28.8\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#8A5A32\"/><rect x=\"49.6\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#7A2E2E\"/><rect x=\"70.4\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#3A4A32\"/><rect x=\"91.2\" y=\"70\" width=\"18.8\" height=\"12\" rx=\"2\" fill=\"#C9A24B\"/></svg></div><figcaption>Vintage: Rembrandt light, aged desaturation, wine/amber</figcaption></figure>\n      </div>\n    </div>\n    <div class=\"card\">\n      <h3>Style recipes <span class=\"tag gold\">Follow the formula</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">Each style has its habitual light, palette and composition. Apply, then tweak to taste.</p>\n      <details><summary>Ethereal · airy</summary>\n        <p><b>Light｜</b>backlight or high-key soft light. Backlight makes tulle, lace and hair glow — the soul of the look; avoid hard light and heavy shadow.<br><b>Color｜</b>high value, <b>low saturation</b> — white, champagne, pale blue, lilac, silver. Monochrome or analogous, <b>keep contrast weak</b>.<br><b>Composition｜</b>lots of negative space, center or thirds, gaze into the distance; add floating elements (petals, bokeh, feathers).<br><b>Texture｜</b>tulle, chiffon, lace, pearl — light, sheer, floating materials.<br><b>Key｜</b>haze. <b>When unsure, go lighter, never heavier.</b></p></details>\n      <details><summary>Gothic · dark</summary>\n        <p><b>Light｜</b>hard light with <b>chiaroscuro</b> (a shaft in deep dark), or uplight for unease; always add a <b>rim light</b> or black clothing sinks into a black background.<br><b>Color｜</b>low value — black, ink, deep purple, dark crimson. <b>One saturated accent</b> (blood red, gold) and everything else pushed down.<br><b>Composition｜</b>symmetry (solemn) or inverted triangle (unease); framing devices (arches, iron bars, curtains) suit it perfectly.<br><b>Texture｜</b>velvet, leather, metal, black lace — heavy, hard, high-contrast sheen.<br><b>Key｜</b>contrast. <b>Let the darks go truly dark and place the highlight precisely.</b></p></details>\n      <details><summary>Japanese · wafū</summary>\n        <p><b>Light｜</b>soft side or raking light (as through a paper screen); cool backlight for moonlit themes.<br><b>Color｜</b><b>desaturated traditional colors</b> — shirotae white, pale red, wisteria, moon-white, ashen cherry. <b>Empty space (ma) is essential</b>; never fill the frame.<br><b>Composition｜</b>asymmetry and off-center placement (the Japanese taste for the incomplete); use straight dividing lines (door frames, screens, hanging drapes).<br><b>Texture｜</b>silk, rinzu, washi, lacquer — matte, fine, restrained sheen.<br><b>Key｜</b>empty space and season. One branch of sakura, one snowfall, one moon beats ten accessories.</p></details>\n      <details><summary>Vintage · old-master</summary>\n        <p><b>Light｜</b><b>Rembrandt light</b> (45° above), with rich dark areas.<br><b>Color｜</b>desaturate and add a touch of amber-brown to age it; deep green, wine red, golden brown.<br><b>Composition｜</b>center or triangle, upright and stable; heavy drapery or interior backdrops.<br><b>Texture｜</b>velvet, brocade, gold embroidery.<br><b>Key｜</b>gravity. <b>Swap pure white for cream and pure black for sepia-brown</b> and it turns classical instantly.</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>Texture &amp; material <span class=\"tag ok\">Touch you can see</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">Material = how light behaves on a surface. Get it right and the image feels tangible.</p>\n      <ul class=\"tips\">\n        <li><b>Sheen is the key</b>silk/satin = a <b>long soft highlight band</b>; velvet = <b>glowing edges, light-absorbing center</b>; metal = <b>sharp highlight + strong reflection</b>; cotton/washi = almost no highlight, <b>matte</b>.</li>\n        <li><b>Sheer fabrics need backlight</b>tulle, lace and chiffon only glow when <b>lit from behind</b>; in front light they&#39;re just white cloth.</li>\n        <li><b>Contrast your textures</b>the best looks pair <b>two opposing textures</b> — soft tulle with hard leather, matte with gloss, coarse weave with fine beading. All-one-texture reads flat.</li>\n        <li><b>Roughness sets distance</b>fine and smooth = refined, luxurious, cool; rough and fuzzy = warm, approachable, rustic.</li>\n        <li><b>Textures have weight</b>leather, metal and velvet look \"heavy\", tulle and lace \"light\" — put heavy low (hem, boots) and light high or outermost for stability.</li>\n        <li><b>Distribute detail density</b>you can&#39;t cover everything in lace + embroidery + sequins. <b>Pick one area as the focus</b> and keep the rest simple — that&#39;s density contrast.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Texture diagrams <span class=\"tag ok\">Highlight = touch</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 10px\">Materials differ in <b>how light falls on the surface</b>.</p>\n      <div class=\"dgm-grid\">\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 84\"><rect width=\"120\" height=\"84\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<rect x=\"14\" y=\"14\" width=\"92\" height=\"42\" rx=\"6\" fill=\"#6E5FA8\"/><rect x=\"20\" y=\"20\" width=\"80\" height=\"7\" rx=\"3\" fill=\"#fff\" opacity=\".55\"/><rect x=\"20\" y=\"40\" width=\"60\" height=\"4\" rx=\"2\" fill=\"#fff\" opacity=\".25\"/>\n<text x=\"60\" y=\"74\" font-size=\"10\" fill=\"#fff\" text-anchor=\"middle\">Satin</text></svg></div><figcaption>Satin: one long soft highlight</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 84\"><rect width=\"120\" height=\"84\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<rect x=\"14\" y=\"14\" width=\"92\" height=\"42\" rx=\"6\" fill=\"#3A2A48\"/><rect x=\"14\" y=\"14\" width=\"92\" height=\"42\" rx=\"6\" fill=\"none\" stroke=\"#B79AD0\" stroke-width=\"4\" opacity=\".5\"/>\n<text x=\"60\" y=\"74\" font-size=\"10\" fill=\"#fff\" text-anchor=\"middle\">Velvet</text></svg></div><figcaption>Velvet: bright edges, light-absorbing center</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 84\"><rect width=\"120\" height=\"84\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<rect x=\"14\" y=\"14\" width=\"92\" height=\"42\" rx=\"6\" fill=\"#8892A0\"/><polygon points=\"22,20 34,20 24,50 16,50\" fill=\"#fff\" opacity=\".85\"/><rect x=\"60\" y=\"18\" width=\"40\" height=\"38\" rx=\"4\" fill=\"#000\" opacity=\".2\"/>\n<text x=\"60\" y=\"74\" font-size=\"10\" fill=\"#fff\" text-anchor=\"middle\">Metal</text></svg></div><figcaption>Metal: sharp highlight + reflection</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 84\"><rect width=\"120\" height=\"84\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<rect x=\"14\" y=\"14\" width=\"92\" height=\"42\" rx=\"6\" fill=\"#C9BBA8\"/>\n<text x=\"60\" y=\"74\" font-size=\"10\" fill=\"#2A2138\" text-anchor=\"middle\">Matte</text></svg></div><figcaption>Cotton/washi: almost no highlight</figcaption></figure>\n      </div>\n      <p class=\"fine\" style=\"margin-top:8px\">Tip: pair <b>two opposing textures</b> (soft tulle + hard leather).</p>\n    </div>\n", "ae-type": "\n    <div class=\"card\">\n      <h3>Typography diagrams <span class=\"tag hot\">See it, get it</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 10px\">Each pair is <b>wrong (✗) vs right (✓)</b> — just follow the right-hand one.</p>\n\n      <p class=\"cond\" style=\"margin:14px 0 4px\"><b>① Three type personalities</b></p>\n      <div class=\"dgm-grid\"><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 80\"><rect width=\"120\" height=\"80\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<text x=\"60\" y=\"42\" font-size=\"34\" font-family=\"Georgia,'Times New Roman',serif\" fill=\"#2A2138\" text-anchor=\"middle\" font-weight=\"700\">Aa</text>\n<text x=\"60\" y=\"64\" font-size=\"10\" fill=\"#7B6BB5\" text-anchor=\"middle\">Serif</text></svg></div><figcaption>Serif = elegant, classical</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 80\"><rect width=\"120\" height=\"80\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<text x=\"60\" y=\"42\" font-size=\"34\" font-family=\"Arial,Helvetica,sans-serif\" fill=\"#2A2138\" text-anchor=\"middle\" font-weight=\"700\">Aa</text>\n<text x=\"60\" y=\"64\" font-size=\"10\" fill=\"#7B6BB5\" text-anchor=\"middle\">Sans-serif</text></svg></div><figcaption>Sans = modern, clean</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 80\"><rect width=\"120\" height=\"80\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<text x=\"60\" y=\"44\" font-size=\"34\" font-family=\"'Brush Script MT','Segoe Script',cursive\" fill=\"#2A2138\" text-anchor=\"middle\" font-style=\"italic\">Aa</text>\n<text x=\"60\" y=\"64\" font-size=\"10\" fill=\"#7B6BB5\" text-anchor=\"middle\">Script</text></svg></div><figcaption>Script = romantic, sparingly</figcaption></figure></div>\n\n      <p class=\"cond\" style=\"margin:16px 0 4px\"><b>② Pairing: contrast, don&#39;t match</b></p>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 240 90\"><rect width=\"240\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<text x=\"16\" y=\"38\" font-size=\"20\" font-family=\"Arial\" fill=\"#2A2138\" font-weight=\"700\">Title</text>\n<text x=\"16\" y=\"62\" font-size=\"15\" font-family=\"Helvetica\" fill=\"#2A2138\">body text</text>\n<text x=\"16\" y=\"82\" font-size=\"10\" fill=\"#C0554E\">Both sans, similar size → unclear</text></svg></div><figcaption><span style=\"color:#C0554E\">✗ Both sans, similar</span>　<span style=\"color:#3D8E8A\">✓ Serif + sans</span></figcaption></figure>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 240 90\"><rect width=\"240\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<text x=\"16\" y=\"40\" font-size=\"26\" font-family=\"Georgia,serif\" fill=\"#2A2138\" font-weight=\"700\">Title</text>\n<text x=\"16\" y=\"64\" font-size=\"13\" font-family=\"Arial,sans-serif\" fill=\"#2A2138\">body text</text>\n<text x=\"16\" y=\"83\" font-size=\"10\" fill=\"#3D8E8A\">Serif title + sans body → clear</text></svg></div><figcaption>Either very different, or one family in different weights</figcaption></figure>\n\n      <p class=\"cond\" style=\"margin:16px 0 4px\"><b>③ Build hierarchy (what to read first)</b></p>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 240 96\"><rect width=\"240\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<text x=\"14\" y=\"26\" font-size=\"13\" fill=\"#2A2138\">Spring arrivals</text>\n<text x=\"14\" y=\"46\" font-size=\"13\" fill=\"#2A2138\">20% off everything</text>\n<text x=\"14\" y=\"66\" font-size=\"13\" fill=\"#2A2138\">Now through month-end</text>\n<text x=\"14\" y=\"88\" font-size=\"10\" fill=\"#C0554E\">全部一樣大 → 不知道先看哪</text></svg></div><figcaption>All one size → no reading order</figcaption></figure>\n      <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 240 96\"><rect width=\"240\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/>\n<text x=\"14\" y=\"34\" font-size=\"21\" font-weight=\"700\" fill=\"#2A2138\">Spring</text>\n<text x=\"14\" y=\"56\" font-size=\"14\" fill=\"#8A5FC0\" font-weight=\"700\">20% OFF</text>\n<text x=\"14\" y=\"74\" font-size=\"11\" fill=\"#2A2138\" opacity=\".7\">Now through month-end</text>\n<text x=\"14\" y=\"90\" font-size=\"10\" fill=\"#3D8E8A\">大小粗細顏色拉開 → 一眼看出順序</text></svg></div><figcaption>Vary size, weight, color → order emerges</figcaption></figure>\n\n      <p class=\"cond\" style=\"margin:16px 0 4px\"><b>④ The four principles: CRAP</b></p>\n      <div class=\"dgm-grid\">\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"14\" y=\"40\" font-size=\"24\" font-weight=\"800\" fill=\"#2A2138\">Big</text><text x=\"14\" y=\"66\" font-size=\"11\" fill=\"#2A2138\" opacity=\".7\">small quiet text</text></svg></div><figcaption>Contrast: big is big, small is small</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"20\" cy=\"30\" r=\"6\" fill=\"#8A5FC0\"/><circle cx=\"42\" cy=\"30\" r=\"6\" fill=\"#8A5FC0\"/><circle cx=\"64\" cy=\"30\" r=\"6\" fill=\"#8A5FC0\"/><circle cx=\"86\" cy=\"30\" r=\"6\" fill=\"#8A5FC0\"/><rect x=\"15\" y=\"52\" width=\"12\" height=\"12\" rx=\"3\" fill=\"#7B6BB5\"/><rect x=\"37\" y=\"52\" width=\"12\" height=\"12\" rx=\"3\" fill=\"#7B6BB5\"/><rect x=\"59\" y=\"52\" width=\"12\" height=\"12\" rx=\"3\" fill=\"#7B6BB5\"/><rect x=\"81\" y=\"52\" width=\"12\" height=\"12\" rx=\"3\" fill=\"#7B6BB5\"/><text x=\"16\" y=\"86\" font-size=\"9\" fill=\"#3D8E8A\">repeat elements</text></svg></div><figcaption>Repetition: repeat the same elements</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"60\" y1=\"8\" x2=\"60\" y2=\"88\" stroke=\"#C0554E\" stroke-dasharray=\"3 3\" opacity=\".4\"/><text x=\"18\" y=\"30\" font-size=\"11\" fill=\"#2A2138\">off</text><text x=\"52\" y=\"50\" font-size=\"11\" fill=\"#2A2138\">messy</text><text x=\"30\" y=\"72\" font-size=\"11\" fill=\"#2A2138\">layout</text><text x=\"8\" y=\"90\" font-size=\"9\" fill=\"#C0554E\">✗ unaligned</text></svg></div><figcaption>Alignment: scattered ✗</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"18\" y1=\"14\" x2=\"18\" y2=\"76\" stroke=\"#3D8E8A\" stroke-dasharray=\"3 3\"/><text x=\"22\" y=\"30\" font-size=\"11\" fill=\"#2A2138\">flush</text><text x=\"22\" y=\"50\" font-size=\"11\" fill=\"#2A2138\">-</text><text x=\"22\" y=\"70\" font-size=\"11\" fill=\"#2A2138\">layout</text><text x=\"8\" y=\"92\" font-size=\"9\" fill=\"#3D8E8A\">✓ aligned</text></svg></div><figcaption>Alignment: flush-left ✓</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"14\" y=\"26\" font-size=\"10\" fill=\"#2A2138\">Head A</text><text x=\"14\" y=\"40\" font-size=\"9\" fill=\"#2A2138\" opacity=\".6\">body a</text><text x=\"14\" y=\"58\" font-size=\"10\" fill=\"#2A2138\">Head B</text><text x=\"14\" y=\"72\" font-size=\"9\" fill=\"#2A2138\" opacity=\".6\">body b</text><text x=\"8\" y=\"90\" font-size=\"8.5\" fill=\"#C0554E\">✗ equal gaps</text></svg></div><figcaption>Proximity: equal gaps ✗</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"14\" y=\"24\" font-size=\"10\" fill=\"#2A2138\">Head A</text><text x=\"14\" y=\"37\" font-size=\"9\" fill=\"#2A2138\" opacity=\".6\">body a</text><text x=\"14\" y=\"62\" font-size=\"10\" fill=\"#2A2138\">Head B</text><text x=\"14\" y=\"75\" font-size=\"9\" fill=\"#2A2138\" opacity=\".6\">body b</text><text x=\"8\" y=\"92\" font-size=\"8.5\" fill=\"#3D8E8A\">✓ grouped</text></svg></div><figcaption>Proximity: group related ✓</figcaption></figure>\n      </div>\n\n      <p class=\"cond\" style=\"margin:16px 0 4px\"><b>⑤ Line height &amp; length</b></p>\n      <div class=\"dgm-grid\"><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 160 96\"><rect width=\"160\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"14\" y=\"16\" width=\"120\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><rect x=\"14\" y=\"25\" width=\"120\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><rect x=\"14\" y=\"34\" width=\"120\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><rect x=\"14\" y=\"43\" width=\"120\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><text x=\"14\" y=\"88\" font-size=\"9\" fill=\"#C0554E\">✗ Too tight</text></svg></div><figcaption>Too tight</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 160 96\"><rect width=\"160\" height=\"96\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"14\" y=\"14\" width=\"120\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><rect x=\"14\" y=\"29\" width=\"120\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><rect x=\"14\" y=\"44\" width=\"120\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><rect x=\"14\" y=\"59\" width=\"120\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><text x=\"14\" y=\"90\" font-size=\"9\" fill=\"#3D8E8A\">✓ 1.5×</text></svg></div><figcaption>~1.5× line height</figcaption></figure></div>\n      <div class=\"dgm-grid\"><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 240 78\"><rect width=\"240\" height=\"78\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"14\" y=\"16\" width=\"214\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><rect x=\"14\" y=\"28\" width=\"214\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><rect x=\"14\" y=\"40\" width=\"214\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><text x=\"14\" y=\"66\" font-size=\"9\" fill=\"#C0554E\">✗ Line too long，找不到下一行</text></svg></div><figcaption>Line too long</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 240 78\"><rect width=\"240\" height=\"78\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"14\" y=\"14\" width=\"150\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><rect x=\"14\" y=\"25\" width=\"150\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><rect x=\"14\" y=\"36\" width=\"150\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><rect x=\"14\" y=\"47\" width=\"150\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".55\"/><text x=\"14\" y=\"70\" font-size=\"9\" fill=\"#3D8E8A\">✓ ~45–75 chars/line最好讀</text></svg></div><figcaption>~45–75 chars/line</figcaption></figure></div>\n\n      <p class=\"cond\" style=\"margin:16px 0 4px\"><b>⑥ Text over an image</b></p>\n      <div class=\"dgm-grid\"><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#8478A8\"/>\n<g fill=\"#B8A9D8\" opacity=\".85\"><circle cx=\"30\" cy=\"40\" r=\"16\"/><circle cx=\"66\" cy=\"30\" r=\"12\"/><circle cx=\"90\" cy=\"58\" r=\"18\"/><circle cx=\"46\" cy=\"70\" r=\"14\"/></g>\n<text x=\"60\" y=\"52\" font-size=\"13\" fill=\"#EDE7F5\" text-anchor=\"middle\" font-weight=\"700\">TITLE</text>\n<text x=\"60\" y=\"90\" font-size=\"8.5\" fill=\"#C0554E\" text-anchor=\"middle\">✗ over clutter</text></svg></div><figcaption>Over the busiest area</figcaption></figure><figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 96\"><rect width=\"120\" height=\"96\" rx=\"7\" fill=\"#8478A8\"/>\n<g fill=\"#B8A9D8\" opacity=\".85\"><circle cx=\"26\" cy=\"66\" r=\"15\"/><circle cx=\"58\" cy=\"76\" r=\"12\"/><circle cx=\"94\" cy=\"70\" r=\"16\"/></g>\n<rect x=\"0\" y=\"0\" width=\"120\" height=\"42\" fill=\"#2A2138\" opacity=\".28\"/>\n<text x=\"60\" y=\"28\" font-size=\"13\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">TITLE</text>\n<text x=\"60\" y=\"90\" font-size=\"8.5\" fill=\"#3D8E8A\" text-anchor=\"middle\">✓ empty + dark base</text></svg></div><figcaption>In empty space + dark base/shadow</figcaption></figure></div>\n    </div>\n    <div class=\"card\">\n      <h3>Visual flow diagrams <span class=\"tag ok\">Eye paths</span></h3>\n      <div class=\"dgm-grid\">\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"120\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\" opacity=\"0\"/><rect x=\"4\" y=\"4\" width=\"112\" height=\"82\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M18 20 L102 20 L18 70 L102 70\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><circle cx=\"18\" cy=\"20\" r=\"4\" fill=\"#3D8E8A\"/><circle cx=\"102\" cy=\"70\" r=\"4\" fill=\"#B8892E\"/></svg></div><figcaption>Z-pattern · image-led layouts</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"120\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\" opacity=\"0\"/><rect x=\"4\" y=\"4\" width=\"112\" height=\"82\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M18 20 L100 20 M18 20 L18 74 M18 44 L82 44\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"2.4\" stroke-linecap=\"round\"/><circle cx=\"18\" cy=\"20\" r=\"4\" fill=\"#3D8E8A\"/></svg></div><figcaption>F-pattern · text-heavy layouts</figcaption></figure>\n        <figure class=\"dgm\"><div class=\"dgm-box\"><svg viewBox=\"0 0 120 90\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"120\" height=\"90\" rx=\"7\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\" opacity=\"0\"/><rect x=\"4\" y=\"4\" width=\"112\" height=\"82\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"60\" y1=\"8\" x2=\"60\" y2=\"82\" stroke=\"#DDD6E8\"/><line x1=\"8\" y1=\"45\" x2=\"112\" y2=\"45\" stroke=\"#DDD6E8\"/>\n<text x=\"14\" y=\"26\" font-size=\"8\" fill=\"#3D8E8A\">primary</text><text x=\"72\" y=\"26\" font-size=\"8\" fill=\"#7B6BB5\">strong</text>\n<text x=\"14\" y=\"66\" font-size=\"8\" fill=\"#C05555\">weak</text><text x=\"72\" y=\"66\" font-size=\"8\" fill=\"#B8892E\">terminal</text>\n<path d=\"M22 32 L98 60\" stroke=\"#8A5FC0\" stroke-width=\"2\" stroke-dasharray=\"4 3\"/></svg></div><figcaption>Gutenberg: bottom-left is the blind spot</figcaption></figure>\n      </div>\n    </div>\n    <div class=\"card\">\n      <h3>The personality of type <span class=\"tag gold\">Choosing a font = choosing a tone</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">Type speaks on its own. The same sentence in a different face has a different character entirely.</p>\n      <details><summary>Serif</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"55\" y=\"46\" font-size=\"34\" font-family=\"Georgia,serif\" fill=\"#2A2138\" text-anchor=\"middle\" font-weight=\"700\">Aa</text></svg></span>Small finishing strokes (serifs) at the ends. Character: <b>classical, formal, literary, elegant</b>. Suits gothic, vintage, brand names, verse. The CJK equivalent is <b>Ming/Song</b> — thin horizontals, thick verticals, angular joints.</p></details>\n      <details><summary>Sans-serif</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"55\" y=\"46\" font-size=\"34\" font-family=\"Arial,sans-serif\" fill=\"#2A2138\" text-anchor=\"middle\" font-weight=\"700\">Aa</text></svg></span>No serifs, clean lines. Character: <b>modern, simple, legible, neutral</b>. Best for body copy, UI and minimal styles; the most readable at small sizes.</p></details>\n      <details><summary>Script / handwriting</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"55\" y=\"47\" font-size=\"34\" font-family=\"'Segoe Script',cursive\" fill=\"#2A2138\" text-anchor=\"middle\" font-style=\"italic\">Aa</text></svg></span>Imitates handwriting or calligraphy. Character: <b>romantic, personal, elegant or casual</b>. <b>Use sparingly</b> — a whole paragraph of script is painful to read. Best for signatures, titles, a single line.</p></details>\n      <details><summary>Display</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"55\" y=\"47\" font-size=\"32\" font-family=\"Georgia,serif\" fill=\"#2A2138\" text-anchor=\"middle\" font-weight=\"800\" letter-spacing=\"1\">A✦</text></svg></span>Special faces designed for headlines (blackletter, decorative). Huge personality but <b>low legibility</b> — <b>headlines only, never body text</b>.</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>Pairing rules <span class=\"tag ok\">Stay safe</span></h3>\n      <ul class=\"tips\">\n        <li><b>Two typefaces max</b>one for headings, one for body is enough. Three or more almost always turns messy.</li>\n        <li><b>Contrast, don&#39;t match</b>either make them <b>clearly different</b> (serif + sans is the classic pair) or use <b>one family</b> in different weights. Nearly-but-not-quite alike is the ugliest option.</li>\n        <li><b>Build hierarchy</b>title → subtitle → body, separated by <b>size, weight and color</b>. Unclear hierarchy = the reader doesn&#39;t know where to start.</li>\n        <li><b>Line height</b>about <b>1.4–1.8×</b> the type size reads best. Too tight feels cramped, too loose falls apart.</li>\n        <li><b>Letter spacing</b>tighten large headlines for punch; loosen small text and all-caps for clarity.</li>\n        <li><b>Line length</b>roughly <b>45–75 characters</b> per line is comfortable; longer and the eye loses the next line.</li>\n        <li><b>Keep contrast</b>light text on a light background is a disaster. Text always needs a clear value difference from its backdrop.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>The four design principles <span class=\"tag hot\">CRAP</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">From <i>The Non-Designer&#39;s Design Book</i> — the golden four of layout.</p>\n      <details><summary>Contrast</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"14\" y=\"38\" font-size=\"22\" font-weight=\"800\" fill=\"#2A2138\">Aa</text><text x=\"60\" y=\"40\" font-size=\"10\" fill=\"#2A2138\" opacity=\".6\">small</text></svg></span>If two things are different, make them <b>very different</b> — size, weight, color, typeface. <b>The danger is \"sort of similar\"</b>. Weak contrast is the most common beginner mistake.</p></details>\n      <details><summary>Repetition</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"20\" cy=\"24\" r=\"4\" fill=\"#8A5FC0\"/><circle cx=\"40\" cy=\"24\" r=\"4\" fill=\"#8A5FC0\"/><circle cx=\"60\" cy=\"24\" r=\"4\" fill=\"#8A5FC0\"/><circle cx=\"80\" cy=\"24\" r=\"4\" fill=\"#8A5FC0\"/><rect x=\"16\" y=\"40\" width=\"10\" height=\"10\" rx=\"2\" fill=\"#7B6BB5\"/><rect x=\"36\" y=\"40\" width=\"10\" height=\"10\" rx=\"2\" fill=\"#7B6BB5\"/><rect x=\"56\" y=\"40\" width=\"10\" height=\"10\" rx=\"2\" fill=\"#7B6BB5\"/><rect x=\"76\" y=\"40\" width=\"10\" height=\"10\" rx=\"2\" fill=\"#7B6BB5\"/></svg></span>Repeat a visual element (a color, rule, typeface, icon style) <b>throughout the piece</b> to build consistency and identity. This is how \"unity\" is actually executed.</p></details>\n      <details><summary>Alignment</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"18\" y1=\"12\" x2=\"18\" y2=\"54\" stroke=\"#3D8E8A\" stroke-dasharray=\"3 3\"/><rect x=\"22\" y=\"18\" width=\"40\" height=\"6\" rx=\"3\" fill=\"#7B6BB5\"/><rect x=\"22\" y=\"30\" width=\"60\" height=\"6\" rx=\"3\" fill=\"#7B6BB5\"/><rect x=\"22\" y=\"42\" width=\"30\" height=\"6\" rx=\"3\" fill=\"#7B6BB5\"/></svg></span>Every element should have a <b>visual connection to another element</b> — nothing placed arbitrarily. <b>Left or right alignment usually looks sharper than centered</b>; center suits formal, symmetrical work. If it looks messy, it&#39;s probably unaligned.</p></details>\n      <details><summary>Proximity</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"18\" y=\"14\" width=\"40\" height=\"5\" rx=\"2\" fill=\"#7B6BB5\"/><rect x=\"18\" y=\"22\" width=\"30\" height=\"5\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".5\"/><rect x=\"18\" y=\"42\" width=\"40\" height=\"5\" rx=\"2\" fill=\"#7B6BB5\"/><rect x=\"18\" y=\"50\" width=\"30\" height=\"5\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".5\"/></svg></span><b>Related things go together; unrelated things stay apart.</b> Items placed close read as one group. A heading should sit near the content it belongs to, not float in the middle.</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>Type over image <span class=\"tag ok\">Add text without ruining the picture</span></h3>\n      <ul class=\"tips\">\n        <li><b>Put text in a quiet zone</b>place it over empty, flat or blurred areas — never over the busiest detail.</li>\n        <li><b>Can&#39;t read it? Add a base</b>a translucent panel, vignette, gradient or a <b>subtle shadow</b> under the text lifts legibility.</li>\n        <li><b>Text is a compositional element</b>it carries visual weight and can <b>balance the frame</b> — figure heavy on one side, text on the other.</li>\n        <li><b>Align to the figure or scene</b>line the text edge up with the subject, horizon or architecture and it instantly looks tidy.</li>\n        <li><b>Pull color from the image</b><b>sample a color already present</b> (the purple of the skirt) and the whole thing harmonizes.</li>\n        <li><b>Fewer words</b>one short line beats a paragraph. The less text, the stronger the image.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Visual flow <span class=\"tag hot\">Where the eye goes</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">A good layout isn&#39;t \"neatly arranged\" — it <b>controls the order in which things are seen</b>.</p>\n      <details><summary>The Z-pattern</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M16 18 L94 18 L16 50 L94 50\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"2.4\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></svg></span>The eye travels top-left → top-right → bottom-left → bottom-right. <b>Best for image-led layouts with little text</b> (posters, ads, covers).<br>Use it: put the most important thing <b>top-left</b> (the entry) and the call to action or signature <b>bottom-right</b> (the exit).</p></details>\n      <details><summary>The F-pattern</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><path d=\"M18 16 L92 16 M18 16 L18 54 M18 34 L74 34\" fill=\"none\" stroke=\"#8A5FC0\" stroke-width=\"2.4\" stroke-linecap=\"round\"/></svg></span>On <b>text-heavy</b> layouts the eye traces an F: a sweep across the top, a shorter sweep mid-page, then down the left edge.<br>Use it: this is real reading behavior on web pages — front-load <b>the start of each paragraph and the left side</b>; the bottom-right is barely seen.</p></details>\n      <details><summary>The Gutenberg diagram</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><line x1=\"55\" y1=\"8\" x2=\"55\" y2=\"58\" stroke=\"#DDD6E8\"/><line x1=\"8\" y1=\"33\" x2=\"102\" y2=\"33\" stroke=\"#DDD6E8\"/><circle cx=\"24\" cy=\"20\" r=\"4\" fill=\"#3D8E8A\"/><circle cx=\"86\" cy=\"46\" r=\"4\" fill=\"#B8892E\"/><path d=\"M28 22 L82 44\" stroke=\"#8A5FC0\" stroke-width=\"1.6\" stroke-dasharray=\"3 3\"/></svg></span>Divides a page into four: <b>primary optical area (top-left) → strong fallow (top-right) → weak fallow (bottom-left) → terminal area (bottom-right)</b>. The eye drifts from top-left to bottom-right.<br>Use it: never put critical information in the <b>bottom-left</b> — the blind spot.</p></details>\n      <details><summary>Visual hierarchy</summary>\n        <p><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"16\" y=\"14\" width=\"60\" height=\"12\" rx=\"3\" fill=\"#2A2138\"/><rect x=\"16\" y=\"30\" width=\"44\" height=\"7\" rx=\"3\" fill=\"#8A5FC0\"/><rect x=\"16\" y=\"42\" width=\"70\" height=\"4\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".5\"/></svg></span>Use <b>size, weight, color, position and space</b> to set what is seen first, second, third.<br>Test it: <b>squint at your work</b> — whatever pops out first is your actual first level. If that isn&#39;t your intended focus, adjust.</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>Grids &amp; layout structure <span class=\"tag ok\">The skeleton of order</span></h3>\n      <ul class=\"tips\">\n        <li><b>Grid systems</b>divide the page into equal columns and rows and <b>align everything to the grid</b>. This is the line between professional and amateur — even free layouts need invisible guides.</li>\n        <li><b>Margins</b>leave generous and <b>consistent</b> margins. Crowding the edges is the classic beginner error; proper margins make content look expensive.</li>\n        <li><b>Grouping</b>use <b>proximity</b> to gather related information into blocks and separate the blocks. Readability comes from blocks, not lines.</li>\n        <li><b>One alignment</b>stick to <b>one primary alignment</b> throughout (usually left). Mixing left and centered is the main cause of visual noise.</li>\n        <li><b>Golden ratio / thirds</b>applies to layout too: place the subject or the dividing line at a third or the golden section rather than dead halfway.</li>\n        <li><b>Repetition builds a system</b>the same spacing, the same corner radius, the same heading style, over and over — that&#39;s where \"designed\" comes from.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Typography <span class=\"tag hot\">make the type look like it always belonged there</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 0\">Type is not only for reading, it is for looking at. Typeface, size contrast and spacing are visual form in their own right. The analyser can only measure the <b>position, size and contrast</b> of text blocks - typeface, tracking and line length need OCR, so nothing there is guessed at.</p>\n    </div>\n    <div class=\"card\">\n      <h3>1. Type basics <span class=\"tag gold\">the skeleton of a letterform</span></h3>\n      <details><summary>Serif vs sans serif</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"26\" y=\"44\" font-size=\"34\" font-family=\"Georgia,serif\" fill=\"#8A5FC0\">Aa</text><text x=\"66\" y=\"44\" font-size=\"34\" font-family=\"Helvetica,Arial,sans-serif\" fill=\"#7B6BB5\">Aa</text></svg></span><i><b>Point</b>The two camps.</i><i><b>Detail</b><b>Serif</b> has small finishing strokes and clear thick/thin contrast: classical, elegant, authoritative, trustworthy. Times New Roman, Garamond, Georgia, Source Han Serif.<br><b>Sans serif</b> has even strokes and geometric feel: modern, plain, rational, legible. Helvetica, Arial, Futura, Source Han Sans.</i><i><b>In practice</b>Photography: serif for weddings and vintage, sans for street and minimal. Design: serif for book and newspaper text and luxury, sans for web UI, decks and wayfinding.</i></p></details>\n      <details><summary>The voice of a typeface</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"10\" y=\"30\" font-size=\"15\" font-family=\"Georgia,serif\" fill=\"#8A5FC0\">Garamond</text><text x=\"10\" y=\"52\" font-size=\"15\" font-family=\"Helvetica,Arial\" fill=\"#7B6BB5\">Futura</text></svg></span><i><b>Point</b>Each one carries a period and a personality.</i><i><b>Detail</b><b>Humanist</b>: Renaissance serifs like Garamond, with a calligrapher's hand still in the strokes. <b>Authoritative</b>: modern serifs like Didot and Bodoni, extreme thick/thin - Vogue's logo comes from this line. <b>Neutral</b>: neo-grotesques like Helvetica, so free of personality it fits anywhere. <b>Geometric</b>: Futura, whose O is nearly a circle - the typeface on the Apollo 11 lunar plaque.</i><i><b>In practice</b>Script and handwriting faces carry a lot of feeling but must never carry body text; they destroy reading speed.</i></p></details>\n      <details><summary>Weight and width</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"10\" y=\"26\" font-size=\"13\" font-weight=\"300\" fill=\"#7B6BB5\">Light</text><text x=\"10\" y=\"42\" font-size=\"13\" font-weight=\"600\" fill=\"#7B6BB5\">Medium</text><text x=\"10\" y=\"58\" font-size=\"13\" font-weight=\"900\" fill=\"#8A5FC0\">Black</text></svg></span><i><b>Point</b>One family can build the whole hierarchy without a second typeface.</i><i><b>Detail</b><b>Weight</b>: Light / Regular / Medium / Bold / Black. Bold or Black for headings, Regular for body, Light for notes. <b>Width</b>: Condensed for headlines in narrow space, Extended for headlines that need presence.</i><i><b>In practice</b>One family, separated by weight, is the hardest setup to get wrong.</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>2. Setting text <span class=\"tag ok\">the rules that make type readable</span></h3>\n      <details><summary>Tracking</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g fill=\"#8A5FC0\"><rect x=\"12\" y=\"26\" width=\"7\" height=\"16\"/><rect x=\"27\" y=\"26\" width=\"7\" height=\"16\"/><rect x=\"42\" y=\"26\" width=\"7\" height=\"16\"/></g><g fill=\"#7B6BB5\" opacity=\".5\"><rect x=\"64\" y=\"26\" width=\"7\" height=\"16\"/><rect x=\"74\" y=\"26\" width=\"7\" height=\"16\"/><rect x=\"84\" y=\"26\" width=\"7\" height=\"16\"/></g></svg></span><i><b>Point</b>The overall space between characters.</i><i><b>Detail</b>Headlines are often tracked out for an airy, expensive feel; body text stays at default or slightly tight. All-caps English must be tracked out or the letters jam together.</i><i><b>In practice</b><span style=\"color:var(--rose)\">Addition: tracking (whole runs) and kerning (specific pairs like A and V) are different things and are constantly confused. Tracking adjusts a passage; kerning fixes individual pairs.</span></i></p></details>\n      <details><summary>Leading</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#8A5FC0\" stroke-width=\"2.4\"><line x1=\"14\" y1=\"16\" x2=\"50\" y2=\"16\"/><line x1=\"14\" y1=\"26\" x2=\"46\" y2=\"26\"/><line x1=\"14\" y1=\"36\" x2=\"50\" y2=\"36\"/></g><g stroke=\"#7B6BB5\" stroke-width=\"2.4\" opacity=\".6\"><line x1=\"62\" y1=\"14\" x2=\"98\" y2=\"14\"/><line x1=\"62\" y1=\"30\" x2=\"94\" y2=\"30\"/><line x1=\"62\" y1=\"46\" x2=\"98\" y2=\"46\"/></g></svg></span><i><b>Point</b>The vertical distance between lines.</i><i><b>Detail</b>Too tight and the lines fight; too loose and the paragraph falls apart. Leading is tied to line length - longer lines need more, or the eye returns to the line it just read.</i><i><b>In practice</b>Rule of thumb: body leading around 1.4-1.6x the type size; headlines can drop to 1.0-1.2x so several lines read as one tight block.</i></p></details>\n      <details><summary>Line length</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-width=\"2.6\"><line x1=\"10\" y1=\"20\" x2=\"100\" y2=\"20\"/><line x1=\"10\" y1=\"32\" x2=\"100\" y2=\"32\"/><line x1=\"10\" y1=\"44\" x2=\"72\" y2=\"44\"/></g></svg></span><i><b>Point</b>Characters per line.</i><i><b>Detail</b>The useful range is 45-75 characters in English, 25-35 characters in Chinese. Too short and the constant returns tire the eye; too long and the reader loses the start of the next line.</i><i><b>In practice</b>A photographic watermark can break this deliberately - three to five words on one line, treating the text as a graphic accent.</i></p></details>\n      <details><summary>Hierarchy</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"12\" y=\"12\" width=\"60\" height=\"9\" rx=\"2\" fill=\"#8A5FC0\"/><rect x=\"12\" y=\"28\" width=\"44\" height=\"6\" rx=\"2\" fill=\"#7B6BB5\" opacity=\".7\"/><g fill=\"#7B6BB5\" opacity=\".45\"><rect x=\"12\" y=\"40\" width=\"82\" height=\"3.5\" rx=\"1.5\"/><rect x=\"12\" y=\"48\" width=\"82\" height=\"3.5\" rx=\"1.5\"/></g></svg></span><i><b>Point</b>A piece needs at least three levels of type before it has any order.</i><i><b>Detail</b><b>Headline</b>: largest and heaviest, carrying the core message in three seconds. <b>Subhead</b>: supports and pulls the reader down. <b>Body</b>: smallest, optimised purely for comfort.</i><i><b>In practice</b>Hierarchy is built from contrast - size, weight, colour. When two levels are not different enough, the result is the uneasy feeling of almost-the-same.</i></p></details>\n      <details><summary>Alignment</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g fill=\"#8A5FC0\" opacity=\".55\"><rect x=\"10\" y=\"14\" width=\"40\" height=\"4\" rx=\"2\"/><rect x=\"10\" y=\"24\" width=\"32\" height=\"4\" rx=\"2\"/><rect x=\"10\" y=\"34\" width=\"38\" height=\"4\" rx=\"2\"/></g><g fill=\"#7B6BB5\" opacity=\".55\"><rect x=\"62\" y=\"14\" width=\"38\" height=\"4\" rx=\"2\"/><rect x=\"68\" y=\"24\" width=\"32\" height=\"4\" rx=\"2\"/><rect x=\"64\" y=\"34\" width=\"36\" height=\"4\" rx=\"2\"/></g></svg></span><i><b>Point</b>Four options, four characters.</i><i><b>Detail</b><b>Left</b>: the default, matching how the eye reads. <b>Right</b>: deliberate, used for corner watermarks and captions. <b>Centred</b>: formal and classical - wedding albums, poetry, invitations - but messy when line lengths vary a lot. <b>Justified</b>: flush on both sides, forming a tidy block.</i><i><b>In practice</b>In justified text set in a narrow column, the word spaces line up into vertical white channels running down the paragraph. Printers call them rivers.</i></p></details>\n      <details><summary>Line-breaking, orphans and widows</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g fill=\"#7B6BB5\" opacity=\".5\"><rect x=\"12\" y=\"14\" width=\"84\" height=\"4\" rx=\"2\"/><rect x=\"12\" y=\"24\" width=\"84\" height=\"4\" rx=\"2\"/><rect x=\"12\" y=\"34\" width=\"84\" height=\"4\" rx=\"2\"/></g><g fill=\"#fff\"><rect x=\"40\" y=\"14\" width=\"5\" height=\"28\" opacity=\".9\"/></g></svg></span><i><b>Point</b>The finishing details.</i><i><b>Detail</b><b>Line-breaking rules</b>: in Chinese setting, a line must not begin with a comma or full stop, nor end with an opening bracket or quote. <b>Orphan</b>: the first line of a paragraph stranded at the bottom of a column or page. <b>Widow</b>: the last line stranded at the top of the next one.</i><i><b>In practice</b><span style=\"color:var(--rose)\">These two definitions are frequently published the wrong way round; the version above is correct. Mnemonic: an orphan has no past (left behind at the bottom), a widow has no future (alone at the top).</span></i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>3. Type as image <span class=\"tag warn\">creative setting</span></h3>\n      <details><summary>Letting type break the frame</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"30\" y=\"18\" width=\"90\" height=\"30\" rx=\"4\" fill=\"#8A5FC0\"/><text x=\"42\" y=\"40\" font-size=\"19\" font-weight=\"800\" fill=\"#fff\">TYPE</text></svg></span><i><b>Point</b>Deliberately running text past the edge, or cropping half a headline letter.</i><i><b>Detail</b>On a poster or cover this kills dullness instantly and creates forward push.</i><i><b>In practice</b>Only if what remains is still readable. Crop past that and it is just a mistake.</i></p></details>\n      <details><summary>Text wrap</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><circle cx=\"40\" cy=\"34\" r=\"22\" fill=\"#8A5FC0\"/><g fill=\"#7B6BB5\" opacity=\".6\"><rect x=\"66\" y=\"14\" width=\"34\" height=\"3.5\" rx=\"1.5\"/><rect x=\"70\" y=\"24\" width=\"30\" height=\"3.5\" rx=\"1.5\"/><rect x=\"72\" y=\"34\" width=\"28\" height=\"3.5\" rx=\"1.5\"/><rect x=\"68\" y=\"44\" width=\"32\" height=\"3.5\" rx=\"1.5\"/></g></svg></span><i><b>Point</b>Letting body text flow around the subject's outline instead of a rectangle.</i><i><b>Detail</b>It lives or dies on the safe distance between text and image: too close and they invade each other, too far and the relationship breaks.</i><i><b>In practice</b>Usually 3-5mm of buffer.</i></p></details>\n      <details><summary>Clipping mask</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><defs><clipPath id=\"tclip\"><text x=\"8\" y=\"46\" font-size=\"34\" font-weight=\"900\">MASK</text></clipPath></defs><rect x=\"0\" y=\"0\" width=\"110\" height=\"66\" fill=\"#8A5FC0\" clip-path=\"url(#tclip)\"/></svg></span><i><b>Point</b>Filling heavy display type with an image, or knocking the type out to reveal what is underneath.</i><i><b>Detail</b>The type is a readable headline and a container for the image at the same time.</i><i><b>In practice</b>Standard on portfolio covers and posters. The face has to be heavy enough or the image inside cannot be read.</i></p></details>\n      <details><summary>Breaking the rules on purpose</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><text x=\"12\" y=\"40\" font-size=\"24\" font-weight=\"800\" fill=\"#8A5FC0\" opacity=\".55\">OVER</text><text x=\"30\" y=\"48\" font-size=\"24\" font-weight=\"800\" fill=\"#7B6BB5\" opacity=\".55\">LAP</text></svg></span><i><b>Point</b>Three devices.</i><i><b>Detail</b><b>Overlap</b>: two layers of type crossing, one translucent or outlined, creating depth. <b>Perspective type</b>: text mapped onto a facade, floor or wall, following the scene's vanishing lines. <b>Deconstruction</b>: words broken into individual letters scattered across the frame.</i><i><b>In practice</b>Deconstruction makes the viewer reassemble the word: engagement goes up, legibility goes down. For expression, not for information.</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>4. In practice <span class=\"tag hot\">how it lands in photography and design</span></h3>\n      <details><summary>The watermark</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"6\" y=\"6\" width=\"98\" height=\"54\" rx=\"4\" fill=\"#7B6BB5\" opacity=\".12\"/><text x=\"62\" y=\"54\" font-size=\"8\" fill=\"#7B6BB5\" opacity=\".8\">© studio</text></svg></span><i><b>Point</b>Not just theft prevention - part of a personal brand.</i><i><b>Detail</b><b>Position</b>: corners, with bottom-right the most natural end point for the eye. <b>Face</b>: rather too light than too heavy, rather too small than too large. <b>Opacity</b>: 60-80%, so it sits in the image rather than on it.</i><i><b>In practice</b>Match the register: serif for vintage photographs, sans for minimal work. The typeface's period has to agree with the image's.</i></p></details>\n      <details><summary>The grid</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><g stroke=\"#7B6BB5\" stroke-dasharray=\"2 2\" opacity=\".75\"><line x1=\"26\" y1=\"4\" x2=\"26\" y2=\"62\"/><line x1=\"55\" y1=\"4\" x2=\"55\" y2=\"62\"/><line x1=\"84\" y1=\"4\" x2=\"84\" y2=\"62\"/></g><rect x=\"30\" y=\"14\" width=\"50\" height=\"20\" rx=\"2\" fill=\"#8A5FC0\" opacity=\".55\"/></svg></span><i><b>Point</b>Type is not placed by feel; it sits on an invisible grid.</i><i><b>Detail</b><b>One column</b> for mobile. <b>Two</b> for magazines, allowing text and image to interleave. <b>Three</b> for posters and dense information, giving the most flexibility. <b>Modular</b>: equal squares that text and image drop into precisely - right for photo books and portfolios.</i><i><b>In practice</b>Every text block should align to that grid. This is the actual secret behind layouts that look professional.</i></p></details>\n      <details><summary>Colour and contrast</summary>\n        <p class=\"lens3\"><span class=\"dgm-inl\"><svg viewBox=\"0 0 110 66\" role=\"img\"><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#F6F4FB\" stroke=\"#DDD6E8\"/><rect x=\"1\" y=\"1\" width=\"108\" height=\"64\" rx=\"6\" fill=\"#2A2138\"/><rect x=\"14\" y=\"26\" width=\"82\" height=\"16\" rx=\"3\" fill=\"#000\" opacity=\".45\"/><text x=\"24\" y=\"38\" font-size=\"11\" fill=\"#fff\">readable</text></svg></span><i><b>Point</b>Whether type over an image can be read.</i><i><b>Detail</b><b>Black and white photographs</b>: pure white type in the shadows, pure black in the highlights, or mid-grey for a minimal register. <b>Colour photographs</b>: sample the dominant colour and set the type to its complement (orange type on a blue sky) for maximum separation.</i><i><b>In practice</b>The safe move: a translucent bar or a local blur behind the type. It holds legibility over any background. The analyser's text-contrast row checks exactly this against the WCAG thresholds.</i></p></details>\n    </div>\n    <div class=\"card\">\n      <h3>In summary <span class=\"tag gold\">an invisible art</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 0\">Typography is an invisible art. Done well, the reader sinks into the content without noticing it; done badly, every character screams amateur. Once you know the rules, remember one thing: the goal is to make the type look like it always belonged there.</p>\n    </div>\n", "ae-prac": "\n    <div class=\"card\">\n      <h3>Art-photo checklist <span class=\"tag hot\">Run this before you shoot</span></h3>\n      <ul class=\"tips\">\n        <li><b>① Pick the star</b>what must the viewer see? (the whole look? the skirt? the expression? a piece of jewelry?)</li>\n        <li><b>② Pick a composition</b>unsure → thirds; formal → center; dynamic → diagonal; two figures → triangle.</li>\n        <li><b>③ Pick the light</b>detail → front; dimension → side; atmosphere → backlight; classical → Rembrandt.</li>\n        <li><b>④ Tame the color</b>apply 60-30-10; if it&#39;s noisy, desaturate or add neutrals.</li>\n        <li><b>⑤ Build contrast</b>dark outfit on a light background (or vice versa) so the subject never sinks in.</li>\n        <li><b>⑥ Add depth</b>put something in the foreground (petals, curtains, bokeh).</li>\n        <li><b>⑦ Clean the edges</b>check for half-cropped clutter and crops landing on joints.</li>\n        <li><b>⑧ Subtract</b>remove one or two more elements at the end — it usually improves.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Common problems &amp; fixes <span class=\"tag warn\">Diagnosis</span></h3>\n      <table>\n        <thead><tr><th>Symptom</th><th>Likely cause</th><th>Fix</th></tr></thead>\n        <tbody>\n          <tr><td>Flat, no dimension</td><td>front light, no shadow</td><td>switch to side/backlight, deepen shadows</td></tr>\n          <tr><td>Can&#39;t tell who the star is</td><td>no emphasis or leading lines</td><td>desaturate the rest, add lines and empty space</td></tr>\n          <tr><td>Busy and chaotic</td><td>too many elements, no unity</td><td>unify the palette, subtract, add negative space</td></tr>\n          <tr><td>Dull and boring</td><td>no variety or contrast</td><td>add one accent color or highlight detail</td></tr>\n          <tr><td>Figure sinks into background</td><td>value/hue too similar</td><td>change background value or add rim light</td></tr>\n          <tr><td>Color looks cheap</td><td>equal complements, full saturation</td><td>apply 60-30-10, desaturate</td></tr>\n          <tr><td>Frame feels tilted</td><td>visual weight on one side</td><td>add a small bright element opposite</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <div class=\"card\">\n      <h3>Weak section, matching discipline <span class=\"tag hot\">learning path</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">Each section of the report corresponds to a different craft. The ones scoring low are the ones worth studying. <b>You do not need all of them</b> - pick the weakest one or two.</p>\n      <table>\n        <thead><tr><th>Weak section</th><th>Skill</th><th>Who to learn from</th></tr></thead>\n        <tbody>\n          <tr><td>Composition<br><span class=\"cond\">(patterns, thirds, leading lines)</span></td><td>Composition</td><td>Photography, <b>film storyboarding</b>, illustration</td></tr>\n          <tr><td>Colour<br><span class=\"cond\">(schemes, style palettes, commentary)</span></td><td>Colour</td><td><b>Colour theory</b>, graphic design, illustration</td></tr>\n          <tr><td>Principles of form<br><span class=\"cond\">(low simplicity or unity-and-variety)</span></td><td>Editing down</td><td>Graphic design, <b>advertising design</b></td></tr>\n          <tr><td>Focus concentration, subject weight</td><td>Visual hierarchy</td><td><b>Layout design</b>, UI design</td></tr>\n          <tr><td>Light, negative space</td><td>Light and space</td><td>Photography, painting, <b>cinematography</b></td></tr>\n          <tr><td>Type layer<br><span class=\"cond\">(contrast, margin)</span></td><td>Typography</td><td><b>Typography</b>, graphic design</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <div class=\"card\">\n      <h3>If you can only take two or three <span class=\"tag gold\">ordered for this kind of work</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 10px\">You make <b>composited graphics</b> - covers, showcase images, layouts with type - not single photographs. That difference changes the order:</p>\n      <ul class=\"tips\">\n        <li><b>1. Layout design</b> Composited work lives or dies here: what goes where, how much air, what outranks what. It is also the most systematic and the fastest to show results.</li>\n        <li><b>2. Colour theory</b> The second biggest lever, and genuinely learnable. The wheel's schemes are rules, not talent.</li>\n        <li><b>3. Typography</b> Unavoidable the moment there is text. Size contrast, leading, alignment - get these wrong and the whole piece reads amateur at a glance.</li>\n        <li><b>4. Storyboarding / photographic composition</b> How the eye is led. Placed fourth not because it is unimportant, but because without the first three underneath it, good composition has nothing to hold up.</li>\n        <li><b>5. Light</b> The slowest to learn and the hardest to shortcut, but it is what gives a picture weight.</li>\n      </ul>\n      <p class=\"cond\" style=\"margin:10px 0 0\">This differs from the usual \"learn composition first\" advice because <b>composition rules were mostly designed for a single camera frame</b>. Your work stacks several elements and adds type, so what decides it is layout and hierarchy, not framing.</p>\n    </div>\n", "sec-lore": "\n  <p class=\"fine\" style=\"margin:0 0 10px\">The full lore on brands &amp; naming. <b>Tap each basket to expand</b> — the origin of the name and the in-game EN screenshot proof sit together. Items marked \"speculation\" are community readings.</p>\n  <div class=\"seg\" id=\"loreSeg\" style=\"margin-bottom:14px\">\n    <button class=\"on\" data-v=\"lore-deux\">Deux</button>\n    <button data-v=\"lore-melem\">melem</button>\n    <button data-v=\"lore-bye\">By(e)</button>\n    <button data-v=\"lore-common\">Shared</button>\n  </div>\n  <div class=\"lort show\" id=\"lore-deux\">\n    <div class=\"card\">\n      <h3>deux <span class=\"tag gold\">Doll series</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\"><b>In a line:</b> the name is French for \"two\" — everything comes in pairs (twin visuals, gendered pairs, opposite dyes), and the item names even address \"you\".</p>\n      <ul class=\"tips\">\n        <li><b>Bases are French words</b>Chagrin (sorrow), Larme (tear), Âme (soul), Néant (void), Soleil (sun), Vérité (truth), Loin (far), Soirée, Rêve (dream), Perle (pearl).</li>\n        <li><b>Loves myth &amp; classics</b>Psyche = Greek \"soul\" (symbol: the butterfly), Giselle = the ballet&#39;s ghost dancer, Marguerite = daisy, Minette = kitten.</li>\n        <li><b>Archaic Japanese in wafū baskets</b>tamayura (an instant), utakata (foam), the \"fleeting sakura\", kawahirako (archaic \"butterfly\"); shirotae &amp; others are traditional color names.</li>\n        <li><b>C.D / F.D family thread</b>#10 Charlotte D.&#39;s Tears + Heritage Book → #11 F.D-Glass Key → #14 C.D-Papillon → #15 F.D-Papillon (likely one family&#39;s initials).</li>\n        <li><b>Why start at #4</b>the intl server follows the JP timeline; #1–#3 ended before global synced, so global starts at #4 (2023/02).</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>What the character names mean <span class=\"tag ok\">Etymology</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">Eyes and hairs are mostly named after real given names, each carrying a meaning (only confirmed etymologies listed; game-coined names like Saintière are omitted).</p>\n      <p class=\"cond\" style=\"margin:10px 0 4px\"><b>Eye characters</b></p>\n      <ul class=\"tips\">\n        <li><b>Francine</b>\"free one\" (feminine of Francis).</li>\n        <li><b>Anne</b>\"grace\" (Hebrew Hannah); <b>Antoine</b>= the French form of Anthony.</li>\n        <li><b>Louise / Louis</b>\"famous warrior\" (Germanic Ludwig).</li>\n        <li><b>Camille</b>\"attendant at a rite\" (Latin); <b>Samuel</b>\"God has heard\" (Hebrew).</li>\n        <li><b>Claris</b>\"bright, clear\" (Latin clarus); <b>Clement</b>\"merciful, mild\" (Latin clemens).</li>\n        <li><b>Marguerite</b>\"pearl / daisy\" (Greek margarites); <b>Maximilian</b>\"the greatest\" (Latin maximus).</li>\n        <li><b>Inez</b>\"pure, holy\" (Spanish form of Agnes); <b>Raul</b>\"wolf-counsel\" (Spanish form of Ralph).</li>\n        <li><b>Giselle</b>\"pledge\" (Germanic gisil); <b>Psyche</b>\"soul, breath\" (Greek).</li>\n      </ul>\n      <p class=\"cond\" style=\"margin:14px 0 4px\"><b>Hair characters</b></p>\n      <ul class=\"tips\">\n        <li><b>Sylvia / Sylvain</b>\"of the forest\" (Latin silva).</li>\n        <li><b>Bénédicte</b>\"blessed\" (Latin benedictus); <b>Felix</b>\"happy, lucky\" (Latin).</li>\n        <li><b>Gilles</b>= French Giles (Greek aigidion, young goat / shield); <b>Henri</b>\"home ruler\" (Germanic).</li>\n        <li><b>Sophie</b>\"wisdom\" (Greek); <b>Luca / Lucie / Lucian</b>\"light\" (Latin lux).</li>\n        <li><b>Elsa</b>= a short form of Elisabeth, \"pledged to God\"; <b>Ludovic</b>= a variant of Louis, \"famous warrior\".</li>\n        <li><b>Alma</b>\"soul\" (Latin / Spanish); <b>Ester</b>\"star\" (Persian Esther).</li>\n        <li><b>Yvette</b>\"yew\" (French, feminine of Yves); <b>Gervais</b>\"spear servant\" (Germanic).</li>\n      </ul>\n      <p class=\"cond\" style=\"margin:14px 0 4px\"><b>More name origins</b></p>\n      <ul class=\"tips\">\n        <li><b>Reveur</b>French \"dreamer\" (rêveur) — appears in #6, #8 and By(e) #1.</li>\n        <li><b>Briller</b>French \"to shine, to sparkle\" (#11).</li>\n        <li><b>Renée</b>\"reborn\" (feminine French of Latin renatus, #10).</li>\n        <li><b>Marie</b>the French form of Mary (Hebrew Miryam, #14); <b>Lune Carmin</b> = moon (Lune) + carmine red.</li>\n        <li><b>Emilia</b>\"rival, eager\" (the Roman gens Aemilia, By(e) #1).</li>\n        <li><b>Lulu</b>a pet form of Louise / Lucille (#4); <b>Simon</b> \"he has heard\" (Hebrew Shimon, #8).</li>\n        <li><b>Cyril</b>\"lordly, masterful\" (Greek Kyrillos, By(e) #3 Pellucid Cyril); <b>Eden</b> \"delight, paradise\" (Hebrew, By(e) #3).</li>\n        <li><b>Cherie</b>French \"darling\" (Reveur: Cherie); <b>Lumiadus / Lumineux</b> coined from Lumière (light).</li>\n      </ul>\n      <p class=\"fine\">A character often has a male/female or light/dark version (Sylvia/Sylvain, Hiina/Hihina), so the names pair up too.</p>\n    </div>\n    <div class=\"card\">\n      <h3>deux · basket by basket <span class=\"tag ok\">Name + EN proof</span></h3>\n      <details><summary>#4 Starlit ice blue · starlight into a moon-rainbow</summary>\n        <p><span class=\"lb\">Name</span>Base <b>Ciel</b> (sky); the key dress is \"Flower Key · Sky\"; Starlight (base) → of Lunar Rainbow (dye); half-moon hats and hazy moons run a moon-phase motif.</p>\n        <p><span class=\"lb en\">EN</span>Starlight (F Francine / M Saintière) → of Lunar Rainbow; the dress = <b>Fleur Serie</b>; moon accessories stay French (Lune Bonnet/Beret, Lunevoirée, Une Rose Eye Patch).</p></details>\n      <details><summary>#5 ex Sakura dusk · don&#39;t trust tomorrow&#39;s blossoms</summary>\n        <p><span class=\"lb\">Name</span>Base <b>dusk/night</b>; the \"fleeting sakura\" quotes a classic poem; the eight-petal love robe → foam love robe (utakata); \"you\" names throughout.</p>\n        <p><span class=\"lb en\">EN</span>Official typo <b>Love Pedal</b> (Petal → Pedal); base eyes = Night Sakura <b>Hinawa</b> (F) / <b>Kyoya</b> (M).</p></details>\n      <details><summary>#6 Ruby · the femme fatale &amp; the moon</summary>\n        <p><span class=\"lb\">Name</span>Base <b>Rouge</b>; the dress is Femme Fatale; the \"wax &amp; wane\" = the moon&#39;s phases; Camille of Darkness → Flash of Light / of Silence.</p>\n        <p><span class=\"lb en\">EN</span><b>Femme Fatale</b>, paired with the male <b>Omphale</b> (the queen who enslaved Heracles); wax &amp; wane = <b>Lunar Flux</b>; Rose Thoughts: Night → <b>White Day / New Year&#39;s Eve / Evening</b> (a holiday pun); card Le Rubis De Deux.</p></details>\n      <details><summary>#7 White rose · the pure light gone far</summary>\n        <p><span class=\"lb\">Name</span>Bases <b>Perle / Ciel / Claire</b>; Pure Lumière → Distant Lumière; \"generous\" is the French name Bénédicte (blessed).</p>\n        <p><span class=\"lb en\">EN</span>Ships nearly all-French (Pure Lumière, Souvenir Eternel, Cache Oeil de Dentelles); Distant Lumière; two word orders coexist; the tranquil eyes flip by gender (Anne Tranquille / Tranquility Antoine); spelling egg <b>Laprèmidi</b> (l&#39;après-midi fused).</p></details>\n      <details><summary>#8 Blue rose · kitten &amp; the Côte d&#39;Azur</summary>\n        <p><span class=\"lb\">Name</span><b>Minette</b> = kitten — hence the black cat ears/tail and Orion; R eyes Riviera + d&#39;Azur = the Côte d&#39;Azur; Chagrin = sorrow.</p>\n        <p><span class=\"lb en\">EN</span>d&#39;Azur romanized <b>Dajour</b>; Silent Bloom / Sleeping / Quiet Bloom; Azure Rondo → Navy Rondo; hairs Yvette / Yverre paired.</p></details>\n      <details><summary>#9 Blue-white cream · a daisy&#39;s dream turned to foam</summary>\n        <p><span class=\"lb\">Name</span>Base <b>Rêve</b> (dream), first dye slot \"Sommeil\" (sleep); Marguerite = daisy (a name that is a flower); Recollection → Silence / Bubbles.</p>\n        <p><span class=\"lb en\">EN</span>Recollection / Silence / Bubbles; spelling eggs <b>Nobel</b> (Noble) and <b>Pesch</b> (Pêche).</p></details>\n      <details><summary>#10 Fallen angel · the dyes act out the fall</summary>\n        <p><span class=\"lb\">Name</span>Base <b>Âme</b> (soul); book of chaos → book closed, Skyward Halo → Void Halo, Fallen Angel Wings → Puppet Wings; Alma (Latin \"soul\"): Vérité.</p>\n        <p><span class=\"lb en\">EN</span>âme; Inez / Raul → <b>Daybreak</b>; Livre: Désarroi → <b>Fermer</b>, Skyward → <b>Void Halo</b>, Fallen Angel → <b>Puppet Wings</b>; family line Heritage Book + Fallen Angel Tears.</p></details>\n      <details><summary>#11 Morning dew · the morning&#39;s tears</summary>\n        <p><span class=\"lb\">Name</span>Base <b>Larme</b> (tear) — dew as the morning&#39;s tears, the basket&#39;s thesis; Matin (morning), Fleurir (to bloom), Soleil (sun).</p>\n        <p><span class=\"lb en\">EN</span>Larme (Dearest Morning Mist); Matin (Dawn Reflet Matin); Fleurir → dye <b>Bourgeon</b> (bud); Soleil → Nature; hair Avenir; family line <b>F.D-Glass Key</b>.</p></details>\n      <details><summary>#12 ex Moon rabbits · the new-moon pact, two worlds</summary>\n        <p><span class=\"lb\">Name</span>Base <b>nightglow</b>; the pact = new moon &amp; full moon; kurotsurubami = acorn-dyed black; underworld ears vs eternal-realm ears; bonbori lantern.</p>\n        <p><span class=\"lb en\">EN</span>The pact = <b>New Moon Promise</b>; two rabbits = Twin Moon Night <b>Uno / Yato</b>; tokoyo = <b>Eternal</b> Rabbit Ears: White vs <b>Underworld</b> Rabbit Ears: Black.</p></details>\n      <details><summary>#13 Gothic time · the forgotten void</summary>\n        <p><span class=\"lb\">Name</span>Base <b>Chronos</b>; Néant = void, \"oblivious Néant\" = forgotten nothingness; the eternal arm bound → future / past; Loin (far) → old; the \"clock flower\" = passionflower.</p>\n        <p><span class=\"lb en\">EN</span>Chronos (Immortal Chronos card); Néant tiers Oblivious → <b>Time</b> / Melancholic; L&#39;âme Éternelle: Présent → <b>Avenir / Passé</b>; shows = <b>Matinée / Soirée</b>; Ash → Platinum Gear Pipe; Loin → Vieux.</p></details>\n      <details><summary>#14 Butterflies &amp; roses · the soul is a butterfly</summary>\n        <p><span class=\"lb\">Name</span>Base <b>Rosé</b>; Psyche = Greek \"soul\" (the butterfly) → Moonlit Sunken Psyche fills the basket with butterflies; Giselle the ghost dancer \"of the Void\"; Reason / Mind ribbons = two senses of \"psyche\".</p>\n        <p><span class=\"lb en\">EN</span><b>Moonlit Sunken Psyche</b> (Rosé/Blanc/Azure/Noir); Giselle of the Void → <b>The Heretical</b> (male Gervais mirrors it); <b>Reason / Mind Butterfly Ribbon</b>; Refret/Refretia → The Longing; darkness = Ténèbres; family line <b>C.D-Papillon</b>.</p></details>\n      <details><summary>#15 ex Moon-night butterflies · two spellings of one old word</summary>\n        <p><span class=\"lb\">Name</span>Base <b>shirotae</b> (Man&#39;yōshū word for pure white); \"Kawahirako / Kahahirako\" = <b>kawahirako</b>, the archaic word for butterfly, spelled two ways; tamayura = an instant; a catalog of traditional colors.</p>\n        <p><span class=\"lb en\">EN</span>Hina dolls pair by reading <b>Hiina</b> (F) / <b>Hihina</b> (M); hairs Chitose / Hinako; dress Moon Butterfly <b>Trance</b>: White → Dusk/Silver/White Night; family closes with <b>F.D-Papillon: White</b> (all four cards done).</p></details>\n      <details><summary>#16 Doll memories · a rabbit and a keepsake box in grey-white lace</summary>\n        <p><span class=\"lb\">Name</span>Original-color characters <b>Solène</b> / <b>Altel</b>; Trésor = French \"treasure\" (Sentimental Trésor); Clarté (light) + Douce (soft, sweet) + Coton (cotton) stack into one garment name; Souvenir (memory/keepsake) ties together with Douces Oreilles (soft ears), Lapin (rabbit), Chouchou (darling/favorite) and Lapinette (little doe rabbit) to build the basket's rabbit-doll theme; Voilage (sheer curtain) and Blanche (white, feminine form) keep the light/atmosphere thread going.</p>\n        <p><span class=\"lb en\">EN</span>The R eyes read <b>Radiant</b> on the female side vs <b>Radian</b> on the male side (missing a \"t\" — possibly an official typo, to be re-checked); the male headpiece <b>Laureate Halo</b> echoes the male hair <b>Aurelius</b> (Latin for \"golden\", a Roman-style name) — the female line runs French given names (Solène / Éliane) while the male line adds a touch of Roman classicism into the grey-white palette; <b>Silve</b> appears in Deux for the first time (likely a coined shorthand for Argent/silver), and along with Radiant/Radian and the art pieces Sentimental Lapin Chouchou and Lapinette Stand, none of it currently connects to the existing C.D/F.D family line or the moon-phase thread.</p></details>\n    </div>\n  </div>\n  <div class=\"lort\" id=\"lore-melem\">\n    <div class=\"card\">\n      <h3>melem <span class=\"tag gold\">Mirror series</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\"><b>In a line:</b> the name is a palindrome (m-e-l-e-m) — mirror-symmetric in itself; the logo is a sheep leading a crow, walking one dark-fable arc.</p>\n      <ul class=\"tips\">\n        <li><b>The dark fable</b>#1 mirror → #2 birdcage &amp; crows → #3 lost sheep → #4 Snow White&#39;s poison apple.</li>\n        <li><b>Suffix = what the mirror made it</b>items grow a suffix in the mirror room; variants are <b>three stages of decay</b> (whole → eroded → shattered), not colors.</li>\n        <li><b>\"You in the Mirror\" 001→004</b>numbered from #1 through #4 — it walks all four baskets; hand items always split L/R.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>melem · basket by basket <span class=\"tag ok\">Name + EN proof</span></h3>\n      <details><summary>#1 Mirror · a soul lost in the glass</summary>\n        <p><span class=\"lb\">Name</span><b>Miloire</b> ≈ a coinage of miroir (speculation); Psyche = a soul lost in the mirror; Simulacrum; Shadowgaze (an eyeshadow pun).</p>\n        <p><span class=\"lb en\">EN</span>Every suffix is <b>: Mirror</b>; deeper lexicon Lingering Dreams / Illusion / Dawn / Opposite / Fragment / <b>Zero</b>; <b>You in the Mirror001</b> starts the count; gloves L/R; the Pittoresque \"behind the mirror\" card.</p></details>\n      <details><summary>#2 Crow · the mirror turns things into concepts</summary>\n        <p><span class=\"lb\">Name</span>Crow feather → reason, halo → gospel, birdcage girl → premonition / delusion; Beckoning L/R, Lurking Girl/Boy.</p>\n        <p><span class=\"lb en\">EN</span>Anthem eyes Another Sky&#39;s → Secret / Everdark; reason = <b>Logos</b>, gospel = <b>Faith</b>; official typo <b>The Gaurdian</b>; You in the Mirror002; Peering Through Darkness → <b>the Abyss</b>.</p></details>\n      <details><summary>#3 Lost sheep · white guides, black frees</summary>\n        <p><span class=\"lb\">Name</span>White-to-black flip: guidance toward white fiction → liberation toward black; the eclipse sheep = a white sheep devoured black; the \"mirror flower\" idiom.</p>\n        <p><span class=\"lb en\">EN</span>Innocent Lost Sheep → <b>Black</b> Shadow/Eternity; White Fiction Leader → <b>Black Fiction Release</b>; <b>Eclipse Sheep</b>; the serial becomes Mirror<b> 003</b> (with a space); closer = <b>Distorted Mirror, No Return.</b> (full stop kept).</p></details>\n      <details><summary>#4 Poison apple · the apple&#39;s three-part fall</summary>\n        <p><span class=\"lb\">Name</span>Eyes in three stages: allure → erosion → jealousy; black/silver → red; Room of Inquiry = where the queen asks the mirror; the irreversible red fruit.</p>\n        <p><span class=\"lb en\">EN</span>Trilogy = Poison Apple <b>Allure → Erosion → Jealousy</b>; <b>Dark → Red → Phantasm</b> Mirror Sorcerer, Argent → Crimson Veil; princess dress Crimson → <b>Fusion</b>; <b>Mirror, Mirror on the Wall</b> verbatim; Irreversible Red Fruit; You in the Mirror 004.</p></details>\n    </div>\n  </div>\n  <div class=\"lort\" id=\"lore-bye\">\n    <div class=\"card\">\n      <h3>by(e) <span class=\"tag gold\">Perfumed florals</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\"><b>In a line:</b> the name puns on \"by ○○\" (a perfume convention) while the bracketed e reads \"bye\" — matching three baskets of fading beauty.</p>\n      <ul class=\"tips\">\n        <li><b>Each basket is a bottled perfume</b>bases wear SCENT FOR YOU; the three lines are its accords; the <b>only brand with makeup slots</b>.</li>\n        <li><b>Subtitles are all about impermanence</b>the anemone&#39;s \"brief love\", a red bloom in colorless NY, an \"eternal\" garden of soap bubbles — the name itself is an oxymoron.</li>\n        <li><b>Lines get recycled and promoted</b>Noir Eden rose from a side line in #1 to the lead in #3; line names are all accords (Floral Eve, Citrus Mellow, Elegant Aqua, Fruity Fairy…).</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>by(e) · basket by basket <span class=\"tag ok\">Name + EN proof</span></h3>\n      <details><summary>#1 Anemone Bouquet · brief love</summary>\n        <p><span class=\"lb\">Name</span>The Aphrodite Bouquet allusion: anemones bloomed from Adonis&#39;s blood and the goddess&#39;s tears, meaning \"brief love\"; the \"faded\" line connects to Noir Eden.</p>\n        <p><span class=\"lb en\">EN</span>\"Fade\" is the basket&#39;s verb = Faded Romance/Mauve/Eden/Mellow; the sentence-name <b>Someday it will Fade</b>; accessories all speak perfume (Airy Bangs/Tail, Aroma Glasses, Shiny Aroma).</p></details>\n      <details><summary>#2 Rose in the Rain · a rainy lost-and-found</summary>\n        <p><span class=\"lb\">Name</span>The \"colorless rainy NY\" names the colorless city = New York; a lost-and-found of roses, one per line; \"Wearing Cologne: Spicy / Sweet\" = accords as color names.</p>\n        <p><span class=\"lb en\">EN</span><b>Lost in the Rain</b>: Red/Blue/Pink/Sepia Rose; <b>Wearing Cologne: Spicy / Sweet</b>; Colorless &amp; Rainy NY; lyric card ROSY DESIRE LULLABY.</p></details>\n      <details><summary>#3 Heavenly Garden · eternity told in soap bubbles</summary>\n        <p><span class=\"lb\">Name</span>Aether (the classical \"heavenly substance\") holds up Heavenly Garden&#39;s \"heavenly\"; the oxymoron runs to the end — an eternal garden of bursting soap bubbles; Noir Eden promoted to the lead.</p>\n        <p><span class=\"lb en\">EN</span>Aether = <b>Ether</b> (Cerulescent/Nocturnal/Fairy); soap = <b>Sabon</b> (Ever Serene: Sabon, Eternal Sabon); Flower Thoughts - Noir Eden; the perfume term <b>Sillage</b> (scent trail).</p></details>\n    </div>\n  </div>\n  <div class=\"lort\" id=\"lore-common\">\n  <div class=\"seg\" id=\"loreCommonSeg\" style=\"margin-bottom:14px\">\n    <button class=\"on\" data-c=\"lc-name\">Naming</button>\n    <button data-c=\"lc-allusion\">Allusions</button>\n    <button data-c=\"lc-story\">Stories</button>\n  </div>\n  <div class=\"lct show\" id=\"lc-name\">\n    <div class=\"card\">\n      <h3>Three language layers in naming <span class=\"tag ok\">Layering</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 10px\">The language used tells you almost immediately what kind of basket it is:</p>\n      <ul class=\"tips\">\n        <li><b>Item names → French</b>Lumière, Souvenir, Papillon, Dentelles… (Deux&#39;s body).</li>\n        <li><b>Character names → Latin / Greek / Germanic</b>Psyche, Alma, Bénédicte, Marguerite…</li>\n        <li><b>Wafū extras → archaic Japanese</b>kawahirako, tamayura, shirotae, utakata… (#5/#12/#15).</li>\n        <li><b>melem → English philosophy</b>Logos, Simulacrum; <b>By(e) → English accords</b>Floral Eve, Citrus Mellow.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>French mini-glossary <span class=\"tag ok\">Deux staples</span></h3>\n      <table>\n        <thead><tr><th>Word</th><th>Meaning</th><th>Word</th><th>Meaning</th></tr></thead>\n        <tbody>\n          <tr><td>Deux</td><td>two</td><td>Lumière</td><td>light</td></tr>\n          <tr><td>Âme</td><td>soul</td><td>Larme</td><td>tear</td></tr>\n          <tr><td>Rêve</td><td>dream</td><td>Néant</td><td>void</td></tr>\n          <tr><td>Vérité</td><td>truth</td><td>Soleil</td><td>sun</td></tr>\n          <tr><td>Ciel</td><td>sky</td><td>Perle</td><td>pearl</td></tr>\n          <tr><td>Chagrin</td><td>sorrow</td><td>Loin</td><td>far</td></tr>\n          <tr><td>Avenir</td><td>future</td><td>Passé</td><td>past</td></tr>\n          <tr><td>Présent</td><td>present</td><td>Vieux</td><td>old</td></tr>\n          <tr><td>Matin</td><td>morning</td><td>Soirée</td><td>evening</td></tr>\n          <tr><td>Rouge</td><td>red</td><td>Noir</td><td>black</td></tr>\n          <tr><td>Argent</td><td>silver</td><td>Ombre</td><td>shadow</td></tr>\n          <tr><td>Lueur</td><td>glimmer</td><td>Ténèbres</td><td>darkness</td></tr>\n          <tr><td>Papillon</td><td>butterfly</td><td>Fleurir</td><td>to bloom</td></tr>\n          <tr><td>Bourgeon</td><td>bud</td><td>Fleur</td><td>flower</td></tr>\n          <tr><td>Dentelles</td><td>lace</td><td>Cache</td><td>to hide</td></tr>\n          <tr><td>Rideau</td><td>curtain</td><td>Marionnettes</td><td>puppets</td></tr>\n          <tr><td>Lune</td><td>moon</td><td>Étoile</td><td>star</td></tr>\n          <tr><td>Grâce</td><td>grace</td><td>Bénédicte</td><td>blessed</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <div class=\"card\">\n      <h3>Japanese archaic &amp; cultural terms <span class=\"tag ok\">wafū baskets</span></h3>\n      <table>\n        <thead><tr><th>Term</th><th>Reading</th><th>Meaning</th></tr></thead>\n        <tbody>\n          <tr><td>玉響</td><td>tamayura</td><td>a fleeting instant</td></tr>\n          <tr><td>うたかた</td><td>utakata</td><td>foam on water; the ephemeral</td></tr>\n          <tr><td>徒櫻</td><td>adazakura</td><td>quick-falling sakura; \"don&#39;t trust tomorrow\"</td></tr>\n          <tr><td>かはひらこ</td><td>kawahirako</td><td>the archaic word for \"butterfly\"</td></tr>\n          <tr><td>常世</td><td>tokoyo</td><td>the eternal land of myth</td></tr>\n          <tr><td>雪洞</td><td>bonbori</td><td>a paper-shaded lamp</td></tr>\n          <tr><td>朔望</td><td>sakubō</td><td>new moon (朔) &amp; full moon (望)</td></tr>\n          <tr><td>宵</td><td>yoi</td><td>early night, dusk</td></tr>\n        </tbody>\n      </table>\n      <p class=\"fine\">Note: <b>shirotae</b> is a <i>makura-kotoba</i> in the Man&#39;yōshū — a fixed epithet placed before \"robe, sleeve, snow\", the classical set phrase for pure white.</p>\n    </div>\n    <div class=\"card\">\n      <h3>EN translation strategies <span class=\"tag ok\">Tell at a glance</span></h3>\n      <ul class=\"tips\">\n        <li><b>Deux</b>keeps its French (Pure Lumière, Souvenir Eternel…), occasionally mixing word order.</li>\n        <li><b>melem</b>re-translates into philosophy words — reason → Logos, gospel → Faith.</li>\n        <li><b>By(e)</b>is native English, almost nothing to translate (SCENT FOR YOU, Floral Eve).</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Official typo collection <span class=\"tag hot\">Photographed in-game</span></h3>\n      <table>\n        <thead><tr><th>Typo</th><th>Correct</th><th>Where</th></tr></thead>\n        <tbody>\n          <tr><td>The <b>Gaurdian</b></td><td>Guardian</td><td>melem #2 (mirror version too)</td></tr>\n          <tr><td>Love <b>Pedal</b></td><td>Petal</td><td>Deux #5 R eyes</td></tr>\n          <tr><td><b>Nobel</b></td><td>Noble</td><td>Deux #9</td></tr>\n          <tr><td><b>Pesch</b></td><td>Pêche</td><td>Deux #9</td></tr>\n          <tr><td><b>Laprèmidi</b></td><td>l&#39;après-midi</td><td>Deux #7 (male drops the accent)</td></tr>\n          <tr><td><b>Dajour</b></td><td>d&#39;Azur</td><td>Deux #8 romanization</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n  <div class=\"lct\" id=\"lc-allusion\">\n    <div class=\"card\">\n      <h3>Philosophy in the items <span class=\"tag hot\">The allusions in names</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">Many items borrow philosophical or mythological concepts as names — a metaphor in itself.</p>\n      <ul class=\"tips\">\n        <li><b>Simulacrum</b>(melem #1) Baudrillard&#39;s theory — the copy replaces the real, the fake truer than truth; in the mirror room, \"you in the mirror\" is no longer you.</li>\n        <li><b>Logos</b>(melem #2, \"reason\") Greek philosophy&#39;s \"reason / word / cosmic order\"; the EN version renders \"reason\" as this very term.</li>\n        <li><b>Néant</b>(Deux #13) the core word of Sartre&#39;s <i>Being and Nothingness</i> — consciousness negating being; \"oblivious Néant\" = forgotten nothingness.</li>\n        <li><b>Chronos</b>(Deux #13) the Greek personification of time (often conflated with the child-devouring Titan Cronus); dropped into the time basket.</li>\n        <li><b>Psyche</b>(Deux #14, melem #1) Greek \"soul, breath\", symbolized by the butterfly, and the princess loved by Eros.</li>\n        <li><b>Aether</b>(By(e) #3) Aristotle&#39;s fifth element, the heavenly substance — holding up Heavenly Garden&#39;s \"heaven\".</li>\n<li><b>Zhuangzi&#39;s butterfly dream</b>(#14/#15) Zhuangzi dreamed he was a butterfly and woke unsure whether he was a man who dreamed a butterfly or a butterfly dreaming a man — real vs illusory, echoing Psyche (soul = butterfly) and melem&#39;s mirror/simulacrum. (Interpretive.)</li>\n        <li><b>Mirror-flower, water-moon</b>(melem #3) a Buddhist / East Asian idea: a flower in the mirror, a moon on the water — visible yet unattainable.</li>\n        <li><b>Impermanence · mono no aware</b>(By(e) overall) the Japanese sense of the fleeting — soap bubbles, falling sakura, fading all say the same thing.</li>\n        <li><b>Zero</b>(melem #1, Boundary Distortion → Zero) distortion pushed to zero: existence erased back into the void.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Myth &amp; literary allusions <span class=\"tag hot\">Sources</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 10px\">The myth or classic behind a name — basic and deep, in one entry.</p>\n      <details><summary>Omphale · Deux #6 male dress</summary>\n        <p>In Greek myth the queen of Lydia. Heracles was sold to her as a slave, wearing women&#39;s clothes and doing women&#39;s work while she wore his lion skin — a myth of <b>gender reversal</b>, the perfect male counterpart to \"Femme Fatale\".</p></details>\n      <details><summary>Giselle · Deux #14</summary>\n        <p>The Romantic ballet: a peasant girl dies of a broken heart and becomes a <b>Wili</b>, a night-spirit that dances men to death. Yet in Act II she <b>protects</b> her faithless lover instead, holding on until the dawn bell strips the Wilis of power — forgiveness over revenge. \"Giselle of the Void → The Heretical\" draws on this ghost-dancer.</p></details>\n      <details><summary>Psyche &amp; Eros · Deux #14 / melem #1</summary>\n        <p>Psyche is Greek for \"soul, breath\", symbolized by the <b>butterfly</b>, and the princess loved by Eros. Forbidden to see his face, she lit an <b>oil lamp</b> to look — a drop of oil woke him and he fled; after Aphrodite&#39;s trials she was made immortal and reunited with him. Hence the butterflies flooding #14.</p></details>\n      <details><summary>Anemone &amp; Adonis · By(e) #1</summary>\n        <p>The anemone bloomed from <b>Adonis&#39;s blood</b> and <b>Aphrodite&#39;s tears</b>; its flower language is \"brief love / forsaken hope\" — the root of the basket&#39;s fading beauty.</p></details>\n      <details><summary>Snow White · melem #4</summary>\n        <p>\"Mirror, Mirror on the Wall\", the poison apple, the queen&#39;s jealousy; \"the irreversible red fruit\" = once bitten, no way back.</p></details>\n      <details><summary>The passionflower · Deux #13</summary>\n        <p>The \"endless clock flower\" = the passionflower. Clock-face shaped, its Japanese name means \"clock plant\", dropping it into the time basket; its Western name <b>Passiflora</b> was coined by missionaries who read its parts as the <b>Passion of Christ</b> — filament corona = crown of thorns, five anthers = five wounds, three stigmas = three nails. A double pun.</p></details>\n      <details><summary>Orion · Deux #8</summary>\n        <p>The giant huntsman Orion of Greek myth, set in the sky as the constellation <b>Orion</b>; the star motif fits the \"star/night\" blue-rose basket.</p></details>\n      <details><summary>Camille / Camilla · the warrior in the name</summary>\n        <p>The name means \"attendant at a rite\", but in Virgil&#39;s Aeneid <b>Camilla</b> is a <b>virgin warrior</b> devoted to Diana, so swift she could skim over grain and water without a trace — echoing the fierce \"femme fatale\" Camille.</p></details>\n      <details><summary>Marguerite · also Faust&#39;s tragic heroine</summary>\n        <p>Beyond \"pearl / daisy\", Marguerite (Gretchen) is the tragic heroine of Goethe&#39;s <i>Faust</i> — seduced, ruined, then redeemed. (Connection is interpretive.)</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>What the colors mean <span class=\"tag ok\">Symbolism + traditional</span></h3>\n      <p class=\"cond\" style=\"margin:10px 0 4px\"><b>Common symbolism</b> (general cultural readings, for reference)</p>\n      <ul class=\"tips\">\n        <li><b>White</b>purity, innocence, blankness — also fading / death (By(e) garden, Deux white rose).</li>\n        <li><b>Black</b>darkness, mourning, the abyss — also elegance (melem base, Deux fallen angel).</li>\n        <li><b>Red / Crimson (Rouge)</b>blood, desire, the forbidden fruit (Deux ruby, melem poison apple).</li>\n        <li><b>Blue (Ciel · Azur)</b>melancholy, night, distance, dreams (Deux starlight / blue rose).</li>\n        <li><b>Purple</b>nobility, mystery, twilight (Deux gothic time).</li>\n        <li><b>Silver (Argent)</b>mirror, moon, coldness (melem).</li>\n      </ul>\n      <p class=\"cond\" style=\"margin:14px 0 4px\"><b>Traditional Japanese color names</b> (real historical colors, used in the wafū extras)</p>\n      <ul class=\"tips\">\n        <li><b>Shirotae</b>the pure white of bark-cloth, an ancient Man&#39;yōshū word for white.</li>\n        <li><b>Tsukishiro</b>a moon-white that actually leans pale blue despite the name.</li>\n        <li><b>Arazome</b>a very pale red (a faded red).</li>\n        <li><b>Kurotsurubami</b>a deep black dyed with acorns (tsurubami).</li>\n        <li><b>Haizakura · usukōri · usukō · usufuji</b>greyed cherry-pink, near-transparent cold white, soft incense hue and wisteria purple — together, a traditional color chart.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Music / theater / perfume terms <span class=\"tag ok\">Other bits</span></h3>\n      <ul class=\"tips\">\n        <li><b>Rondo</b>(Deux #8 Azure Rondo) a musical form whose theme keeps returning (ABACA).</li>\n        <li><b>Anthem</b>(melem #2 Anthem eyes) a song of praise or devotion.</li>\n        <li><b>Trance</b>(Deux #15 Moon Butterfly Trance) a hypnotic, dreamlike state.</li>\n        <li><b>Théâtre de Marionnettes</b>(Deux #13) Matinée = daytime show, Soirée = evening show — the day/night performances.</li>\n        <li><b>Sillage</b>(By(e) #3) a perfume term: the trail of scent left behind.</li>\n        <li><b>Sabon</b>= French savon (soap); <b>Cologne</b> comes from the German city <b>Köln</b>.</li>\n        <li><b>Côte d&#39;Azur</b>(Deux #8, Riviera + d&#39;Azur combined); <b>Orion</b> = the blue-rose black cat.</li>\n      </ul>\n    </div>\n  </div>\n  <div class=\"lct\" id=\"lc-story\">\n    <div class=\"card\">\n      <h3>Story arcs · read the whole brand together <span class=\"tag hot\">Narrative reading</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">One basket is just clothes; strung together, each brand tells a story (a community reading; parts are speculation).</p>\n      <details><summary>melem · the four-part dark fable</summary>\n        <p>Step by step, deeper into the mirror: <b>#1 Mirror</b> — you cross to the other side and meet the \"simulacrum\" of yourself; <b>#2 Crow &amp; cage</b> — reason is caged, the crow brings premonition and delusion; <b>#3 Lost sheep</b> — choose white guidance or black liberation; the innocent sheep is eclipsed into black; <b>#4 Poison apple</b> — Snow White&#39;s mirror, allure → erosion → jealousy, one bite of the red fruit and there&#39;s no return. Four baskets of a mirror-tale sinking ever deeper.</p></details>\n      <details><summary>Deux · dolls, souls, time</summary>\n        <p>Linked together it&#39;s a story about \"dolls\": the girls are really <b>dolls in cases</b> (#7 rose doll case → #14 butterfly doll case); they have <b>souls</b> (Âme #10, Psyche #14), they <b>fall</b> (#10 fallen angel), they&#39;re bound by <b>time</b> (#13 Chronos, past/present/future); and the butterfly = the soul, hinting at <b>rebirth</b>. The C.D/F.D family initials running through it read like the \"maker family\" behind the dolls. (An interpretive reading.)</p></details>\n      <details><summary>By(e) · a trilogy of withering</summary>\n        <p>All three baskets say \"beauty fades\": <b>#1 Anemone</b> — flower language \"brief love\", fade is the basket&#39;s verb; <b>#2 Rose in the rain</b> — a red bloom in a colorless city, a love too late; <b>#3 Heavenly Garden</b> — an \"eternal\" garden built, of all things, from bursting soap bubbles. The very name by(e) is a farewell.</p></details>\n    </div>\n    <div class=\"card\">\n      <h3>Art items hide a story <span class=\"tag hot\">Hidden narrative</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">The \"art\" items at the top of each basket aren&#39;t just decor — they&#39;re usually the <b>narrative thread</b>.</p>\n      <ul class=\"tips\">\n        <li><b>Deux · the doll-case motif</b>\"Silver Rose Doll Case\" (#7) → \"Butterfly Doll Case\" (#14) — echoing the <b>Doll series</b>: the girls are really dolls kept in cases.</li>\n        <li><b>Deux · family thread</b>#10 \"Book about a Family\" + \"Fallen Angel Tears\" signed Charlotte D. → #11 \"F.D-glass key\" → #14 \"C.D-Butterfly\" → #15 \"F.D-Papillon\", a family-initials thread across five baskets.</li>\n        <li><b>melem · every basket is a mirror</b>The Other Side of the Mirror (#1) → Gap of the Mirror (#2) → Boundary of Dream &amp; Reality (#3) → Mirror, Mirror (#4) — the art itself is about \"the mirror\".</li>\n        <li><b>By(e) · the fleeting freeze-frame</b>plant flower box / anemone wreath (#1), rose hotel window (#2), daydream ripple (#3) — all a moment you can&#39;t keep.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Each basket&#39;s \"text card\" = its thesis <span class=\"tag ok\">Lore card</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">Every basket hides one <b>text / brand card</b> among the art — that&#39;s where the theme is set.</p>\n      <ul class=\"tips\">\n        <li><b>Deux</b>#5 Yin-Yang Sakura Song (a waka), #6 Le rubis de Deux, #13 IMMORTAL CHRONOS.</li>\n        <li><b>melem</b>#1 Pittoresque \"behind the mirror\", #4 melem mirror.</li>\n        <li><b>By(e)</b>#1 Anemone Bouquet (with a flower-language verse), #2 ROSY DESIRE LULLABY (a lyric card).</li>\n      </ul>\n      <p class=\"fine\">Not sure what a basket is about? Find its text card — the origin of its naming and theme lives there.</p>\n    </div>\n    <div class=\"card\">\n      <h3>Deux&#39;s moon-phase &amp; time motif <span class=\"tag hot\">Throughline</span></h3>\n      <ul class=\"tips\">\n        <li><b>A full moon cycle</b>half-moon (#4) → the new-moon/full-moon pact (#12) → moon-ring (#13) → moon-night (#15).</li>\n        <li><b>#13 lays time bare</b>Chronos + past/present/future + the passionflower (clock-shaped) — the moonlight motif turns into \"time\" here.</li>\n      </ul>\n    </div>\n  </div>\n</div>\n", "sec-branddata": "\n  <div class=\"seg\" id=\"bdSeg\" style=\"margin-bottom:14px\">\n    <button class=\"on\" data-v=\"bd-deux\">Deux</button>\n    <button data-v=\"bd-melem\">melem</button>\n    <button data-v=\"bd-bye\">By(e)</button>\n    <button data-v=\"bd-rule\">Patterns</button>\n    <button data-v=\"bd-color\">Colors</button>\n    <button data-v=\"bd-stat\">Stats</button>\n  </div>\n\n  <div class=\"bdt show\" id=\"bd-deux\">\n    <div class=\"card\">\n      <h3>Deux basket list <span class=\"tag warn\">#4–#16</span></h3>\n      <table>\n        <thead><tr><th>#</th><th>Sale period</th><th>Palette · dye lines</th></tr></thead>\n        <tbody>\n          <tr><td class=\"num\">#4</td><td>2023/02/23–04/23</td><td>Icy blue-white<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">orig Ciel | dye Rose / Soirée / Sucre (+ Jaune, Blanc, Lune)</span></td></tr>\n          <tr><td class=\"num\">#5 ex</td><td>2023/03/24–05/28</td><td>Purple-black sakura · wafū<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">orig Evening / Midnight | dye Hazy / Memory (+ Remnant, Dawn, Clear, Violet, Ivory)</span></td></tr>\n          <tr><td class=\"num\">#6</td><td>2023/06/01–08/06</td><td>Red-black<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">orig Rouge | dye Noir / Azul / Verre (+ Phantom, Deep Blue, Lilac)</span></td></tr>\n          <tr><td class=\"num\">#7</td><td>2023/11/01–2024/01/07</td><td>Pure white<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">orig Perle · Ciel · Claire | dye Lilas / Pêche / Miel (+ Terre / Argent)</span></td></tr>\n          <tr><td class=\"num\">#8</td><td>2024/02/01–04/07</td><td>Blue-black<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">orig Blue (a quiet rose-blue; also Azure, Chagrin, Night) | dye Brandy / Rouge / Rose Black</span></td></tr>\n          <tr><td class=\"num\">#9</td><td>2024/02/23–04/28</td><td>Light blue & cream<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">orig Rêve (+ Ciel Bleu, Perle, Nobel) | dye Sleep / Yellow / Rose (+ Light, White, Peach)</span></td></tr>\n          <tr><td class=\"num\">#10</td><td>2024/08/01–10/06</td><td>Black-grey<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">orig Âme (+ Daylight, Vérité, Désarroi) | dye Shadow / Dawn / Destiny (+ Sun, Moon)</span></td></tr>\n          <tr><td class=\"num\">#11</td><td>2025/02/01–04/06</td><td>Ivory white<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">orig Larme (+ Nature, Fleurir, Soleil) | dye Opale / Lila / Fleur (+ Sky, Brulon)</span></td></tr>\n          <tr><td class=\"num\">#12 ex</td><td>2025/03/01–05/04</td><td>Black-white · moon-rabbit wafū<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">orig Nightglow (+ Black, White Gem, Guidance, Jet Black) | dye White Moon / Aster / Pale Grey (+ Pallid, White Porcelain, Light / Dark)</span></td></tr>\n          <tr><td class=\"num\">#13</td><td>2025/08/01–10/05</td><td>Dark purple<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">orig Chronos (+ Shackles, Soirée, Loin) | dye Crimson Lotus / Indigo / Moon Ring</span></td></tr>\n          <tr><td class=\"num\">#14</td><td>2026/02/01–04/05</td><td>Black-pink<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">orig Rosé (+ Bordeaux, Carman) | dye White / Indigo / Black (+ Grey, Blue, Amethyst)</span></td></tr>\n          <tr><td class=\"num\">#15 ex</td><td>2026/03/01–05/03</td><td>Pink-white · moonlit-butterfly wafū<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">orig White (+ Beige, Pale Wisteria, Daybreak) | dye Evening Dark / Water Moon / White Night (+ Grey Sakura, Pale Blue, Thin Ice)</span></td></tr>\n          <tr><td class=\"num\">#16</td><td>2026/08/01–10/04</td><td>Grey-white lace dollhouse<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">orig Solène / Altel (Silve; other dye colors not yet confirmed) | R eyes Radiant / Radian</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"fine\">All baskets end Sunday 22:59; launch time unified to 05:00 from mid-2023. ex＝extra edition. \"orig\"＝the SR dress&#39;s original-color name; <b>#4–#16 all verified</b> against the in-game original-color tabs. English names follow the in-game English glossary where available; the rest are unofficial fan translations. <span style=\"color:var(--rose)\">#16 is confirmed for character items, art items (19/19 collected), and sale period — other dye colors still to be filled in.</span></p>\n    </div>\n    <div class=\"card\">\n      <h3>Eye characters (pairs) <span class=\"tag ok\">Reference</span></h3>\n      <ul class=\"tips\">\n        <li><b>#4</b> Francine / Saintière　<b>#6</b> Louise / Louis + Camille / Samuel　<b>#7</b> Anne / Antoine</li>\n        <li><b>#8</b> Minette / Ansha + Riviera / d'Azur　<b>#9</b> Claris / Clement + Marguerite / Maximilian</li>\n        <li><b>#10</b> Inez / Raoul + René　<b>#12</b> Spring Night Fragment / Nito (the two rabbits)　<b>#13</b> History of Creation + Néant</li>\n        <li><b>#14</b> Jesvie / Giselle + Refret / Refretia　<b>#15</b> Hina / Hihina + Kawahirako</li>\n        <li><b>#16</b> Solène / Altel (SR) + Radiant / Radian (R)</li>\n        <li><b>Original → dyed eye prefixes</b>the table below lists each basket&#39;s eye-prefix shift.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Original → dyed prefixes <span class=\"tag ok\">Deux eyes</span></h3>\n      <table>\n        <thead><tr><th>Basket</th><th>SR eye: original → dye</th><th>R eye shift</th></tr></thead>\n        <tbody>\n          <tr><td class=\"num\">#4</td><td>Starlight → of Lunar Rainbow</td><td>—</td></tr>\n          <tr><td class=\"num\">#5</td><td>Night Sakura → Sakura</td><td>Love Pedal → Love Vapor</td></tr>\n          <tr><td class=\"num\">#6</td><td>Ruby → of the False</td><td>of Darkness → Flash of Light / of Silence</td></tr>\n          <tr><td class=\"num\">#7</td><td>Pure Lumière → Distant Lumière</td><td>Tranquille → Serene / Impartial</td></tr>\n          <tr><td class=\"num\">#8</td><td>Blue Rose → Dark Rose</td><td>Blooming in Silence → Sleeping / Blooming at Dawn</td></tr>\n          <tr><td class=\"num\">#9</td><td>Pale Sky → Faint Sunlight</td><td>Reminiscence → Silence / Foam</td></tr>\n          <tr><td class=\"num\">#10</td><td>Sky Night → Dawn</td><td>Night-Sky Light → Skylight / Wisdom</td></tr>\n          <tr><td class=\"num\">#11</td><td>Lit Morning Dew → Dew on Lit Leaves</td><td>—</td></tr>\n          <tr><td class=\"num\">#12</td><td>Spring Night → Rō Moonlit Night</td><td>Perpetual-Night Nito → Moonlit-Night Nito</td></tr>\n          <tr><td class=\"num\">#13</td><td>The Immortal Histoire → History of Creation</td><td>Oblivious Néant → Time-Light / Melancholy<br>Ash Gear Pipe → Platinum Gear Pipe</td></tr>\n          <tr><td class=\"num\">#14</td><td>Void → Heretic</td><td>Butterfly&#39;s → Papillon / Longing</td></tr>\n          <tr><td class=\"num\">#15</td><td>Moon-Shadow → Today&#39;s</td><td>—</td></tr>\n        </tbody>\n      </table>\n      <p class=\"fine\">Character names are unofficial fan translations.</p>\n    </div>\n    <div class=\"card\">\n      <h3>Fixed structure per basket <span class=\"tag gold\">Deux</span></h3>\n      <ul class=\"tips\">\n        <li><b>5 art items</b> (extra editions 6–7), including one brand text card.</li>\n        <li><b>SR dress</b>＝3 colors × M/F＝6 slots; <b>SR eyes</b>＝1 character pair ×2＝4 slots; <b>R eyes</b>＝another pair ×2＝4 slots.</li>\n        <li>R outfits use standalone color names outside the main lines; hairstyles are not dyeable and carry character names.</li>\n        <li>Hats/headpieces get all 3 colors; small accessories only 1–2; accessories also come in opposing duos (sun/moon, light/dark, future/past, day/night/dusk).</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"bdt\" id=\"bd-melem\">\n    <div class=\"card\">\n      <h3>melem basket list <span class=\"tag warn\">#1–#4</span></h3>\n      <table>\n        <thead><tr><th>#</th><th>Sale period</th><th>Theme</th></tr></thead>\n        <tbody>\n          <tr><td class=\"num\">#1</td><td>2023/08/18–10/22</td><td>Mirrors<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">palette: black / dark tones</span></td></tr>\n          <tr><td class=\"num\">#2</td><td>2023/12/01–2024/02/04</td><td>Crow · birdcage<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">palette: black / white</span></td></tr>\n          <tr><td class=\"num\">#3</td><td>2024/11/01–2025/01/05</td><td>Lost sheep<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">palette: black / white / rose</span></td></tr>\n          <tr><td class=\"num\">#4</td><td>2025/11/01–2026/01/04</td><td>Snow White · poison apple<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">palette: black / red</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"fine\">From #3 onward, fixed Nov 1 launch.</p>\n    </div>\n    <div class=\"card\">\n      <h3>Variant words <span class=\"tag ok\">3-stage decay</span></h3>\n      <ul class=\"tips\">\n        <li><b>#1</b>: Simulacrum / Illusion / Pieces; eyes＝Miloire of Mirror Abyss / of Separation; mirror versions all suffixed \"<b>: Mirror</b>\"</li>\n        <li><b>#2</b>: Erosion / Severance / Gloom; eyes＝Concealed / Everdark Anthem; from #2 mirror suffixes vary per item (Mirror / Premonition / Gloom / Reason / Gospel…)</li>\n        <li><b>#3</b>: Curtain / Foam / Fallen Petals · In Darkness / Shadow / In the Mist; eyes＝Shadowed / Eternally Lost Sheep</li>\n        <li><b>#4</b>: Crimson / Veil / Melting / Allure / Collapse; eyes＝Poison Apple's Erosion / Envy-Stained Poison Apple</li>\n        <li><b>Spotting originals</b>: originals use the base name with no suffix; only <b>Mirror-room versions</b> carry the variant-word suffix.</li>\n      </ul>\n      <p class=\"fine\">Variant names are unofficial fan translations.</p>\n    </div>\n    <div class=\"card\">\n      <h3>Fixed structure per basket <span class=\"tag gold\">melem</span></h3>\n      <ul class=\"tips\">\n        <li><b>The girls/boys tabs hold the suffix-free originals</b>; <b>the Mirror Room tab holds the suffixed mirror versions</b> (3-stage decay words). Original eyes: #1 \"Miloire of the Mirror\", #2 \"Another Sky&#39;s Anthem\", #3 \"Innocent Lost Sheep\", #4 \"Poison Apple Allure\". #3&#39;s mirror versions <b>invert white→black</b> (White Fiction → Black Fiction, White Haze → Black Haze, White Horns → Black Horns); #4&#39;s <b>invert black/silver→red</b> (Dark Mirror Sorcerer → Crimson Mirror Sorcerer, Argent Veil → Deep-Red Veil).</li>\n        <li>5 art items; category page fixed as <b>\"Mirror Room\"</b>, all items carry the Mirror tag.</li>\n        <li>Variants aren&#39;t colors but a <b>3-stage decay</b>: intact → veiled/eroded → shattered.</li>\n        <li>Eyes come in three fixed slots: SR adjectives ×2＋R ×1, same character with changing prefixes.</li>\n        <li>Always a numbered item <b>\"You in the Mirror\" 001→004</b> with no skips; hand items always split L/R.</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"bdt\" id=\"bd-bye\">\n    <div class=\"card\">\n      <h3>By(e) basket list <span class=\"tag warn\">#1–#3</span></h3>\n      <table>\n        <thead><tr><th>#</th><th>Sale period</th><th>Theme</th></tr></thead>\n        <tbody>\n          <tr><td class=\"num\">#1</td><td>2024/05/24–07/28</td><td>Anemone Bouquet<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">palette: white / beige / floral</span></td></tr>\n          <tr><td class=\"num\">#2</td><td>2025/05/09–07/13</td><td>Rose in the Rain · urban<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">palette: red / black</span></td></tr>\n          <tr><td class=\"num\">#3</td><td>2026/05/08–07/12</td><td>Heavenly Garden · soap flowers<br><span style=\"font-size:11.5px;color:var(--ink-soft)\">palette: white / silver</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"fine\">Fixed May launch, one basket per year; the launch date creeps earlier each year (05/24 → 05/09 → 05/08) — #4 expected <b>early May 2027</b>.</p>\n    </div>\n    <div class=\"card\">\n      <h3>Three lines & perfume cards <span class=\"tag ok\">3-line system</span></h3>\n      <ul class=\"tips\">\n        <li><b>#1</b>: faded magenta (Floral Eve) ＋ black (Noir Eden) ＋ citrus (Citrus Mellow)</li>\n        <li><b>#2</b>: aqua (Elegant Aqua) ＋ baby pink (Baby Rosy) ＋ woody (Essence Wood)</li>\n        <li><b>#3</b>: night black (Noir Eden) ＋ fairy multicolor (Fruity Fairy) ＋ green (Evergreen)</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Fixed structure per basket <span class=\"tag gold\">By(e)</span></h3>\n      <ul class=\"tips\">\n        <li><b>The girls/boys tabs hold the SCENT-FOR-YOU-tagged originals</b>; the perfume-items tab holds the three-line variants. Originals carry their own color words (#1: Tan, Coral Glow, Faded Romance; #2: Red, Crow, Spicy; #3: Pale Blue, Transparent, Soap).</li>\n        <li>Category page fixed as <b>\"Fragrance items\"</b>; the <b>only brand with makeup slots</b> (lips / blush / brows).</li>\n        <li><b>3-line system</b>: each line＝eyes＋lips＋blush (＋brows)＋one English perfume-name card.</li>\n        <li>The lead line gets the SR dress＋hairstyle; the third line is lightest (makeup only).</li>\n        <li>Old lines can be recycled and promoted: Noir Eden went from #1 side line → #3 lead line.</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"bdt\" id=\"bd-rule\">\n    <div class=\"card\">\n      <h3>Original vs dye — how to tell <span class=\"tag ok\">Quick check</span></h3>\n      <ul class=\"tips\">\n        <li>The color worn in the <b>big preview at the top</b> = the <b>original color</b> (official default).</li>\n        <li>The <b>other color thumbnails</b> in the grid = <b>dyeable versions</b>; the actual dyed color depends on the player.</li>\n        <li>Originals are usually <b>saturated or pure tones</b> (white, silver, black, deep red, pink); <b>SR items tend to have more dye options</b>.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Launch &amp; sale patterns <span class=\"tag gold\">Schedule</span></h3>\n      <ul class=\"tips\">\n        <li><b>~2-month sales</b>always ending <b>Sunday 22:59</b>; launch time unified to 05:00 from mid-2023.</li>\n        <li><b>Fixed months</b>Deux Feb–Mar (spring double) + Aug (Fate slot); By(e) May; melem fixed Nov 1 from #3.</li>\n        <li><b>Deux extra = March wafū</b>#5/#12/#15 are sakura/moon; spring doubles #4+#5, #8+#9, #11+#12, #14+#15, one light + one dark.</li>\n        <li><b>Category pages</b>Deux = Customization, melem = Mirror Room, By(e) = Fragrance items.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Item &amp; structure patterns <span class=\"tag ok\">Per basket</span></h3>\n      <ul class=\"tips\">\n        <li><b>29–30 items each</b>30 from Deux #12 and By(e) #2 on (#4 is also 30); melem stays 29.</li>\n        <li><b>Deux slots</b>#4 = 30, #5–#11 = 29, <b>fixed 30 from #12</b>.</li>\n        <li><b>Deux structure</b>5 art items (6–7 in extras with a text card), SR dress ×3 colors ×2 genders, one character pair each for SR/R eyes, hairs named after characters (no dye).</li>\n        <li><b>melem structure</b>eyes in three tiers (SR ×2 + R ×1, same character); a serial \"You in the Mirror\"; hands split L/R.</li>\n        <li><b>By(e) structure</b>three lines (cool/warm/earthy), each = eyes + lips + blush (+ brows) + an EN perfume card; the only brand with makeup.</li>\n              <li><b>Rarity</b>SR (rainbow tag) &gt; R (gold tag) &gt; N; SR items usually have the most dye options.</li>\n        <li><b>Three versions + count</b>each basket splits into Art (unisex) / Female / Male; the top-right \"Collection X/Y\" is your completion.</li>\n</ul>\n    </div>\n    <div class=\"card\">\n      <h3>Naming &amp; pairing patterns <span class=\"tag ok\">Eggs</span></h3>\n      <ul class=\"tips\">\n        <li><b>Deux pairs everything</b>items, eye characters, hairs, word order all pair by gender (Yvette/Yverre, Hiina/Hihina, Anne Tranquille/Tranquility Antoine).</li>\n        <li><b>melem serial</b>\"You in the Mirror\" 001→004 walks all four baskets (spaced from #3).</li>\n        <li><b>By(e) accord naming</b>line names are all accords (Floral Eve, Citrus Mellow, Elegant Aqua…); old lines get promoted (Noir Eden #1→#3 lead).</li>\n              <li><b>Hands always split L/R</b>; melem #2 also pairs Girl/Boy.</li>\n</ul>\n      <p class=\"fine\">Compiled from actual records; for reference only — schedules follow official announcements.</p>\n    </div>\n  </div>\n  <div class=\"bdt\" id=\"bd-color\">\n    <div class=\"card\">\n      <h3>Original color usage <span class=\"tag hot\">Approx. share</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">Distribution of each set&#39;s <b>original (preview) color</b> (estimated, not official).</p>\n      <div class=\"cbar\"><div class=\"lbl\"><b>White · dreamy / pure staple</b><span class=\"pct\">35–40%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:38%;background:linear-gradient(90deg,#e8e4f0,#cfc7e6)\"></div></div></div>\n      <div class=\"cbar\"><div class=\"lbl\"><b>Black · dark / mystery core</b><span class=\"pct\">25–30%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:28%;background:linear-gradient(90deg,#8a86a0,#4a4560)\"></div></div></div>\n      <div class=\"cbar\"><div class=\"lbl\"><b>Red/pink · rose / butterfly</b><span class=\"pct\">15–20%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:18%;background:linear-gradient(90deg,#f3c3d4,#e0728f)\"></div></div></div>\n      <div class=\"cbar\"><div class=\"lbl\"><b>Blue/purple · night / floral</b><span class=\"pct\">12–18%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:15%;background:linear-gradient(90deg,#b9c4e8,#6f7fd0)\"></div></div></div>\n      <div class=\"cbar\"><div class=\"lbl\"><b>Other · gold-silver / light FX</b><span class=\"pct\">5–8%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:7%;background:linear-gradient(90deg,#ecd9a8,#cbb26a)\"></div></div></div>\n    </div>\n    <div class=\"card\">\n      <h3>Dyeable color spread <span class=\"tag hot\">Screenshot-verified</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 12px\">From 19 sets of in-game screenshots — the color-family spread of each basket&#39;s main dye trio + key accents. <b>Dyeing widens the palette</b>, with far more blue / purple / warm than the originals.</p>\n      <div class=\"cbar\"><div class=\"lbl\"><b>White · silver</b><span class=\"pct\">~24%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:24%;background:linear-gradient(90deg,#e8e4f0,#cfc7e6)\"></div></div></div>\n      <div class=\"cbar\"><div class=\"lbl\"><b>Black · grey</b><span class=\"pct\">~19%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:19%;background:linear-gradient(90deg,#8a86a0,#4a4560)\"></div></div></div>\n      <div class=\"cbar\"><div class=\"lbl\"><b>Blue</b><span class=\"pct\">~15%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:15%;background:linear-gradient(90deg,#b9c4e8,#6f7fd0)\"></div></div></div>\n      <div class=\"cbar\"><div class=\"lbl\"><b>Red · pink</b><span class=\"pct\">~14%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:14%;background:linear-gradient(90deg,#f3c3d4,#e0728f)\"></div></div></div>\n      <div class=\"cbar\"><div class=\"lbl\"><b>Purple</b><span class=\"pct\">~13%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:13%;background:linear-gradient(90deg,#d3c0e6,#9a6fc0)\"></div></div></div>\n      <div class=\"cbar\"><div class=\"lbl\"><b>Warm · brown · yellow</b><span class=\"pct\">~12%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:12%;background:linear-gradient(90deg,#ecd9a8,#cb9a5a)\"></div></div></div>\n      <div class=\"cbar\"><div class=\"lbl\"><b>Green</b><span class=\"pct\">~2%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:2%;background:linear-gradient(90deg,#bfe0c0,#6fae74)\"></div></div></div>\n      <div class=\"cbar\"><div class=\"lbl\"><b>Fairy · other</b><span class=\"pct\">~1%</span></div><div class=\"track\"><div class=\"fill\" style=\"width:1%;background:linear-gradient(90deg,#e6d0f0,#c08fd0)\"></div></div></div>\n      <p class=\"fine\">Black is higher than first estimated — melem&#39;s four baskets are all black, By(e)&#39;s Noir Eden recurs, and many Deux baskets have black dyes (Noir / rose-black / shadow / black-jade / dusk…).</p>\n    </div>\n    <div class=\"card\">\n      <h3>Original vs dyeable <span class=\"tag ok\">Side by side</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 10px\">Share of each color family as original vs dyeable; the arrow shows the shift after dyeing.</p>\n      <table>\n        <thead><tr><th>Family</th><th>Original</th><th>Dyeable</th><th>Shift</th></tr></thead>\n        <tbody>\n          <tr><td>White · silver</td><td>35–40%</td><td>~24%</td><td>▼ down</td></tr>\n          <tr><td>Black · grey</td><td>25–30%</td><td>~19%</td><td>▼ down</td></tr>\n          <tr><td>Red · pink</td><td>15–20%</td><td>~14%</td><td>≈ level</td></tr>\n          <tr><td>Blue</td><td rowspan=\"2\" style=\"vertical-align:middle\">12–18%<br><span style=\"font-size:11px;color:var(--ink-soft)\">(blue+purple)</span></td><td>~15%</td><td>▲ up</td></tr>\n          <tr><td>Purple</td><td>~13%</td><td>▲ up</td></tr>\n          <tr><td>Warm · brown · yellow</td><td>5–8%<br><span style=\"font-size:11px;color:var(--ink-soft)\">(with others)</span></td><td>~12%</td><td>▲ way up</td></tr>\n          <tr><td>Green</td><td>—</td><td>~2%</td><td>▲ new</td></tr>\n        </tbody>\n      </table>\n      <p class=\"fine\">Takeaway: originals cluster in white/black (showcase), while dyeing pours in <b>blue, purple and warm</b> — the palette you can actually build. Figures compiled from in-game screenshots.</p>\n    </div>\n    <div class=\"card\">\n      <h3>Each basket&#39;s main dyes (verified) <span class=\"tag warn\">Deux trios</span></h3>\n      <p class=\"cond\" style=\"margin:2px 0 10px\">The three-color dye line of each SR main dress (from in-game screenshots).</p>\n      <table>\n        <thead><tr><th>Basket</th><th>Main dye trio</th></tr></thead>\n        <tbody>\n          <tr><td class=\"num\">#4</td><td>Rose / Dusk / Sugar</td></tr>\n          <tr><td class=\"num\">#5</td><td>Haze / Memory / Faded-sakura</td></tr>\n          <tr><td class=\"num\">#6</td><td>Noir / Sky-blue / Veil</td></tr>\n          <tr><td class=\"num\">#7</td><td>Lilac / Peach / Honey</td></tr>\n          <tr><td class=\"num\">#8</td><td>Brandy / Rouge / Rose-black</td></tr>\n          <tr><td class=\"num\">#9</td><td>Sleep / Yellow / Rose</td></tr>\n          <tr><td class=\"num\">#10</td><td>Shadow / Dawn / Fate</td></tr>\n          <tr><td class=\"num\">#11</td><td>Opal / Lila / Fleur</td></tr>\n          <tr><td class=\"num\">#12</td><td>White-moon / Grey-mouse / Aster</td></tr>\n          <tr><td class=\"num\">#13</td><td>Red-lotus / Blue / Moon-ring</td></tr>\n          <tr><td class=\"num\">#14</td><td>White / Blue / Black</td></tr>\n          <tr><td class=\"num\">#15</td><td>Dusk-dark / Water-moon / White-night</td></tr>\n        </tbody>\n      </table>\n      <p class=\"fine\">melem&#39;s mirror room is mostly black/white/grey, with crimson first in #4; By(e)&#39;s three lines are under \"Brand data → By(e)\".</p>\n    </div>\n    <div class=\"card\">\n      <h3>Each brand&#39;s dye strategy <span class=\"tag ok\">Color rules</span></h3>\n      <ul class=\"tips\">\n        <li><b>Deux · light↔dark</b>strict alternation; back-to-back darks only between \"extra→summer\" or \"summer→next Feb\"; spring doubles are always one light + one dark.</li>\n        <li><b>Deux · hue rotation</b>no hue runs more than two baskets; red appeared once (#6, 2023); blue&#39;s era ended in 2024 — since then achromatic + purple + pink.</li>\n        <li><b>melem · accent grows in</b>base is forever black/white/grey — #1/#2 pure achromatic, #3 faint accents, #4 first saturated red.</li>\n        <li><b>By(e) · stable trio</b>of nine lines only black (Noir Eden) repeats; each basket is cool/warm/earthy; cover color can diverge from contents (#2 red cover, blue-pink-brown inside).</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Color timeline <span class=\"tag hot\">Trend</span></h3>\n      <ul class=\"timeline\">\n        <li><b>2023</b>light / pink / red — Deux starlight, white rose; ruby the lone red slot.</li>\n        <li><b>2024</b>blue / black / floral — blue rose &amp; cream lead; melem&#39;s crow brings black.</li>\n        <li><b>2025</b>white butterflies / dark purple — dew, moon rabbits, gothic time turn deep.</li>\n        <li><b>2026</b>pink butterflies / light — butterflies &amp; roses, moon-night butterflies; the butterfly becomes the new motif.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Motif evolution <span class=\"tag ok\">Recurring themes</span></h3>\n      <ul class=\"tips\">\n        <li><b>Moonlight</b>runs through all of Deux (Lune / Starlight / moon rabbits / moon-night butterflies).</li>\n        <li><b>Roses</b>the 2023–2024 staple (ruby, blue rose, white rose, By(e) rose rain).</li>\n        <li><b>Butterflies</b>the new 2026 motif (Psyche → #14/#15 flooded with butterflies).</li>\n        <li><b>Mirror / shadow</b>melem&#39;s own — the dark fable across four baskets.</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"bdt\" id=\"bd-stat\">\n    <div class=\"card\">\n      <h3>Overview numbers <span class=\"tag ok\">Stats</span></h3>\n      <div class=\"row\"><span>Total sets</span><span class=\"r t\">19 (Deux 12＋melem 4＋By(e) 3)</span></div>\n      <div class=\"row\"><span>Time span</span><span class=\"r t\">2023/02–2026/06</span></div>\n      <div class=\"row\"><span>Items per basket</span><span class=\"r t\">29–30</span></div>\n      <div class=\"row\"><span>Launch months</span><span class=\"r t\">Feb·Mar·May·Aug·Nov</span></div>\n    </div>\n    <div class=\"card\">\n      <h3>Brand positioning <span class=\"tag gold\">In a line</span></h3>\n      <ul class=\"tips\">\n        <li><b>Deux</b>longest-lived, most versatile — light/dark + deep customization, every classic motif (moonlight, rose, butterfly, light).</li>\n        <li><b>melem</b>the dark-style flagship — most unified, black-white-grey base, gothic theater; #4 introduces its first saturated red.</li>\n        <li><b>By(e)</b>elegant florals — bouquet / garden / rose-rain themes, white + accent, the only one with makeup.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h3>Value trend <span class=\"tag hot\">Resale</span></h3>\n      <ul class=\"tips\">\n        <li><b>No reruns = older is pricier</b>#4 is the intl server&#39;s first brand basket and the priciest.</li>\n        <li><b>Dilution after more brands</b>from #7 on, per-basket value sits below #4/#5 — but still appreciates over time.</li>\n        <li><b>Candle dyes expire</b>melem&#39;s discontinued dyes are usually worth more the older they are.</li>\n      </ul>\n      <p class=\"fine\">Player observations, for reference only — actual values follow official info &amp; the market.</p>\n    </div>\n  </div>\n", "sec-feedback": "\n  <div class=\"card\" style=\"text-align:center\">\n    <h3 style=\"justify-content:center\">Feedback <span class=\"tag warn\">Contact</span></h3>\n    <p class=\"cond\" style=\"font-size:14.5px\">Want to <b>add a rule</b> or <b>spotted a mistake</b>? DM on Instagram:</p>\n    <a class=\"ig-btn\" href=\"https://www.instagram.com/diana0520_art?igsh=MWZoajRvM3c5enUyZw==\" target=\"_blank\" rel=\"noopener\">📷 @diana0520_art</a>\n    <img class=\"ig-qr\" src=\"data:image/jpeg;base64,\" alt=\"Instagram QR code\">\n    <p class=\"fine\">Tap the button or scan the QR code to open Instagram.</p>\n  </div>\n"};
